window.PF_DATA_prestige = {"meta":{"category":"prestige","count":27,"generatedAt":"2026-11-18T15:57:31Z","source":"https://pathfinder.family"},"prestige":[{"book":"Adventurer's Guide","classSkills":["Акробатика","Блеф","Дипломатия","Запугивание","Знание (высший свет)","Исполнение","Проницательность"],"features":[{"description":"Повелитель меча Алдори может добавить свой модификатор Ловкости к броскам атаки при ударе дуэльным мечом Алдори вместо модификатор Силы. Этот бонус применяется вне зависимости от того, держит ли герой клинок в одной или обеих руках. Повелитель меча Алдори не может использовать эту способность, если орудует щитом или другим дополнительным оружием (включая шипы на броне, безоружный удар и естественное оружие).","name":"Проворный удар (Экс)"},{"description":"Повелитель меча Алдори получает Быстрое выхватывание как дополнительную черту. Если у персонажа уже имеется эта черта, то он получает Дуэльный мастер Алдори. Если он уже имеет обе эти черты, он получает любую боевую черту по своему выбору, однако он должен соответствовать её условиям.","name":"Быстрое выхватывание"},{"description":"На 2-ом уровне, Повелитель меча Алдори добавляет бонус равный половине его уровня в этом классе к проверкам Запугивания во время применения Демонстрации силы с дуэльным мечом Алдори в руках. Он также получает дополнительный бонус +1 к этим проверкам Запугивания за каждую из следующих черт, которые он взял с дуэльным мечом Алдори: Уверенное владение оружием+, Привычное оружие+, Улучшенный критический удар, Уверенное владение оружием или Привычное оружие. Бонусы складываются между собой (общий бонус является бонусом мастерства). Когда Повелитель меча Алдори находится в дуэли, его мастерство искусных ударов и стоек гарантирует ему бонус равный половине его уровня в классе на проверки боевого выступления. Эти трюки также отлично помогут парировать атаки противника во время дуэли, давая при этом бонус равный половине его уровня в классе на броски попыток дуэльного парирования или использование решения дуэли.","name":"Демонстрация оружейного мастерства (Экс)"},{"description":"На 3-ем уровне, Повелитель меча Алдори получает бонус +1 уклонения к его КБ, когда совершает атаку полного хода с дуэльным мечом Алдори в руках. Этот бонус увеличивается до +2 на 7-ом уровне. Если дуэлянт Алдори к тому же является воином с архетипом Защитник Алдори, то уровни этого класса складываются с его уровнями воина для расчёта бонуса к КБ от этой способности.","name":"Защитное парирование (Экс)"},{"description":"На 4-ом уровне, Повелитель меча Алдори учится подстраивать свой боевой стиль под сильные стороны противника. Повелитель меча Алдори уменьшает штраф к атаке за сражение в защите или за использование Защитной стойки на 1 на 4-ом уровне, и на 2 на 8-ом уровне. Ко всему прочему, когда Повелитель меча Алдори использует дуэльный меч Алдори для атаки существа, которое он атаковал в предыдущем раунде, он может пройти проверку Проницательности в качестве быстрого действия (СЛ = 10 + БМА существа). При успехе, герой получает бонус обстоятельств +2 либо к броскам атаки, либо к КБ против этого же существа до начала своего следующего хода.","name":"Адаптивная тактика (Экс)"},{"description":"На 5-ом уровне Повелитель меча Алдори может пройти проверку Запугивания, чтобы деморализовать цель в качестве быстрого действия после успешной критической атаки или манёвра разоружения, перемещения или разрушения с помощью дуэльного меча Алдори. Если его цель уже потрясена, мечник может пройти проверку Запугивания для деморализации цели в качестве быстрого действия после любой успешной атаки или боевого манёвра. Если он проходит проверку, цель теряет все бонусы морали на количество раундов, равное уровню престиж-класса Повелитель меча Алдори. Потерянные бонусы морали не исчезают, и вновь появляются у цели, если их время не истекло. Потерянные бонусы морали включат в себя и Ярость варвара; однако, эта способность не отключает ярость и её эффекты вместе с дарами, которые не дают бонусов морали (то есть, это не утомляет варвара пока он не решит закончить действие ярости во время действия способности мечника Алдори: в этом случае усталость действует на варвара по обычным правилам).","name":"Сломленная уверенность (Экс)"},{"description":"На 6-ом уровне, когда Повелитель меча Алдори держит в руках дуэльный меч Алдори, он может попытаться отразить критический удар в ближнем бою, направленный на него, прерывающим действием, уменьшая его урон до урона обычного удара с шансом 25% на успех. Этот эффект не складывается с эффектом укреплённый магической брони и похожими эффектами.","name":"Спасительный разрез (Экс)"},{"description":"На 7-ом уровне, если у Повелителя меча Алдори есть хотя бы одна свободная рука, он не отнимает свой бонус Ловкости при проверке Акробатики или Лазания, и не провоцирует внеочередные атаки при попытке подняться с земли.","name":"Ловкий дуэлянт (Экс)"},{"description":"На 9-ом уровне, Спасительный разрез Повелителя меча Алдори имеет 50% шанс снижения критического удара до обычного. В дополнение, он может попытаться совершить Спасительный разрез от критических дальних атак, включая лучи и иные типы касательных атак, с 25% шансом на успех.","name":"Улучшенный спасительный разрез (Экс)"},{"description":"На 10-ом уровне, Повелитель меча Алдори, который успешно использовал Сломленную уверенность, также отнимает у цели бонусы мастерства и интуитивные бонусы.","name":"Сбивающий с толку дуэлянт (Экс)"}],"hitDie":"d10","kind":"prestige","nameEn":"Aldori Swordlord","nameRu":"Повелитель Меча Алдори","originalUrl":"https://pathfinder.family/class/prestige/aldoriSwordlord","progression":[{"bab":"+1","fort":"+0","level":1,"ref":"+1","special":"Проворный удар, Быстрое выхватывание","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Демонстрация оружейного мастерства","will":"+1"},{"bab":"+3","fort":"+1","level":3,"ref":"+2","special":"Защитное парирование +1","will":"+1"},{"bab":"+4","fort":"+1","level":4,"ref":"+2","special":"Адаптивная тактика 1","will":"+1"},{"bab":"+5","fort":"+2","level":5,"ref":"+3","special":"Сломленная уверенность","will":"+2"},{"bab":"+6","fort":"+2","level":6,"ref":"+3","special":"Спасительный разрез","will":"+2"},{"bab":"+7","fort":"+2","level":7,"ref":"+4","special":"Защитное парирование +2, Ловкий дуэлянт","will":"+2"},{"bab":"+8","fort":"+3","level":8,"ref":"+4","special":"Адаптивная тактика 2","will":"+3"},{"bab":"+9","fort":"+3","level":9,"ref":"+5","special":"Улучшенный спасительный разрез","will":"+3"},{"bab":"+10","fort":"+3","level":10,"ref":"+5","special":"Сбивающий с толку дуэлянт","will":"+3"}],"requirements":[{"kind":"Черты","text":"Демонстрация силы, Обращение с экзотическим оружием (дуэльный меч Алдори), Фехтование, Уверенное владение оружием (дуэльный меч Алдори)."},{"kind":"Навыки","text":"Акробатика 3, Запугивание 5, Знание (высший свет) 3, Проницательность 3."}],"skillRanks":"2 + Инт","slug":"aldoriSwordlord"},{"alignment":"Мистические лучники могут иметь любое мировоззрение. Эльфы и полуэльфы из их числа более склонны к свободомыслию и редко придерживаются принципиальных взглядов. Кроме того, среди мистических лучников эльфийских кровей не так много злодеев, так что чаще всего на этот путь встают добрые или нейтральные персонажи.","book":"Core Rulebook","classSkills":["Верховая езда","Внимание","Выживание","Скрытность"],"features":[{"description":"Мистические лучники умеют обращаться со всеми видами простого и особого оружия, со щитами, а также легкими и средними доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"На определенных уровнях персонаж получает дополнитедьные заклинания в день, как если бы он получил уровень в том классе мистического заклинателя, который у него был до взятия престиж-класса. Он не получает иных преимуществ от того класса, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у мистического лучника до получения престиж-класса было несколько классов, дающих доступ к мистическим заклинаниям, он должен выбрать, к какому из классов он будет добавдять уровни для определения количества заклинаний в день.","name":"Заклинания в день"},{"description":"На 1 уровне любая немагическая стрела, выпущенная мистическим лучником, становится магической и получает +1 (усиление) к атаке и урону. В отличие от магического оружия, создаваемого по обычным правилам, стрелы мистического лучника получают бонус без денежных затрат, но только если он выпускает их собственноручно. По мере получения новых уровней сила волшебных стрел мистического лучника растет. Стихийные и мировоззренческие свойства волшебных стрел (см. далее) мистический лучник может сменить раз в день, когда пополняет список подготовленных заклинаний или (если он спонтанный заклинатель) после полноценного восьмичасового отдыха. На 3 уровне любая немагическая стрела, которую мистический лучник выпускает из своего лука, получает одно из стихийных свойств: огненная, ледяная или грозы. На 5 уровне любая немагическая стрела, которую мистический лучник выпускает из своего лука, получает свойство дальнобойная. На 7 уровне любая немагическая стрела, которую мистический лучник выпускает из своего лука, получает одно из стихийных свойств: огненный взрыв, ледяной взрыв или грозовой взрыв. Эта особенность заменяет собой соответствующую особенность 3 уровня. На 9 уровне любая немагическая стрела, которую мистический лучник выпускает из своего лука, получает одно из мировоззренческих свойств: бунтарская, праведная, священная или нечестнвая. Мистический лучник не может выбрать свойство, противоположное его собственному мировоззрению (так, принципиальный добрый мистический лучник не сможет сделать свои волшебные стрелы ни бунтарскими, ни нечестивымы). Бонусы, которые обеспечивает волшебный лук, действуют на волшебные стрелы как обычно. Применяется лишь наибольший бонус усиления. Повторяющиеся свойства не складываются.","name":"Вошебные стрелы (Св)"},{"description":"На 2 уровне мистический лучник получает возможность поместить заклинание, бьющее по области, на выпущенную стрелу. Заклинание при этом срабатывает там, куда попадает стрела, а его дистанция заменяется дистанцией оружия мистического лучника. При промахе заклинание потрачено впустую. Время сотворения заклинания при этом не изменяется, а выстрел из лука становится завершающей частью этого процесса. Стрелу следует выпустить в тот же раунд, когда было сотворено заклинание, иначе оно считается потраченным впустую.","name":"Заколдованная стрела (Св)"},{"description":"На 4 уровне мистический лучник получает возможность выпустить стрелу в любую известную ему цель, находящуюся в пределах дистанции поражения его оружия - это единственное ограничение. Выпущенная стрела самостоятельно находит свою цель, огибая оказавшиеся у нее на пути препятствия; единственное, что может остановить ее полет, - это непреодолимое препятствие вроде глухой каменной стены. На этот выстрел не влияют модификаторы за укрытие и вероятность промаха из-за плохой видимости, но в остальном атака совершается по обычным правилам. Применение этой способности - основное действие (частью которого служит выстрел из лука). Мистический лучник может использовать эту способность один раз в день на 4 уровне и еще один раз в день дополнительно за каждые два уровня после 4, вплоть до максимума в четыре раза в день на 10 уровне.","name":"Самонаводящаяся стрела (Св)"},{"description":"На 6 уровне мистический лучник получает возможность выпустить стрелу в любую известную ему цель, находящуюся в пределах дистанции поражения его оружия - это единственное ограничение. Выпущенная стрела самостоятельно находит цель, двигаясь в ее направдении сквозь любые немагические препятствия, стены и т. п. (любой магический барьер, однако, останавливает ее полет). На этот выстрел не влияют модификаторы за укрытие, броню, щит и вероятность промаха из-за плохой видимости, но в остальном атака совершается по обычным правилам. Применение этой способности - основное действие (частью которого служит выстрел из лука). Мистический лучник может использовать эту способность один раз в день на 6 уровне и еще один раз в день дополнительно за каждые два уровня после 6, вплоть до максимума в три раза в день на 10 уровне.","name":"Неостановимая стрела (Св)"},{"description":"Раз в день вместо своей основной атаки мистический лучник 8 уровня получает возможность выпустить по стреле в каждого из врагов, находящихся в пределах дистанции поражения его оружия, вплоть до максимума в одного врага за каждый уровень класса мистического лучника. Каждая атака совершается с наивысшим БМА лучника, но каждый из врагов может стать мишенью только для одной стрелы.","name":"Град стрел (Св)"},{"description":"На 10 уровне мистический лучник может создать особую стрелу истребления. Существо, которому эта стрела причинит хотя бы 1 пункт урона, должно немедленно пройти испытание Стойкости и в случае провала умереть. СЛ этого испытания равна 20 + модификатор Харизмы мистического лучника. Процесс создания стрелы истребления длится один день, и действует она, только если ее выпускает из лука сам мистический лучник. Магия стрелы истребления полностью рассеивается через год. Одновременно у мистического лучника может быть только одна такая стрела.","name":"Стрела смерти (Св)"}],"hitDie":"d10","kind":"prestige","nameRu":"Мистический лучник","originalUrl":"https://pathfinder.family/class/prestige/arcaneArcher","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+1","special":"Волшебные стрелы (+1)","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Заколдованная стрела","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+2","special":"Волшебные стрелы (стихийные)","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+4","fort":"+2","level":4,"ref":"+2","special":"Самонаводящаяся стрела","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+5","fort":"+3","level":5,"ref":"+3","special":"Волшебные стрелы (дальнобойные)","will":"+2"},{"bab":"+6","fort":"+3","level":6,"ref":"+3","special":"Неостановимая стрела","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+7","fort":"+4","level":7,"ref":"+4","special":"Волшебные стрелы (стихийный взрыв)","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+8","fort":"+4","level":8,"ref":"+4","special":"Град стрел","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+9","fort":"+5","level":9,"ref":"+5","special":"Волшебные стрелы (мировоззренческие)","will":"+3"},{"bab":"+10","fort":"+5","level":10,"ref":"+5","special":"Стрела смерти","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"}],"requirements":[{"kind":"Базовый модификатор атаки","text":"+6."},{"kind":"Черты","text":"Стрельба вблизи, Прицельная стрельба, Уверенное владение оружием (длинный или короткий лук)."},{"kind":"Заклинания","text":"Способность творить мистические заклинания 1 круга."}],"role":"Мистический лучник несет смерть издалека, уничтожая врагов, пока его союзники сражаются с ними в ближнем бою. Его вклад в победу - град бьющих без промаха стрел. Этот класс - вершина развития искусства дальнего боя.","skillRanks":"4 + Инт","slug":"arcaneArcher"},{"alignment":"Все мистические трикстеры - знатные пройдохи и бедокуры, которые зарабатывают на жизнь воровством, так что среди них нет личностей, обремененных принципиальным мировоззрением. Хотя порой волшебники, любящие корпеть над книгами, и становятся мистическими трикстерами, больше всего среди них чародеев, придерживающихся хаотичного мировоззрения.","book":"Core Rulebook","classSkills":["Акробатика","Блеф","Внимание","Дипломатия","Знание (высший свет)","Знание (география)","Знание (инженерное дело)","Знание (история)","Знание (краеведение)","Знание (магия)","Знание (планы)","Знание (подземелья)","Знание (природа)","Знание (религия)","Изворотливость","Колдовство","Лазание","Ловкость рук","Маскировка","Механика","Оценка","Проницательность","Скрытность"],"features":[{"description":"Мистические трикстеры не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"На определенных уровнях персонаж получает дополнительные заклинания в день, как если бы он получил уровень в том классе заклинателя, который у него был до взятия престиж-класса. Он не получает иных преимуществ от того класса, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у мистического трикстера до получения престиж-класса было несколько классов, дающих доступ к заклинаниям, он должен выбрать, к какому из классов он будет добавлять уровни для определения количества заклинаний в день.","name":"Заклинания в день"},{"description":"Мистический трикстер может применять Механику и Ловкость рук на расстоянии до 30 футов. При этом СЛ задачи увеличивается на 5, а брать результат 10 без броска кости нельзя. Объект, которым собирается манипулировать трикстер, должен весить не более 5 фунтов. Трикстер может использовать эту способность, только если у него есть хотя бы 1 пункт в соответствующем навыке.","name":"Дистанционный трюк (Св)"},{"description":"Эта способность работает точно так же, как одноименная способность плута. Наносимый при помощи нее урон увеличивается на +1d6 на каждом втором уровне мистического трикстера (т. е. на 2, 4, 6, 8 и 10). Если у него уже есть модификаторы за атаку исподтишка, они складываются.","name":"Атака исподтишка"},{"description":"Начиная с 3 уровня один раз в день мистический трикстер может объявить одну свою атаку (ближнего боя или дистанционную) атакой исподтишка (если атака дистанционная, ее цель должна находиться в пределах 30 футов от трикстера). Цель импровизированной атаки исподтишка не учитывает свой положительный модификатор Ловкости к КБ для этой атаки. Эта способность может быть использована против любой цели, но существа, невосприимчивые к критическим ударам, не получат дополнительного урона (хотя и они лишаются своего положительного модификатора Ловкости к КБ). Начиная с 7 уровня, мистический трикстер может применять эту способность дважды в день.","name":"Импровизированная атака исподтишка (Экс)"},{"description":"Начиная с 5 уровня мистический трикстер получает возможность творить заклинания без словесных и жестовых компонентов, как при использовании черт Безжестовое заклинание и Безмолвное заклинание, за исключением того, что время прочтения и круг этих заклинаний остаются неизменными. Трикстер может использовать эту способность трижды в день на 5 уровне и еще один раз в день доподнительно за каждые два уровня после 5 вплоть до максимума в пять раз в день на 9 уровне.","name":"Ловкий трюк (Св)"},{"description":"Начиная с 9 уровня мистический трикстер может становиться невидимым (свободное действие), как если бы находился под действием заклинания высшая невидимость. В день он может быть невидимым количество раундов, равное его уровню мистического трикстера. Эти раунды необязательно должны идти подряд.","name":"Невидимый вор (Св)"},{"description":"На 10 уровне мистический трикстер может прибавить урон своей атаки исподтишка к урону любого своего заклинания, если цели этого заклинания застигнуты врасплох. Это заклинание должно наносить своей цели прямой урон, а тип урона от атаки исподтишка будет полностью соответствовать типу урона от самого заклинания. Если заклинание подразумевает испытание, в результате которого цель может получить только половину урона (или не получить его вовсе), то это касается и урона от атаки исподтишка.","name":"Подлое заклинание"}],"hitDie":"d6","kind":"prestige","nameRu":"Мистический трикстер","originalUrl":"https://pathfinder.family/class/prestige/arcaneTrickster","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Дистанционный трюк","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Атака исподтишка +1d6","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":3,"ref":"+2","special":"Импровизированная атака исподтишка 1/день","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+1","level":4,"ref":"+2","special":"Атака исподтишка +2d6","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+2","level":5,"ref":"+3","special":"Ловкий трюк 3/день","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":6,"ref":"+3","special":"Атака исподтишка +3d6","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":7,"ref":"+4","special":"Импровизированная атака исподтишка 2/день, ловкий трюк 3/день","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":8,"ref":"+4","special":"Атака исподтишка +4d6","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":9,"ref":"+5","special":"Невидимый вор, ловкий трюк 5/день","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"},{"bab":"+5","fort":"+3","level":10,"ref":"+5","special":"Атака исподтишка +5d6, подлое заклинание","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"}],"requirements":[{"kind":"Мировоззрение","text":"любое непринципиальное."},{"kind":"Навыки","text":"Механика 4, Изворотливость 4, Знание (магия) 4."},{"kind":"Заклинания","text":"Магическая рука и как минимум одно мистическое заклинание 2 крута или выше."},{"kind":"Особое","text":"Атака исподтишка +2d6."}],"role":"Благодаря своему магическому искусству мистический трикстер может быть хитрее или незаметнее, чем любой рядовой плут. Дистанционные трюки значительно расширяют воровской арсенал трикстеров, а их способность наносить атаки исподтишка при помощи заклинаний и без необходимости брать противника в тиски делает их очень опасными противниками.","skillRanks":"4 + Инт","slug":"arcaneTrickster"},{"book":"Adventurer's Guide","classSkills":["Блеф","Верховая езда","Внимание","Выживание","Дрессировка","Запугивание","Знание (природа)","Знание (религия)","Проницательность","Ремесло"],"features":[{"description":"Асавир владеет всем простым и особым оружием, а также может использовать все виды брони и щитов (кроме башенных).","name":"Ношение брони и обращение с оружием"},{"description":"Асавир способен возглавлять тех, кто бьётся с ним бок о бок, создавая тем самым верную и слаженную команду, заклиная их храбро сражаться. Пока асавира слышат, бонус его действия помощь другому в бою для любых союзников в радиусе 30 футов возрастает на 1. На 5-ом уровне бонус увеличивается до 2, а на 9-ом уровне он увеличивается до 3. Эти бонусы не складываются с другими бонусами, улучшающими действие помощи другому.","name":"Товарищество (Экс)"},{"description":"Асавир получает скакуна как верного коня. Способности этого скакуна такие же, как и у верного зверя друида, используя уровень асавира + 2 как уровень друида (к примеру, на 3-ем уровне скакун асавира будет иметь такие же способности, что и верный зверь друида 5-ого уровня). Скакун обязан быть лошадью или пони, однако ведущий может позволить взять какое-то другое подходящее вам животное (особенно, если ваш персонаж маленького или крупного размера). Если же у асавира есть верный зверь скакун от другого класса, который даёт такую же способность (такого как кавалерист, друид или следопыт), то уровни асавира складываются с уровнями одного из них (по выбору) для определения способностей и характеристик его скакуна. Асавир также не получает второго компаньона, если имеет эту способность в другом классе. Его общий эффективный уровень друида при расчёте характеристик скакуна не может превышать общий уровень персонажа. К тому же, асавир не добавляет штраф за ношение брони к проверкам Верховой езды, когда он едет на своём скакуне, который всегда считается боевым и начинает игру с дополнительной чертой Ношение лёгкой брони.","name":"Лошадиная связь (Экс)"},{"description":"Когда асавир достигает 2-ого уровня, его скакун получает благословление шайтанов. Он получает +2 бонус народа к испытаниям против эффектов страха и воздействующих на разум эффектов. На 9-ом уровне асавира, этот бонус увеличивается до +4.","name":"Благословление шайтана (Св)"},{"description":"На 2-ом уровне количество раз в день, равное уровню асавира, асавир и его скакун могут провести атаку с разбега, от которой будет сотрясаться земля. Это действие считается атакой полного хода, и работает как обычная атака с разбега, кроме скорости скакуна асавира, которая остаётся той же (вместо удвоенной скорости как при обычной атаке с разбега). Существа в радиусе 5 футов от конечной точки атаки должны пройти проверку Реакции (СЛ = 10 + уровень асавира + модификатор Силы скакуна) или упасть. За каждый уровень асавира после 2-ого, он может не подвергать воздействию своей атаки одно существо (одно существо на 3-ем, до максимума в 8 существ на 10-ом уровне). Асавир должен совершить свою атаку или до, или после определения целей, которые упадут. На 6-ом уровне, радиус Громовой атаки с разбега увеличивается до 10 футов, а на 10-ом до 20 футов.","name":"Громовая атака с разбега (Св)"},{"description":"На 3-ем уровне асавир получает ауру доблести, которую получает паладин на 3-ем уровне.","name":"Аура доблести (Св)"},{"description":"На 3-ем уровне, если асавир успешно атакует врага, который фланкирует союзника, то он может совершить боевой манёвр против ЗБМ врага как быстрое действие. Если манёвр успешен, противник не может фланкировать любых существ на 1 раунд.","name":"Крушитель флангов (Экс)"},{"description":"На 4-ом уровне, асавир учится с точностью атаковать с разбега со спины скакуна. Асавир получает бонус +4 к атакам ближнего боя при атаке с разбега на скакуне (вместо обычного +2) и не получает штрафа к КБ после совершения атаки с разбега на скакуне.","name":"Контролируемая атака с разбега (Экс)"},{"description":"Когда асавир достигает 4-ого уровня, его скакун получает благословление джиннов, делающего его проворным и неутомимым. Он увеличивает свою скорость на 10 футов, не получает штрафов к перемещению в доспехах и может перемещаться с 2-умя наездниками без штрафов. Когда асавир достигает 8-ого уровня, скорость его скакуна увеличивается ещё на 10 футов.","name":"Благословление джинна (Св)"},{"description":"На 6-ом уровне, скакун асавира получает благословление марид, делающего его ловким партнёром с плавной поступью. Любой наездник не обязан проходить проверку концентрации во время движения на скакуне. Сам скакун получает бонус народа +2 к проверкам Реакции.","name":"Благословление марид (Св)"},{"description":"На 6-ом уровне, скакун асавира получает затаптывание как способность монстра, но только если им командует асавир действием полного хода. Урон от затаптывания сопоставим с атакой копытами скакуна + 1,5 его модифиактора Силы.","name":"Топчущий галоп (Экс)"},{"description":"На 7-ом уровне, три раза в день в качестве быстрого действия асавир может бросить вызов. Каждый его оппонент в 30 футах должен пройти проверку Воли (СЛ = 10 + уровень асавира + модификатор Харизмы асавира) или быть потрясённым видом асавира до его следующего хода. Каждое существо, провалившее испытание, является застигнутым врасплох и получает штраф -2 к КБ против атак союзников асавира. Это визуальный эффект, влияющий на разум.","name":"Все глаза на меня (Св)"},{"description":"Когда асавир получает 8 уровень, его скакун получает благословление ифрита, дающее устойчивость к огню 5. Также оно позволяет наносить дополнительные 1d6 урона огнём при атаке копытами.","name":"Благословление ифрита (Св)"},{"description":"На 9-ом уровне, асавир может воодушевить своих союзников сопутствующим действием. Союзники в 60 футах от асавира, которые его слышат, получают бонус морали равный модификатору Харизмы асавира на броски атаки и урона на 1 раунд. Асавир может использовать эту способность 3 раза в день. Это влияющий на разум, языковой эффект.","name":"Вдохновляющий лидер (Св)"},{"description":"На 10-ом уровне, когда асавир бросает d20 для совершения атаки, испытания или проверки навыка, он может перебросить и выбрать лучшее значение. Асавир может использовать это умение 1 раз в день для него и 1 раз в день для скакуна. Оба они получают бонус удачи +1 для всех испытаний.","name":"Благословление джанна (Св)"}],"hitDie":"d10","kind":"prestige","nameEn":"Asavir","nameRu":"Асавир","originalUrl":"https://pathfinder.family/class/prestige/asavir","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Товарищество +1, Лошадиная связь","will":"+1"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Благословление шайтана +2, Громовая атака с разбега (5 фт.)","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Аура доблести, Крушитель флангов","will":"+2"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Контролируемая атака с разбега, Благословление джинна (10 фт.)","will":"+2"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Товарищество +2","will":"+3"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Громовая атака с разбега (10 фт.), Благословление марид, топчущий галоп","will":"+3"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"Все глаза на меня","will":"+4"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Благословление джинна (20 фт.), Благословление ифрита","will":"+4"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Товарищество +3, Вдохновляющий лидер, Благословление шайтана +4","will":"+5"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Громовая атака с разбега (20 фт.), Благословление джанна","will":"+5"}],"requirements":[{"kind":"БМА","text":"+6."},{"kind":"Черты","text":"Бой Верхом."},{"kind":"Навыки","text":"Дрессировка 5, Верховая езда 5."}],"skillRanks":"4 + Инт","slug":"asavir"},{"book":"Adventurer's Guide","classSkills":["Блеф","Знание (история)","Знание (магия)","Использование магических устройств","Ловкость рук","Маскировка","Проницательность"],"features":[{"description":"Агент Аспидов получает бонус +1 к КБ и к испытаниям Реакции, чтобы избежать ловушек; этот бонус увеличивается на 1 на 4-ом уровне и каждые 3 уровня после. Также, эта способность складывается с бонусами Чутья на ловушки, полученного от другого класса.","name":"Чутьё на ловушки (Экс)"},{"description":"Работает так же, как и одноимённая способность плута. Уровни Агента Аспидов складываются с уровнями в других классах, которую дают такую же способность, для определения общего бонуса для Поиска ловушек.","name":"Поиск ловушек (Экс)"},{"description":"На 2-ом уровне, а также каждые 2 уровня после, Агент Аспидов получает один из следующих секретов. Он не может выбрать один и тот же секрет несколько раз (кроме тех случаев, когда об этом написано в самом секрете). Пустые угрозы (Экс): Агент Аспидов не получает штраф на проверки Запугивания против существ большего размера, а они, в свою очередь, не получают бонуса к проверкам Запугивания против Агента. Дополнительная черта: Агент Аспидов может выбрать одну из следующих черт как дополнительную: Продвинутые Ловушки Следопытов, Вывести Из Себя, Защитная стойка, Страхолюдина, Грязный Трюк++, Грязный Трюк+, Мастер Кнута+, Внушительный вид, Выученная Ловушка Следопыта, Эксперт (Запугивание), Мастер Кнута. Он должен соответствовать всем требованиям выбранной черты. Агент Аспидов может взять этот секрет несколько раз. Скрыть мысли (Св): Агент Аспидов, на которого нацелено чтение мыслей или аналогичный эффект, может выбирать, какие мысли на самом деле обнаруживаются, в то время как истинные мысли остаются конфиденциальными. Это не влияет на эффекты, влияющие на разум, кроме чтение мыслей. Экзотическое исполнение: Агент Аспидов, обладающий классовой способностью выступление барда или прикладное искусство, увеличивает свой эффективный уровень барда на 1 для всех эффектов, зависящих от выступления, включая изучение новых типов и улучшение эффектов его выступлений. Тайник (Экс/Св): Агент Аспидов получает бонус, равный его уровню на проверку Ловкости рук, чтобы спрятать небольшие предметы на себе. К тому же, он может один раз в день спрятать магические свойства одного предмета аналогично заклинанию аура магии. Мастер Заклинатель: Агент Аспидов, который может творить заклинания барда, инквизитора или гипнотизёра, увеличивает свой УЗ на 1 в этом классе. Он не получает других преимуществ этого класса, кроме заклинаний в день, известных заклинаний и повышенного уровня заклинателя. Если агент имеет уровни более чем в одном из этих классов, он должен выбрать, к какому классу применить это повышение, когда берёт этот секрет агентства. Агент Аспидов может взять этот секрет дважды. Воровской приём: Агент Аспидов может выбрать один Воровской приём, требованиям которого соответствует. Уровни в этом престиж-классе складываются с уровнями классов с Воровским приёмом для увеличения бонуса, зависящего от уровня, для любых талантов, которые у него есть, независимо от того, были ли они получены от этого престиж-класса или другого класса. Агент Аспидов, обладающий классом, дающим способность Воровской приём, может выбрать этот секрет дважды. Уменьшенная контрабанда (Св): Агент Аспидов может использовать заклинание уменьшение предмета раз в день в качестве псевдозаклинания, используя свой уровень в этом классе в качестве УЗ. К тому же, когда предмет уменьшен, на него действует эффект необнаружимость, который заканчивается по возвращению предмета в нормальное состояние. Мстительный Агент (Экс): Агент Аспидов с уровнями мстителя может выбрать один социальный талант, требованиям которого соответствует. Если он может взять Талант мстителя благодаря его уровням мстителя, Агент может взять один Талант мстителя, требованиям которого соответствует. Уровни обоих классов складываются для получения бонусов от эффектов, зависящих от уровня, вне зависимости от того, были ли они получены из-за уровней престиж-класса или другого класса. Агент Аспидов, обладающий уровнями мстителя, способен взять этот секрет дважды.","name":"Секреты агентства"},{"description":"На 2-ом уровне, в качестве основного действия, Агент Аспидов может изменить свою ауру мировоззрения для отмены эффектов обнаружения мировоззрения. Он может изменить ауру своего мировоззрения на иную или же совсем скрыть её. Это действует только на обнаружение мировоззрение, а не на эффекты, связанные с конкретным мировоззрением. Эта способность действует до смены мировоззрения, или же до отмены самим Агентом Аспидов. На 6-ом уровне, Агент Аспидов, на которого направлено действие обнаружения мировоззрения или иной эффект, связанный с мировоззрением, может пройти проверку Колдовства для идентификации эффекта. При успешном прохождении Агент Аспидов может сменить ауру мировоззрения в качестве быстрого действия. На 10-м уровне, когда агент Аспида принимает ложную ауру мировоззрения, он рассматривается как обладающий этим мировоззрением для всех эффектов магических предметов, заклинаний, а также псевдозаклинаний или сверхъестественных эффектов (таких как запрет, симпатия или нечестивое оружие), включая магические ловушки, основанные на мировоззрении. Маскируя свое мировоззрение, он игнорирует эти типы эффектов, которые связаны с истинным мировоззрением.","name":"Скрытие мировоззрения (Св)"},{"description":"На 3-ем уровне, Агент Аспидов может установить ловушку, которую он сделал или обошёл ранее, превысив СЛ проверки Механики на 10. Установленная ловушка может быть активирована Агентом Аспидов как сопутствующее действие пока она рядом с ним. Он добавляет свой бонус Чутья на ловушки к СЛ проверки Внимания ловушки и к броскам на попадание. Также он добавляет бонус атаки исподтишка к урону ловушки по существам, которых застали врасплох или у которых иным образом отсутствует бонус Ловкости к КБ.","name":"Засадная ловушка (Экс)"},{"description":"На 3-ем уровне Агент Аспидов получает атаку исподтишка, идентичную способности плута. Его дополнительный урон равен 1d6, однако он увеличивается на 1d6 на 6-ом и 9-ом уровнях. Если Агент Аспидов получает бонус к атаке исподтишка из другого источника, бонусы к урону складываются.","name":"Атака исподтишка (Экс)"},{"description":"На 5-ом уровне, Агент Аспидов может комбинировать самодовольство и насмешку с проверками Блефа для финта, проверками Запугивания для деморализации и боевыми манёврами Грязный трюк, получая бонус равный половине его уровня Агента на эти проверки. Он может приостановить эффект способности при успешной проверке вплоть до 1 дня за уровень в этом классе, тратя быстрое действие для повторной активации способности позже. Агент Аспидов должен быть в пределах 60 футов от цели для использования или активации Решающей насмешки. Это языковой эффект.","name":"Решающая насмешка (Экс)"},{"description":"На 7-ом уровне, Агент Аспидов добавляет бонус Чутья на ловушки к испытаниям для избежания ловушек.","name":"Улучшенное чутьё на ловушки (Экс)"},{"description":"На 8-ом уровне, Агент Аспидов может использовать способность Засадная ловушка, находясь на расстоянии от ловушки вплоть до 30 футов.","name":"Дистанционная активация (Экс)"}],"hitDie":"d8","kind":"prestige","nameEn":"Aspis Agent","nameRu":"Агент Аспидов","originalUrl":"https://pathfinder.family/class/prestige/aspisAgent","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Чутьё на ловушки +1, Поиск ловушек","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Секреты агентства, Скрытие мировоззрения","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Засадная ловушка, Атака исподтишка +1d6","will":"+1"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Секреты агентства, Чутьё на ловушки +2","will":"+1"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Решающая насмешка","will":"+2"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Секреты агентства, Атака исподтишка +2d6","will":"+2"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Чутьё на ловушки +3, Улучшенное чутьё на ловушки","will":"+2"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Секреты агентства, Дистанционная активация","will":"+3"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Атака исподтишка +3d6","will":"+3"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Секреты агентства, Чутьё на ловушки +4","will":"+3"}],"requirements":[{"kind":"Навыки","text":"Оценка 5, Блеф 5, Ремесло (ловушки) 5, Механика 5, Запугивание 5, Знание (история) 5, Внимание 5."},{"kind":"Особое","text":"Умеет обращаться с кнутом, а также классовую особенность Обезвреживание ловушек или возможность использовать заклинание обнаружение тайных дверей."}],"skillRanks":"4 + Инт","slug":"aspisAgent"},{"alignment":"Эгоизм и ледяное равнодушие - почти необходимые для профессиональных убийц душевные качества, и они более свойственны персонажам со злым мировоззрением. Больше всего среди них принципиально злых - работа ассасина требует недюжинной самодисциплины, хаотичные убийцы мало соответствуют этой роли. Хотя нейтральные ассасины поначалу склонны считать себя просто профессионалами, хорошо выполняющими свою работу, сама природа избранного ремесла неизбежно приводит их на путь зла.","book":"Core Rulebook","classSkills":["Акробатика","Блеф","Внимание","Дипломатия","Запугивание","Изворотливость","Использование магических устройств","Лазание","Ловкость рук","Маскировка","Механика","Плавание","Проницательность","Скрытность"],"features":[{"description":"Ассасины умеют обращаться с арбалетами (ручными, легкими и тяжелыми), кинжалами (любыми), дротиками, рапирами, мягкими дубинками, короткими луками (простыми и композитными), короткими мечами и легкими доспехами, но не умеют обращаться со щитами.","name":"Ношение брони и обращение с оружием"},{"description":"Эта способность работает точно так же, как одноименная способность плута. Наносимый при ее помощи урон увеличивается на +1d6 на каждом нечетном уровне ассасина (т. е. на 1, 3, 5, 7 и 9). Если у ассасина уже есть модификаторы за атаку исподтишка, они складываются.","name":"Атака исподтишка"},{"description":"Если ассасин тратит три раунда на внимательное изучение своей жертвы основным действием, а затем в ближнем бою совершает по ней успешную атаку исподтишка, нанося урон, он получает возможность парализовать или убить ее на месте (по своему выбору). Смертельная атака не срабатывает, если жертва успевает заметить ассасина или понять, что тот враждебно настроен (но даже в этом случае она остается атакой исподтишка, если жертва взята в тиски или не может прибавить положительный модификатор Ловкости к КБ). Если смертельная атака срабатывает и наносит урон, жертва должна пройти испытание Стойкости (СЛ 10 + уровень ассасина + модификатор Интеллекта ассасина). При провале этого испытания цель либо погибает (если ассасин хотел ее убить), либо теряет возможность действовать и становится абсолютно беспомощной на 1d6 раундов плюс 1 раунд за каждый уровень ассасина. Если жертва успешно проходит это испытание, смертельная атака становится просто атакой исподтишка. Проведя три раунда за изучением жертвы, ассасин должен нанести смертельный удар в течение следующих 3 раундов. Если он выжидает дольше или если смертельная атака не удается (жертва успешно проходит испытание), то снова такую атаку он сможет провести, только если потратит еще три раунда на изучение жертвы.","name":"Смертельная атака (Экс)"},{"description":"Ассасины весьма искусны в обращении с ядами, а потому не могут случайно отравиться, нанося яд на оружие.","name":"Специалист по ядам"},{"description":"На 2 уровне ассасин получает +1 к испытаниям против ядов. Этот модификатор увеличивается на +1 на каждом четном уровне ассасина.","name":"Бонус к испытаниям против ядов"},{"description":"Начиная со второго уровня ассасина нельзя застать врасплох, и он не теряет положительный модификатор Ловкости к КБ, если его противник невидим. Ассасин все же теряет его, если не может двигаться, а также если противник успешно применит против него финт. Если у ассасина уже есть особенность невероятное уклонение, полученная от другого класса, он автоматически получает невероятное уклонение+.","name":"Невероятное уклонение (Экс)"},{"description":"К 4 уровню ассасин становится настоящим мастером скрытного ношения оружия. Он прибавляет свой уровень ассасина к проверкам Ловкости рук при утаивании оружия от посторонних глаз.","name":"Спрятанное оружие (Экс)"},{"description":"Начиная с 4 уровня каждому, кто падет от руки ассасина, будет гораздо сложнее вернуться с того света. Любой заклинатель, который попытается сотворить над жертвой ассасина заклинание наподобие возвращения к жизни, должен пройти проверку УЗ со СА 15 + уровень ассасина. В случае провала заклинание будет потрачено впустую, а его реагенты пропадут. Эффект истинной смерти не сработает, если за раунд до сотворения возвращения к жизни над жертвой ассасина сотворить снятие проклятия. СЛ снятия проклятия равна 10 + уровень ассасина.","name":"Истинная смерть (Св)"},{"description":"Начиная с 5 уровня ассасина больше нельзя взять в тиски. Плут при этом не может атаковать его исподтишка, взяв в тиски, если только уровень плута не превышает уровень ассасина на 4. Если у ассасина уже есть полученная от другого класса особенность невероятное уклонение (см. выше), уровни в этих классах складываются для определения того, какой минимальный уровень плута нужен для взятия персонажа в тиски.","name":"Невероятное уклонение+ (Экс)"},{"description":"На 6 уровне ассасин, убивший существо в ходе предбоевого раунда при помощи способности Смертельная атака, может пройти встречную проверку Скрытности против Внимания окружающих. Если ассасин выигрывает, никто не успевает заметить его и понять, кто нанес смертельный удар.","name":"Тихая смерть (Экс)"},{"description":"Начиная с 8 уровня ассасин может использовать навык Скрытность, даже если ему негде спрятаться от чужих глаз. Для этого ему нужно просто находиться не далле 10 футов от области с низким уровнем освещенности (не считая его собственной тени).","name":"Мастер незаметности (Св)"},{"description":"На 9 уровне раз в день ассасин может провести смертельную атаку без предварительного изучения жертвы. Ему нужно просто атаковать исподтишка при помощи оружия ближнего боя, способного нанести жертве урон.","name":"Быстрая смерть (Экс)"},{"description":"На 10 уровне ассасин становится истинным мастером убийств. Раз в день, успешно проведя смертельную атаку, он может обратить тело своей жертвы в прах, что исключит ее оживление при помощи заклинаний возвращение к жизни и воскрешение (в данном случае сработает только истинное воскрешение). Ассасин должен объявить, что использует эту способность, до того, как нанести смертельную атаку. Если атака оказывается неудачной (иди приходится мимо цели), способность не сабатывает и тратится впустую.","name":"Ангел смерти (Св)"}],"hitDie":"d8","kind":"prestige","nameRu":"Ассасин","originalUrl":"https://pathfinder.family/class/prestige/assassin","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Атака исподтишка +1d6‚ смертельная атака, специалист по ядам","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"+1 к испытаниям против ядов, невероятное уклонение","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Атака исподтишка +2d6","will":"+1"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"+2 к испытаниям против ядов, спрятанное оружие, истинная смерть","will":"+1"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Невероятное уклонение+, атака исподтишка +3d6","will":"+2"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"+3 к испытаниям против ядов, тихая смерть","will":"+2"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Атака исподтишка +4d6","will":"+2"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"+4 к испытаниям против ядов, мастер незаметности","will":"+3"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Атака исподтитшка +5d6, быстрая смерть","will":"+3"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"+5 к испытаниям против ядов, ангел смерти","will":"+3"}],"requirements":[{"kind":"Мировоззрение","text":"Любое злое."},{"kind":"Навыки","text":"Маскировка 2, Скрытность 5."},{"kind":"Особое","text":"Чтобы стать ассасином, персонаж должен совершить убийство, не служащее никакой другой цели."}],"role":"Ассасины - по природе своей одиночки, и любых компаньонов они считают в лучшем случае досадной помехой. Конечно, порой миссия вынуждает ассасина надолго примкнуть к группе искателей приключений, но мало кто рискнет доверить профессиональному убийце прикрывать спину в бою; куда чаще им поручают задачи вроде разведки и подготовки засад.","skillRanks":"4 + Инт","slug":"assassin"},{"alignment":"Раздувшиеся маги не имеют особого мировоззрения, но целеустремлённость на достижении бо&#x301;льших магических способностей (и пошлое отвращение широкой публики к их ритуальному членовредительству) имеет тенденцию делать их, по крайней мере, частично нейтральными.","book":"City of Strangers","classSkills":["Знание (высший свет)","Знание (география)","Знание (инженерное дело)","Знание (история)","Знание (краеведение)","Знание (магия)","Знание (планы)","Знание (подземелья)","Знание (природа)","Знание (религия)","Использование магических устройств","Колдовство","Лечение","Полет"],"features":[{"description":"Пиявочники не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием (Weapon and Armor Proficiency)"},{"description":"На определённых уровнях персонаж получает дополнительные заклинания в день, как если бы он получил уровень в том классе мистического заклинателя, который у него был до взятия престиж-класса. Он не получает иных преимуществ от того класса, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у персонажа до получения престиж-класса было несколько классов, дающих доступ к мистическим заклинаниям, он должен выбрать, к какому из классов он будет добавлять уровни для определения количества заклинаний в день.","name":"Заклинания в день (Spells per Day)"},{"description":"На 1 уровне пиявочник получает запас пунктов крови, что представляет собой перегрузку его организма избытком крови, что позволяет расширить его мистические способности за пределы обычного уровня. Обычный запас пунктов крови пиявочника равен его классовому уровню. Пункты крови можно потратить во время сотворения заклинания, не тратя его ячейку. Ячейка заклинания остаётся неиспользованной (для спонтанных заклинателей), или заклинание возвращается, как если бы оно не было сотворено (для подготавливающих чары заклинателей). Сохранение заклинания или ячейки заклинания таким образом тратит количество пунктов крови, равное кругу заклинания, и эти пункты должны быть потрачены во время сотворения заклинания. Пункты крови не дают доступа к заклинаниям, которые заклинатель не изучил или не подготовил. Кроме того, пиявочник может использовать свою способность вздутие, чтобы получить несколько дополнительных пунктов крови, но такое усилие - опасная авантюра. Если текущее количество пунктов крови пиявочника превышает его классовый уровень, но не более чем в два раза, он становится дезориентирован. Если это усилие приводит к превышению двукратного значения пунктов крови, он немедленно впадает в убийственную ярость, беспорядочно нанося свои самые разрушительные атаки и используя способности как на друзей, так и на врагов в течение 1d6 раундов или до тех пор, пока запас крови не уменьшится до 0 (в зависимости от того, что наступит раньше). В конце ярости пункты крови падают до 0, ПЗ опускаются до -1, и он оказывается при смерти. Каждый день во время отдыха для восстановления заклинаний пиявочник восстанавливает пункты крови до значения, равного классовому уровню, но не выше (поэтому, если у пиявочника 5 уровней в классе, но в настоящее время 8 пунктов, то у него останется 8, пока не потратит дополнительные пункты). Некоторые пиявочники проводят постоянные ритуалы с использованием пиявок или кровопускания, пытаясь регулировать системы своего организма. Эти ритуалы, которые необходимо проводить ежедневно во время подготовки заклинания, дают пиявочнику возможность вычитать 1 из проверок вздутия (см. ниже) после определения результата, но ценой не складывающегося штрафа -2 к Выносливости. Этот штраф не может быть снят, за исключением случая отказа пиявочника от ритуала на день (также во время подготовки заклинания), что снимает его немедленно.","name":"Запас крови (Blood Pool)"},{"description":"Пиявочник может в качестве свободного действия мгновенно получить дополнительные пункты крови, но это подвергает его риску опасного изнеможения. На 1 уровне пиявочник может раз в день вздуться, чтобы получить 1d4 пункта крови. На 4 уровне он может вздуваться дважды в день, а кость проверки становится 1d8. На 8 уровне он может вздуваться три раза в день, и кость проверки становится 1d12.","name":"Вздутие (Bloat)"},{"description":"Пиявочники особенно восприимчивы к эффектам кровотечения, и сложность любой проверки Лечения для остановки кровотечения на 5 выше, чем обычно. Кроме того, когда пиявочник получает кровотечение после атаки, он теряет 1 пункт крови. Эта потеря пунктов крови суммируется при нескольких атаках с кровотечением, но не каждый раз, когда он получает урон от одной и той же атаки.","name":"Гемофилия (Hemophilia)"},{"description":"на 3 уровне пиявочник становится настолько массивным, что жировые складки наполненной кровью плоти дают +1 (естественная броня) к КБ. На 7 уровне этот бонус увеличивается до +2, но снижает скорость на 10 футов. Этот штраф складывается со штрафом от черты Посвящённый в пиявочники, но не может снизить скорость ниже 5 футов и не влияет на эффекты волшебного полёта.","name":"Тучность (Corpulence)"},{"description":"начиная с 10 уровня пиявочник может временно получить доступ ко всем дарам выбранного наследия, считая свой общий уровень мистического заклинателя (включая уровни пиявочника) в качестве уровня чародея, потребляя кровь, связанную с этим наследием. Выпивая 1 пинту свежей крови (что наносит 1 урон Выносливости) у чародея выбранного наследия или существа, связанного с этим наследием, пиявочник получает возможность использовать дары наследия (но не дополнительные заклинания, навыки обращения и тому подобное) в зависимости от его уровня в течение 1 часа. Эту способность можно использовать раз в день, и для питья крови обычно требуется целая минута, но пиявочники с чертой Создание зелий могут перегонять кровь в вытяжку размером с зелье, которую можно хранить и потреблять в качестве основного действия. Поглощенные наследия дополняют изначальное наследие пиявочника с уровнями чародея. Хотя пиявочники не получают физического насыщения от питья крови, эта практика, вероятно, является причиной многих историй, связывающих их и вампиров. Помимо чародеев конкретного наследия, в следующем списке представлены несколько примеров существ, чья кровь считается связанной с наследием. На усмотрение мастера могут быть и другие возможные образчики. Демоническое наследие: любое хаотичное злое потустороннее существо. Драконье наследие: любой дракон или существо с типом дракон. Дьявольское наследие: любое принципиальное злое потустороннее существо. Загробное наследие: любая нежить, имеющая плоть и кровь (например, вампиры или упыри, но не скелеты). Мистическое наследие: любой мистический заклинатель или любое существо с мистическим заклинанием или псевдозаклинанием не менее 3 круга. Наследие фей: любые феи или гномы. Небесное наследие: любое доброе потустороннее существо. Противоестественное наследие: любая аберрация. Стихийное наследие: любое существо с подтипом элементаль или стихийным подтипом (водяной, воздушный, земляной, огненный или холодный), при условии, что оно имеет плоть и кровь (например, саламандра, но не элементаль огня). Судьбоносное наследие: любое существо, способное творить заклинания прорицания.","name":"Поглощение наследия (Absorb Bloodline)"}],"hitDie":"d6","kind":"prestige","nameEn":"Bloatmage","nameRu":"Пиявочник","originalUrl":"https://pathfinder.family/class/prestige/bloatmage","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+0","special":"Вздутие (1/день, 1d4), гемофилия, запас крови","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"-","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":3,"ref":"+1","special":"Тучность","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+1","level":4,"ref":"+1","special":"Вздутие (2/день, 1d8)","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+2","level":5,"ref":"+2","special":"-","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":6,"ref":"+2","special":"-","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":7,"ref":"+2","special":"Тучность","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":8,"ref":"+3","special":"Вздутие (3/день, 1d12)","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":9,"ref":"+3","special":"-","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"},{"bab":"+5","fort":"+3","level":10,"ref":"+3","special":"Поглощение наследия","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"}],"requirements":[{"kind":"Черты (Feats)","text":"Любимая школа магии (любая), Посвящённый в пиявочники."},{"kind":"Заклинания (Spells)","text":"Способность творить мистические заклинания 3 круга."}],"role":"Пиявочники - превосходные заклинатели, часто действующие в бою как тяжёлая артиллерия, но возможность обезуметь при чрезмерном напряжении может сделать их почти такими же опасными для друзей, как и для врагов.","skillRanks":"2 + Инт","slug":"bloatmage"},{"alignment":"Хаотичное злое.","book":"Book of the Damned","classSkills":["Блеф","Запугивание","Знание (планы)","Знание (религия)","Колдовство","Проницательность","Скрытность"],"features":[{"description":"Демониак приобретает умение обращаться со всем простым оружием, а также с любимым оружием своего демонического покровителя.","name":"Ношение брони и обращение с оружием (Weapon and Armor Proficiency)"},{"description":"На указанных уровнях демониак получает новые заклинания в день, как если бы он также получил уровень в классе заклинателя, к которому он принадлежал, до взятия престиж-класса. Он не получает других преимуществ, которые получил бы персонаж этого класса, за исключением дополнительных заклинаний в день, известных заклинаний (если он спонтанный заклинатель) и увеличения УЗ. Если у персонажа было более одного класса заклинателя до того, как он стал демониаком, он должен решить, к какому классу он добавляет новый уровень, чтобы определить количество заклинаний в день.","name":"Заклинания в день/Известные заклинания (Spells per Day/Spells Known)"},{"description":"Когда демониака убивают, его душу мгновенно забирает Бездна, чтобы со временем превратиться в демона, соответствующего величайшим грехам, которыми прославлялся демониак при жизни. Персонаж, пытающийся воскресить убитого демониака, должен преуспеть в проверке УЗ со СЛ, равной 10 + уровень персонажа-демониака, иначе заклинание провалится. Этот персонаж не может снова попытаться воскресить демониака, пока не пройдёт 24 часа, хотя другие персонажи все еще могут попытаться это сделать.","name":"Проклятый (Damned) (Экс)"},{"description":"Демониак носит знак своего демонического владыки в виде клейма, похожего на татуировку, где-то на теле. Один раз в день демониак может призвать нечестивую магию этой метки, чтобы усилить заклинание во время его произнесения. Это заклинание приобретет хаотичный и злой дескрипторы, и это приведет к тому, что заклинание не будет расходоваться во время его наложения, позволяя демониаку снова наложить заклинание позже в этот же день.","name":"Демоническая метка (Demonic Mark) (Экс)"},{"description":"Чтобы сохранить свои демонические способности (включая все колдовские способности, которые были усилены классом), демониак должен ежедневно потакать своему избранному демоническому владыке. Эта церемония включена в любой метод, который демониак использует для восстановления колдовских способностей (например, медитация, молитва демоническому владыке или изучение книги заклинаний). Когда персонаж получает свой первый уровень демониака, он должен решить, является ли он евангелистом, возвышенным или стражем своего демонического покровителя. Этот выбор определяет, какую категорию даров он получит по мере повышения уровня, и после того, как он будет сделан, его нельзя будет изменить позже.","name":"Послушание (Obedience) (Экс)"},{"description":"Один раз в день на 2-м уровне демониак может открыть свою душу демоническому духу в качестве свободного действия. Этот демонический дух вселяется в демониака на количество раундов, равное его уровню демониака, предоставляя нечестивый бонус +2 к одному показателю характеристики по выбору демониака. На 5-м уровне одержимость дает нечестивый бонус +4 к одному показателю характеристики, устойчивость к электричеству 10 и бонус +4 к испытаниям против яда. На 7-м уровне одержимость дает нечестивый бонус +6 к одному показателю характеристики и невосприимчивость к электричеству и яду. Когда одержимость заканчивается, демониак приходит в замешательство на количество раундов, равное его уровню демониака, поскольку демонический дух проникает в его разум. В начале каждого раунда замешательства демониак может попытаться пройти испытание Воли со СЛ 25, чтобы немедленно прекратить эффект замешательства. Одержимость - это эффект, который сводится на нет защитой от зла или защитой от хаоса. Демониак может предотвратить или прекратить побочный эффект замешательства, используя одно из этих заклинаний, но воздействие такого заклинания до того, как одержимость исчерпает свое действие, также приводит к преждевременному прекращению предоставленных преимуществ.","name":"Одержимость (Energumen) (Св)"},{"description":"По мере того, как демониак получает уровни, он получает дары от своего демонического покровителя, поскольку его тело и душа все больше наполняются демонической энергией. Природа предоставляемых даров варьируется в зависимости от выбранного демониаком демонического владыки и от того, какую категорию даров он решает воплотить. Каждый демонический владыка дарует три дара, каждый из которых более мощный, чем предыдущий. На 3-м уровне демониак получает первый дар. На 6-м уровне он получает второй дар, а на 9-м уровне — третий и последний дар. Подробности об этих дарах см. в описании черты Бестиальное послушание и в описаниях демонических владык и зарождающихся демонических владык. Когда демонический дар предоставляет псевдозаклинание, уровень заклинателя демониака для этой способности равен общему уровню его персонажа. Эта способность позволяет демониаку получить доступ к этим дарам раньше, чем обычно; она не дает дополнительных возможностей использования даров, как только персонаж достигает необходимого количества КЗ для нормального получения даров.","name":"Демонический дар (Demonic Boon) (Экс, Пс или Св)"},{"description":"Один раз в день на 4-м уровне демониак может использовать призыв чудовища VI, чтобы вызвать одного суккуба, 1d3 бабау или 1d4+1 бримораков, чтобы они служили ему. На 8-м уровне демониак также получает способность один раз в день произносить призыв чудовища VIII, чтобы вызвать одного хезроу, 1d3 враков или 1d4+1 суккубов для служения ему.","name":"Призыв Демона (Summon Demon) (Пс)"},{"description":"На 10-м уровне демониак может подвергнуться временному превращению в уникального демона в качестве основного действия. Его тип меняется на потустороннее существо с подтипами хаотичный, демон, злой и местный. Он получает снижение урона 10/добро и холодное железо, устойчивость к кислоте 10, холоду 10 и огню 10, а также телепатию на расстояние 100 футов. Когда он впервые получает эту способность, он решает получить одну дополнительную физическую трансформацию из следующих при превращении: крылья (скорость полета 40 футов с хорошей маневренностью), жабры (способность дышать под водой и скорость плавания 30 футов) или одна естественная атака (укус, когти, рога, крушащий удар или жало; урон наносится в зависимости от размера демона). Если это дополнительное физическое преобразование выбрано, его уже невозможно изменить. Естественное оружие вновь созданного демона и любое оружие, которым он владеет, считаются хаотичным и злым с целью обхода снижения урона. Демониак может оставаться в этой форме количество минут в день, равное его уровню персонажа; эта продолжительность не обязательно должна быть последовательной, но ее следует использовать с шагом в 1 минуту. Возвращение в свою нормальную форму - свободное действие.","name":"Демоническая форма (Demonic Form) (Св)"}],"hitDie":"d8","kind":"prestige","nameEn":"Demoniac","nameRu":"Демониак","originalUrl":"https://pathfinder.family/class/prestige/demoniac","progression":[{"bab":"+0","fort":"+1","level":1,"ref":"+0","special":"Проклятый, демоническая метка, послушание","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Одержимость +2 (устойчивость)","spellcasting":"+1 уровень существующего класса","will":"+1"},{"bab":"+2","fort":"+2","level":3,"ref":"+1","special":"Демонический дар 1","spellcasting":"+1 уровень существующего класса","will":"+1"},{"bab":"+3","fort":"+2","level":4,"ref":"+1","special":"Призыв демона 1","spellcasting":"+1 уровень существующего класса","will":"+1"},{"bab":"+3","fort":"+3","level":5,"ref":"+2","special":"Одержимость +4 (устойчивость)","spellcasting":"+1 уровень существующего класса","will":"+2"},{"bab":"+4","fort":"+3","level":6,"ref":"+2","special":"Демонический дар 2","spellcasting":"+1 уровень существующего класса","will":"+2"},{"bab":"+5","fort":"+4","level":7,"ref":"+2","special":"Одержимость +6 (невосприимчивость)","spellcasting":"+1 уровень существующего класса","will":"+2"},{"bab":"+6","fort":"+4","level":8,"ref":"+3","special":"Призыв демона 2","spellcasting":"+1 уровень существующего класса","will":"+3"},{"bab":"+6","fort":"+5","level":9,"ref":"+3","special":"Демонический дар 3","spellcasting":"+1 уровень существующего класса","will":"+3"},{"bab":"+7","fort":"+5","level":10,"ref":"+3","special":"Демоническая форма","spellcasting":"+1 уровень существующего класса","will":"+3"}],"requirements":[{"kind":"Мировоззрение (Alignment)","text":"Хаотичное злое."},{"kind":"Черты (Feats)","text":"Бестиальное послушание, Стальная воля."},{"kind":"Навыки (Skills)","text":"Запугивание 7, Знание (планы) 7, Колдовство 7."},{"kind":"Язык (Language)","text":"Демонический."},{"kind":"Заклинания (Spells)","text":"Способность использовать как минимум два заклинания очарования двух разных кругов заклинаний."},{"kind":"Особое (Special)","text":"Должен поклоняться демоническому владыке или зарождающемуся демоническому владыке; должен быть морально, физически или духовно травмирован демоном — либо его ПЗ снижены до отрицательных значений в результате физических атак демона, либо получено в общей сложности 10 или более очков урона характеристикам или их потери от специальной атаки демона (этот общий урон может быть от нескольких атак, если общее количество составляет 10 или более), или провести как минимум 1 день под контролем демона (либо через эффекты приворота или принуждения, либо через демоническую одержимость)."}],"skillRanks":"2 + Инт","slug":"demoniac"},{"alignment":"Принципиальное злое.","book":"Book of the Damned","classSkills":["Блеф","Дипломатия","Запугивание","Знание (магия)","Знание (планы)","Знание (религия)","Колдовство","Проницательность"],"features":[{"description":"На указанных уровнях дьяволист получает новые заклинания в день, как если бы он также получил уровень в классе заклинателей, к которому он принадлежал, до добавления престиж-класса. Он не получает других преимуществ, которые получил бы персонаж этого класса, за исключением дополнительных заклинаний в день, известных заклинаний (если он спонтанный заклинатель) и увеличения УЗ. Если у персонажа было более одного класса заклинателя до того, как он стал дьяволистом, он должен решить, к какому классу он добавляет новый уровень, чтобы определить количество заклинаний в день.","name":"Заклинания в день/Известные заклинания (Spells per Day/Spells Known)"},{"description":"Когда дьяволиста убивают, его душа мгновенно отправляется в Ад. Персонаж, пытающийся воскресить его, должен преуспеть в проверке УЗ со СЛ, равной 10 + уровень дьяволиста, иначе заклинание провалится. Этот персонаж не может снова попытаться воскресить дьяволиста, пока не пройдут 24 часа, хотя другие персонажи все еще могут попытаться это сделать.","name":"Проклятый (Damned) (Экс)"},{"description":"Дьяволист образует тесную связь с конкретным бесом, подобно тому, как волшебник обретает фамильяра. Это действует как классовая особенность волшебника Мистическая связь, но так, как если бы дьяволист выбрал черту Улучшенный фамильяр. Если у дьяволиста есть классовые уровни в другом классе, который предоставляет фамильяра, уровни этого класса и уровни класса дьяволиста суммируются для определения общих способностей его беса-фамильяра. Фамильяр-бес может общаться со своим хозяином посредством телепатии, пока бес находится с ним в физическом контакте. На 5-м уровне бес-фамильяр дьяволиста может выбрать любое из следующих заклинаний, чтобы добавить их в свой список как псевдозаклинание (Пс) и применять неограниченно: кровотечение, зрение некроманта, определение мировоззрения (зло), определение мировоззрения (принципиальность), погибель, призрачный звук, магическая рука, сообщение, открывание/закрывание или мелкие фокусы. Бес может также добавить любое из следующих заклинаний в свой список способностей, как псевдозаклинание 1/день: осквернение воды, парящий диск, масло, волшебный засов, опознание, немой образ, невидимый слуга или чревовещание. Дальность телепатии беса с дьяволистом увеличивается до 60 футов. На 8-м уровне бес может выбрать еще два псевдозаклинания с неограниченным применением из соответствующего списка выше, а также еще одно псевдозаклинание, действующее 1/день, из соответствующего списка выше. Дальность телепатии беса с дьяволистом увеличивается до 1 мили.","name":"Бес фамильяр (Imp Familiar) (Экс)"},{"description":"Дьяволист получает бонус +2 к проверкам Харизмы при взаимодействии с дьяволами. Этот бонус увеличивается до +4 на 4-м уровне и до +6 на 7-м уровне.","name":"Адская харизма (Infernal Charisma) (Экс)"},{"description":"Чтобы поддерживать свои способности дьяволиста (включая все колдовские способности, которые были усилены классом), дьяволист должен ежедневно потакать своему выбранному покровителю. Эта церемония включена в любой метод, который дьяволист использует для восстановления способностей к заклинаниям (например, медитация, молитва архидьяволу или изучение книги заклинаний). Когда персонаж получает свой первый уровень дьяволиста, он должен решить, является ли он евангелистом, возвышенным или стражем своего дьявольского покровителя. Этот выбор определяет, какую категорию даров он получит по мере повышения уровня, и после того, как он будет сделан, его нельзя будет изменить позже.","name":"Послушание (Obedience) (Экс)"},{"description":"На 2-м уровне дьяволист может изменить заклинания, наносящие энергетический урон, на наносящие вместо этого урон Адского Огня. Он может делать это как свободное действие количество раз в день, равное его модификатору Харизмы (минимум 1). Заклинания, измененные адским огнем, получают дескрипторы принципиальность и зло. (Адский огонь принимает множество форм, большинство из которых воняют серой и мерцают яростным малиновым или тошнотворным зеленым оттенком. Поскольку он не требует топлива, любая земля, воздух или вода могут сгореть этим смертоносным пламенем. Урон, нанесенный адским огнем, известен как урон адского огня; он рассматривается как обычный огонь, но наносит половину урона от огня и половину урона от нечестивой энергии. Существа злого мировоззрения и существа со злым подтипом не получают урона от нечестивой энергии, но существа доброго мировоззрения и существа с добрым подтипом получают от нее двойной урон. Существа, находящиеся под действием заклинаний, таких как защита от зла, не подвержены воздействию этой нечестивой энергии, хотя они все равно могут получать урон от огня.)","name":"Канал Адского Огня (Channel Hellfire) (Св)"},{"description":"На 2-м уровне дьяволист, использующий заклинание потусторонний союзник (или подобное заклинание), может попытаться провести встречную проверку Харизмы против воззванного (но не призванного) дьявола. Если ему это удается, дьявол вдвое снизит цену, которую он требует за свое служение.","name":"Адская сделка (Infernal Bargain) (Экс)"},{"description":"На 3-м уровне дьяволист получает черту Усиленный призыв, даже если он не соответствует требованиям.","name":"Усиленный призыв (Augment Summoning) (Экс)"},{"description":"по мере того, как дьяволист получает уровни, он получает дары от своего адского покровителя. Природа предоставляемых даров варьируется в зависимости от выбранного покровителя дьяволиста и от того, какую категорию благ он решает воплотить. Каждый дьявольский покровитель дарует три дара, каждый сильнее предыдущего. На 3-м уровне дьяволист получает первый дар. На 6-м уровне он получает второй дар, а на 9-м уровне - третий и последний дар. Для получения подробной информации об этих дарах обратитесь к черте Бестиальное послушание и к описаниям архидьяволов, адских герцогов и Малебраншей. Когда дьявольский дар предоставляет псевдозаклинание, уровень заклинателя дьяволиста для него равен общему уровню его персонажа. Эта способность позволяет дьяволисту получить доступ к этим дарам раньше, чем обычно; он не дает дополнительных возможностей использования даров, когда персонаж достигает необходимого количества КЗ для обычного получения даров.","name":"Дьявольский дар (Diabolic Boon) (Экс, Пс или Св)"},{"description":"На 3-м уровне дьяволист получает бонус +2 к проверкам на исследование символов или истинных имен конкретных дьяволов. Этот бонус увеличивается до +4 на 9-м уровне.","name":"Ересь (Heresy) (Экс)"},{"description":"На 5-м уровне дьяволист считается достаточно полезным для дела Ада, чтобы ему была предоставлена краткая передышка от проклятия. Если дьяволист убит любым способом помимо воли Асмодея, архидьяволов или другой влиятельной силы в аду, он может быть воскрешен как обычно.","name":"Адская душа (Hellish Soul) (Экс)"},{"description":"На 6-м уровне дьяволист может переносить себя через ад в огненной вспышке. Он может использовать эту способность дважды в день, как дверь в пространстве, или может потратить оба использования на путешествие, как для телепортации. Он не может использовать эту способность, чтобы войти или покинуть области, защищенные от злых существ.","name":"Адский транспорт (Infernal Transport) (Пс)"},{"description":"На 8-м уровне дьяволист может использовать Луч Адского Огня дважды в день как псевдозаклинание.","name":"Луч Адского Огня (Hellfire Ray) (Пс)"},{"description":"На 10-м уровне, когда дьяволист вызывает (не призывает) дьявола, имя которого он знает, он может произнести заклинание воззвания как основное действие и заключить сделку с дьяволом как сопутствующее действие. Он добавляет половину своего модификатора Блефа, Дипломатии или Запугивания к проверке Харизмы переговоров (если таковая имеется).","name":"Мастер Воплощения (Master Conjurer) (Экс)"}],"hitDie":"d6","kind":"prestige","nameEn":"Diabolist","nameRu":"Дьяволист","originalUrl":"https://pathfinder.family/class/prestige/diabolist","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+0","special":"Проклятый, Бес фамильяр, Адская харизма +2, Послушание","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Канал адского огня, Адская сделка","spellcasting":"+1 уровень существующего класса","will":"+1"},{"bab":"+1","fort":"+1","level":3,"ref":"+1","special":"Усиленный призыв, Дьявольский дар 1, Ересь +2","spellcasting":"+1 уровень существующего класса","will":"+2"},{"bab":"+2","fort":"+1","level":4,"ref":"+1","special":"Адская харизма +4","spellcasting":"+1 уровень существующего класса","will":"+2"},{"bab":"+2","fort":"+2","level":5,"ref":"+2","special":"Адская душа, Способности беса (псевдозаклинания).","spellcasting":"+1 уровень существующего класса","will":"+3"},{"bab":"+3","fort":"+2","level":6,"ref":"+2","special":"Дьявольский дар 2, Адский транспорт","spellcasting":"+1 уровень существующего класса","will":"+3"},{"bab":"+3","fort":"+2","level":7,"ref":"+2","special":"Адская харизма +6","spellcasting":"+1 уровень существующего класса","will":"+4"},{"bab":"+4","fort":"+3","level":8,"ref":"+3","special":"Луч Адского Огня, Способности беса (псевдозаклинания)","spellcasting":"+1 уровень существующего класса","will":"+4"},{"bab":"+4","fort":"+3","level":9,"ref":"+3","special":"Дьявольский дар 3, Ересь +4","spellcasting":"+1 уровень существующего класса","will":"+5"},{"bab":"+5","fort":"+3","level":10,"ref":"+3","special":"Мастер Воплощения","spellcasting":"+1 уровень существующего класса","will":"+5"}],"requirements":[{"kind":"Мировоззрение (Alignment)","text":"Принципиальное злое."},{"kind":"Черты (Feats)","text":"Бестиальное послушание."},{"kind":"Навыки (Skills)","text":"Знание (планы) 7 рангов, Знание (религия) 7 рангов, Колдовство 7 рангов."},{"kind":"Язык (Language)","text":"Дьявольский."},{"kind":"Заклинания (Spells)","text":"Способность использовать как минимум два заклинания воплощения двух разных кругов заклинаний."},{"kind":"Особое (Special)","text":"Должен поклоняться Архидьяволу, Адскому Герцогу или Мальбраншу; должен был вызвать дьявола с помощью заклинания низший потусторонний союзник или низший потусторонний слуга (или аналогичные заклинания), чтобы успешно приказать дьяволу выполнить задачу, выполнение которой занимает минимум 1 день."}],"skillRanks":"2 + Инт","slug":"diabolist"},{"alignment":"Драконьи апостолы могут иметь практически любое мировоззрение, хотя в целом они более склонны к хаосу, чем к принципиальности. Апостолы, ведущие свой род от устрашающих цветных драконов, например от белых или красных, становятся злыми. Те же, что происходят от благородных металлических драконов, например латунных или золотых, чаще бывают добрыми.","book":"Core Rulebook","classSkills":["Внимание","Дипломатия","Запугивание","Знание (высший свет)","Знание (география)","Знание (инженерное дело)","Знание (история)","Знание (краеведение)","Знание (магия)","Знание (планы)","Знание (подземелья)","Знание (природа)","Знание (религия)","Изворотливость","Колдовство","Полет"],"features":[{"description":"Драконьи апостолы не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"На определенных уровнях персонаж получает дополнительные заклинания в день, как если бы он взял уровень в том классе мистического заклинателя, который у него был до взятия престиж-класса. Он не получает иных преимуществ от этого класса, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у драконьего апостола до получения престиж-класса было несколько классов, дающих доступ к мистическим заклинаниям, он должен выбрать, к какому из классов он будет добавлять уровни для определения количества заклинаний в день.","name":"Заклинания в день"},{"description":"Уровень драконьего апостола прибавляется к уровню чародея при определении его эффективного уровня владения дарами наследия драконов. Если драконий апостол не является чародеем, он просто получает дары чародейского драконьего наследия, используя свой уровень апостола вместо уровня чародея. На 1 уровне апостол должен определиться с видом дракона, который был его предком. Обратите внимание, что кровь драконов и чародейское драконье наследие должны возводить родословную персонажа к драконам одного и того же вида. Кровь драконов дает чародею дополнительные заклинания, но только для тех кругов, к которым у него уже есть доступ. Этот аспект крови драконов срабатывает каждый раз, когда чародей получает доступ к новому кругу заклинаний.","name":"Кровь драконов"},{"description":"Со временем кожа драконьего апостола все сильнее начинает напоминать прочную чешуйчатую шкуру его крылатого предка. На 1, 4 и 7 уровнях модификатор естественной брони драконьего апостола увеличивается на +1. Эти бонусы суммируются.","name":"Естественная броня (Экс)"},{"description":"Достигнув уровня, отмеченного в таблице «Драконий апостол», драконий апостол увеличивает значение указанной характеристики. Это увеличение постоянно и складывается с пунктами характеристик, которые по мере своего развития подучает любой персонаж.","name":"Рост характеристики (Экс)"},{"description":"Достигнув 2 уровня (и на каждом третьем уровне после этого), драконий апостол получает одну дополнительную черту из следующего списка: Бой вслепую, Быстрое заклинание, Внушительная стойкость, Живучесть, Сокрушительный удар, Улучшенная инициатива, Эксперт (Знание (магия)), Эксперт (Полет)..","name":"Черта наследия"},{"description":"Начиная со 2 уровня каждый раз, когда драконий апостол взывает к драконьему наследию, чтобы отрастить когти, его зубы превращаются в клыки, и он получает основную естественную атаку «укус». Им он наносит урон, равный 1d6 (1d4, если размер апостоила небольшой) + 1,5 модификатора Силы. На 6 уровне укус дополнительно наносит 1d6 урона стихией. Тип стихии опредеkяется видом дракона, от которого апостол ведет свой род.","name":"Драконьи клыки (Экс)"},{"description":"На 3 уровне драконий апостол получает губительное дыхание, даже если его общий уровень в соответствующих классах недостаточно высок, чтобы получить эту способность в качестве одного из даров наследия. Если апостол получит этот дар позднее, он просто сможет использовать эту способность на один раз в день чаще. Тип и форма дыхания зависят от вида дракона, от которого апостол происходит.","name":"Губительное дыхание (Св)"},{"description":"На 5 уровне драконий апостол обретает слепое чутье, которое охватывает область радиусом 30 футов. С его помощью апостол способен понять, что в этой области находится кто-то, кого он не видит. Если цели находятся на линии досягаемости, то апостолу, скорее всего, даже не понадобится проверка Внимания, чтобы засечь и определить их точное местоположение. Освещение влияет на скорость перемещения персонажа со слепым чутьем как обычно. Драконий апостол может атаковать существо, которое чует, но не видит, с вероятностью промаха 50%, а если это существо атакует его, положительный модификатор Ловкости апостола не учитывается при подсчете его КБ. На 10 уровне апостола радиус его чутья увеличивается до 60 футов.","name":"Слепое чутье (Экс)"},{"description":"На 7 уровне драконий апостол получает возможность принимать облик дракона. Эта способность работает как заклинание облик дракона I. На 10 уровне апостола она работает как облик дракона II, а сам апостол получает возможность превращаться в дракона дважды в день. Его УЗ при этом равно его общему уровню владения дарами драконьего наследия. Драконий апостол может принимать облик только одного вида драконов - того, к которому принадлежал его предок.","name":"Облик дракона (Пс)"},{"description":"На 9 уровне драконий апостол получает крылья, даже если его общий уровень соответствующих классов недостаточно высок, чтобы взять эту способность в качестве одного из даров наследия. Если апостол получит этот дар позднее, скорость его полета увеличится до 90 футов.","name":"Крылья (Св)"}],"hitDie":"d12","kind":"prestige","nameRu":"Драконий апостол","originalUrl":"https://pathfinder.family/class/prestige/dragonDisciple","progression":[{"bab":"+0","fort":"+1","level":1,"ref":"+0","special":"Кровь драконов, естественная броня (+1)","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Рост характеристики (Сил +2), черта наследия, драконьи клыки","spellcasting":"+1 уровень мистического заклинателя","will":"+1"},{"bab":"+2","fort":"+2","level":3,"ref":"+1","special":"Губительное дыхание","spellcasting":"+1 уровень мистического заклинателя","will":"+2"},{"bab":"+3","fort":"+2","level":4,"ref":"+1","special":"Рост характеристики (Сил +2), естественная броня (+1)","spellcasting":"+1 уровень мистического заклинателя","will":"+2"},{"bab":"+3","fort":"+3","level":5,"ref":"+2","special":"Слепое чутье (30 футов)‚ черта наследия","will":"+3"},{"bab":"+4","fort":"+3","level":6,"ref":"+2","special":"Рост характеристики (Вын +2)","spellcasting":"+1 уровень мистического заклинателя","will":"+3"},{"bab":"+5","fort":"+4","level":7,"ref":"+2","special":"Облик дракона (1/день)‚ естественная броня (+1)","spellcasting":"+1 уровень мистического заклинателя","will":"+4"},{"bab":"+6","fort":"+4","level":8,"ref":"+3","special":"Рост характеристики (Инт +2), черта наследия","spellcasting":"+1 уровень мистического заклинателя","will":"+4"},{"bab":"+6","fort":"+5","level":9,"ref":"+3","special":"Крылья","will":"+5"},{"bab":"+7","fort":"+5","level":10,"ref":"+3","special":"Слепое чутье (60 футов)‚ облик дракона (2/день)","spellcasting":"+1 уровень мистического заклинателя","will":"+5"}],"requirements":[{"kind":"Народ","text":"Любой, кроме драконов."},{"kind":"Навыки","text":"Знание (магия) 5."},{"kind":"Язык","text":"Драконий."},{"kind":"Заклинания","text":"Способность творить мистические заклинания 1 круга, не готовя их заранее. Если персонаж чародей, его наследие обязано быть драконьим. Если персонаж берет класс чародея уже после того, как становится драконьим апостолом, он также обязан выбрать драконье наследие."}],"role":"Будучи заклинателем, драконий апостол может играть в группе искателей приключений роль мага, задерживающего и уничтожающего противника чарами. Однако драконьи черты вроде способности летать или дышать огнем делают этих заклинателей еще более опасными противниками.","skillRanks":"2 + Инт","slug":"dragonDisciple"},{"alignment":"У дуэлянта может быть любое мировоззрение, но поскольку большинство из них относится к числу плутов и бардов, нет ничего удивительного в том, что среди них преобладают личности, не склонные к порядку и дисциплине. Впрочем, среди дуэлянтов порой встречаются люди весьма принципиальные - как правило, носители строгого кодекса чести, запрещающего им поднимать оружие на безоружного или беспомощного врага.","book":"Core Rulebook","classSkills":["Акробатика","Блеф","Внимание","Изворотливость","Исполнение","Проницательность"],"features":[{"description":"Дуэлянты умеют обращаться со всеми видами простого и особого оружия, а также с легкими доспехами, но не со щитами.","name":"Ношение брони и обращение с оружием"},{"description":"Когда дуэлянт облачен в легкие доспехи (или вообще обходится без брони), не использует щит и вооружен оружием ближнего боя, он прибавляет по пункту своего модификатора Интеллекта (если тот положительный) за каждый уровень дуэлянта, в качестве бонуса уклонения к своему КБ. Если дуэлянт застигнут врасплох (или не может учитывать свой положительный модификатор Ловкости к КБ по иной причине), этот бонус также теряется.","name":"Хитроумная защита (Экс)"},{"description":"Дуэлянт особенно точно попадает одноручным или полуторным колющим оружием, добавляя уровень дуэлянта к урону от оружия. Нанося точный выпад, дуэлянт теряет возможность использовать оружие или щит, находящийся во второй руке. Эта особенность действует только против живых существ с более или менее понятным строением тем. На существо, обладающее невосприимчивостью к критическим ударам, она не подействует, а любой предмет или способность, которые защищают от критических ударов, защитят и от точного выпада.","name":"Точный выпад (Экс)"},{"description":"На 2 уровне дуэлянт получает +2 к проверкам инициативы. На 8 уровне этот бонус возрастает до +4. Он складывается с бонусом от черты Улучшенная инициатива.","name":"Улучшенная реакция (Экс)"},{"description":"На 2 уровне дуэлянт постигает тонкости парирования вражеских атак. Каждый раз, когда дуэлянт, вооруженный одноручным или полуторным колющим оружием, совершает полную атаку, он может не наносить один из доступных ему при этом ударов, а в любой момент до своего следующего хода попытаться парировать вражескую атаку по себе или союзнику рядом прерывающим действием при помощи этого заранее подготовленного удара. Для этого дуэлянт должен провести атаку с теми же модификаторами, которые должны были быть у неиспользованной атаки. Если результат атаки выше, чем результат проверки атаки противника, персонаж отражает вражеский удар. За каждую ступень, на которую размеры противника превышают размеры дуэлянта, дуэлянт получает штраф -4 к парированию. Дуэдянт также получает штраф -4 к парированию атаки, которая нацелена не против него, а против стоящего рядом союзника. Дуэлянт должен заявить применение этой способности после того, как противник попытается атаковать, но до того, как будут брошены кости.","name":"Парирование (Экс)"},{"description":"Начиная с 3 уровня, если дуэлянт облачен в легкие доспехи (или вообще обходится без брони) и не использует щит, он получает +4 к КБ от внеочередных атак при передвижении с контролируемой противником клетки.","name":"Повышенная подвижность (Экс)"},{"description":"На 4 уровне дуэлянт получает все преимущества одноименной черты, если он вооружен легким или одноручным колющим оружием.","name":"Боевые рефлексы"},{"description":"На 4 уровне дуэлянт получает бонус +2 (мастерство) к испытаниям Реакции. Эта способность работает, только если дуэлянт облачен в легкие доспехи (или вообще обходится без брони) и не использует щит.","name":"Грация (Экс)"},{"description":"Начиная с 5 уровня дуэлянт может совершать внеочередную атаку по противнику, чью атаку он только что успешно парировал, если этот противник находится в зоне досягаемости дуэлянта.","name":"Контратака (Экс)"},{"description":"На 6 уровне дуэлянт получает возможность атаковать с разбега там, где не могут другие - в том числе на участках пересеченной местности. Это, впрочем, не избавляет дуэлянта от необходимости проходить проверки навыков, зависящие от препятствий и иных особенностей местности.","name":"Ловкий разбег (Экс)"},{"description":"Начиная с 7 уровня дуэлянт, ушедший в защиту или в глухую оборону в ближнем бою, увеличивает свой модификатор уклонения к КБ на +1 за каждые три уровня дуэлянта.","name":"Изощренная защита (Экс)"},{"description":"На 9 уровне дуэлянт получает все преимущества одноименной черты, если он вооружен одноручным или полуторным колющим оружием. Дуэлянту не нужна свободная рука, чтобы использовать это умение.","name":"Отбивание стрел"},{"description":"На 9 уровне дуэлянт получает возможность совершать внеочередные атаки по противникам, пытающимся отступить из его зоны досягаемости.","name":"Враг не сбежит (Экс)"},{"description":"Когда дуэлянт подтверждает критический удар, нанесенный одноручным или полуторным колющим оружием, он может, помимо нанесения урона, по своему выбору применить по отношению к врагу один из следующих эффектов: скорость перемещения врага уменьшается на 10 футов (до минимума в 5 футов); урон 1d4 Силе или Ловкости врага; враг получает штраф -4 ко всем испытаниям; враг получает штраф -4 к КБ; враг истекает кровью (2d6 урона). Эти эффекты длятся 1 минуту, за исключением урона характеристикам, который лечится по обычным правилам, н кровотечения, которое можно остановить только при помощи магического исцеления или успешной проверки Лечения со СЛ 15.","name":"Критическое увечье (Экс)"}],"hitDie":"d10","kind":"prestige","nameRu":"Дуэлянт","originalUrl":"https://pathfinder.family/class/prestige/duelist","progression":[{"bab":"+1","fort":"+0","level":1,"ref":"+1","special":"Хитроумная защита, точный выпад","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Улучшенная реакция +2, парирование","will":"+1"},{"bab":"+3","fort":"+1","level":3,"ref":"+2","special":"Повышенная подвижность","will":"+1"},{"bab":"+4","fort":"+1","level":4,"ref":"+2","special":"Боевые рефлексы, грация","will":"+1"},{"bab":"+5","fort":"+2","level":5,"ref":"+3","special":"Контратака","will":"+2"},{"bab":"+6","fort":"+2","level":6,"ref":"+3","special":"Ловкий разбег","will":"+2"},{"bab":"+7","fort":"+2","level":7,"ref":"+4","special":"Изощренная защита","will":"+2"},{"bab":"+8","fort":"+3","level":8,"ref":"+4","special":"Улучшенная реакция +4","will":"+3"},{"bab":"+9","fort":"+3","level":9,"ref":"+5","special":"Отбивание стрел, враг не сбежит","will":"+3"},{"bab":"+10","fort":"+3","level":10,"ref":"+5","special":"Критическое увечье","will":"+3"}],"requirements":[{"kind":"Базовый модификатор атаки","text":"+6."},{"kind":"Навыки","text":"Акробатика 2, Исполнение 2."},{"kind":"Черты","text":"Уворот, Подвижность, Фехтование."}],"role":"Способности дуэлянта специально рассчитаны на плутов и бардов, стремящихся повысить свою боевую эффективность, но при этом справедливо опасающихся за свою жизнь в силу неумения обращаться с тяжелыми доспехами. Дуэлянты сражаются в авангарде бок о бок с воинами, варварами и другими любителями ближнего боя, изматывая противника тщательно продуманными атаками.","skillRanks":"4 + Инт","slug":"duelist"},{"alignment":"Причин, по которым люди становятся рыцарями-колдунами, не меньше, чем причин, которые приводят их в подмастерья к волшебникам или в солдатские казармы, так что рыцарь-колдун может обладать любым мировоззрением. Однако баланс между мистическими штудиями и физическими тренировками помогает поддерживать только самодисциплина, так что большая часть таких персонажей все же придерживается принципиального мировоззрения.","book":"Core Rulebook","classSkills":["Верховая езда","Знание (высший свет)","Знание (магия)","Колдовство","Лазание","Плавание","Проницательность","Языкознание"],"features":[{"description":"Рыцари-колдуны не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"На 1 уровне рыцарь-колдун получает еще одну боевую черту. Это дополнение к тем чертам, которые любой персонаж получает по мере своего развития. Персонаж должен соответствовать всем требованиям черты, которую он хочет выбрать. Рыцарь-колдун получает еще по одной дополнительной боевой черте на 5 и 9 уровне.","name":"Дополнительная боевая черта"},{"description":"Рыцарь-колдун прибавляет свой уровень к уровню в классе воина, когда определяет, соответствует ли он требованиям той или иной черты (если у рыцаря-колдуна нет ни одного уровня в классе воина, уровни рыцаря-колдуна считаются уровнями воина). То же самое касается черт, которые требуют наличия определенного уровня заклинателя.","name":"Всесторонняя подготовка"},{"description":"На определенных уровнях персонаж получает дополнительные заклинания в день, как если бы он получил уровень в том классе мистического заклинателя, который у него был до взятия престиж-класса. Он не получает иных преимуществ от того класса, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у рьщаря-колдуна до получения престиж-класса было несколько классов, дающих доступ к мистическим заклинаниям, он должен выбрать, к какому из классов он будет добавлять уровни для определения количества заклинаний в день.","name":"Заклинания в день"},{"description":"На 10 уровне рыцарь-колдун, подтвердив критический удар, может сотворить заклинание в качестве быстрого действия. Среди целей или в области действия этого заклинания в обязательном порядке должна быть жертва этого критического удара. Сотворение этого заклинания не провоцирует внеочередные атаки. Заклинатель обязан иметь при себе все необходимые компоненты, а все внешние факторы, которые могут вызвать провал попытки сотворения мистического заклинания действуют как обычно.","name":"Критическое заклинание (Св)"}],"hitDie":"d10","kind":"prestige","nameRu":"Рыцарь-колдун","originalUrl":"https://pathfinder.family/class/prestige/eldritchKnight","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Дополнительная боевая черта, всесторонняя подготовка","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"-","spellcasting":"+1 уровень мистического заклинателя","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"-","spellcasting":"+1 уровень мистического заклинателя","will":"+1"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"-","spellcasting":"+1 уровень мистического заклинателя","will":"+1"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Дополнительная боевая черта","spellcasting":"+1 уровень мистического заклинателя","will":"+2"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"-","spellcasting":"+1 уровень мистического заклинателя","will":"+2"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"-","spellcasting":"+1 уровень мистического заклинателя","will":"+2"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"-","spellcasting":"+1 уровень мистического заклинателя","will":"+3"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Дополнительная боевая черта","spellcasting":"+1 уровень мистического заклинателя","will":"+3"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Критическое заклинание","spellcasting":"+1 уровень мистического заклинателя","will":"+3"}],"requirements":[{"kind":"Ношение брони и обращение с оружием","text":"Способность обращаться со всеми видами особого оружия."},{"kind":"Заклинания","text":"Способность творить мистические заклинания 3 круга."}],"role":"Рыцари-колдуны объединяют в себе роли бойцов и заклинателей - сейчас они мечут во врагов колдовское пламя, а секунду спустя уже разят их сверкающей сталью. Они чувствуют себя одинаково комфортно как в гуще сражения, так и за спинами соратников. Эта тактическая гибкость может стать решающим преимуществом, особенно когда истинная природа подстерегающего впереди врага неизвестна.","skillRanks":"2 + Инт","slug":"eldritchKnight"},{"book":"Inner Sea Gods","classSkills":["Внимание","Дипломатия","Знание (религия)","Лечение","Профессия","Ремесло"],"features":[{"description":"Евангелист умеет обращаться со всем простым оружием и легкой броней, а так же получает умение обращаться с любимым оружием своего божества.","name":"Ношение брони и обращение с оружием (Weapon and Armor Proficiency)"},{"description":"Для поддержания способностей, полученных от данного престиж-класса, включая все способности за счет особенности «Связанный класс», Евангелист должен проводить ежедневный обряд службы своему текущему божеству.","name":"Послушание (Obedience) (Экс)"},{"description":"Евангелист имеет свой набор навыков в различных дисциплинах. На 1 уровне Евангелист выбирает 2 навыка и добавляет их к своему списку классовых навыков. После выбора эти навыки нельзя изменить.","name":"Умелый (Skilled)"},{"description":"Евангелисты могут происходить из совершенно разных мест и иметь различный опыт за спиной, и по этому среди них есть совершенно разнообразные личности. На 2 уровне евангелист должен выбрать класс, к которому имел отношение до того, как получил этот престиж-класс, для того, чтобы он являлся связанным классом. Он получает все классовые особенности этого класса, по сути просто добавляя каждый уровень евангелиста не считая 1-го к уровню связанного класса для того, чтобы определить, какие способности он получает. Он сохраняет КЗ, БМА, бонусы к испытаниям и ранги навыков от прести-класса, но получает все остальные особенности связанного класса вместе с классовыми особенностями Евангелиста.","name":"Связанный класс (Aligned Class) (Экс)"},{"description":"Избранное Евангелистом божество награждает его повышенной осведомленностью и усиленной реакцией, что затрудняет противникам попадание по нему в бою. На 2 уровне, Евангелист получает бонус уклонения +1 к КБ. Этот бонус увеличивается до +2 на 7 уровне. Евангелист теряет этот бонус в том случае, когда лишается бонуса Ловкости к КБ.","name":"Защитная грация (Protective Grace) (Св)"},{"description":"По мере получения уровней евангелист получает дары от своего божества. Природа этих даров зависит от божества, которое избрал евангелист. Каждое божество дает 3 дара, каждый из которых сильнее предыдущего. На 3 уровне, Евангелист получает первый дар, на 6-ом - второй, и на 9-ом - третий. См. черту Божественное послушание относительно деталей божественных даров. Если дар дает псевдозаклинание, УЗ Евангелиста для этого заклинания будет равен его общему уровню персонажа. Эта способность позволяет Евангелисту получать божественные дары раньше, чем просто персонажу с чертой Божественное послушание; она не дает дополнительных возможностей для использования даров после того, как персонаж достингет нужного количества КЗ для их получения без учета этой способности.","name":"Божественный дар (Divine Boon)"},{"description":"На 4 уровне, Евангелист может выбрать дополнительный язык в качестве дара от своего божества. Он получает возможность свободно общаться и писать на данном языке. На 8 уровне, Евангелист выбирает второй язык для изучения. Способность понимать данные языки является моментальным божественным даром, и заклинания и эффекты, рассеивающие продолжительные эффекты, не могут рассеять Дар полиглота Евангелиста.","name":"Дар полиглота (Gift of Tongues)"},{"description":"За жизнь Евангелисту приходится встречаться с ситуациями, в которых требуются самые различные навыки. Начиная с 5 уровня, Евангелист получает святой или нечестивый бонус +4 к проверкам любого навыка, в котором у него нет рангов. Этот бонус применяется только к навыком, которые можно использовать без тренировки.","name":"Множество талантов (Multitude of Talents) (Экс)"},{"description":"По достижении 10 уровня, Евангелист получает возможность принимать духовную форму. Принятие этой формы требует основного действия, и Евангелист может поддерживать духовную форму количество минут в день, равное его уровню персонажа. Эти минуты не обязательно должны быть последовательными, но минимально расходуется 1 минута. Возвращение в обычную форму требует свободного действия. Духовная форма Евангелиста дает ему телепатию с радиусом в 100 футов, а так же две способности. При достижении 10 уровня, Евангелист должен выбрать форму этих двух способностей, и после выбора он не сможет ее изменить. Сначала, он выбирает одну из характеристик, к которой будет получать бонус +4 в духовной форме. После, он выбирает одно физическое изменение, которое проявляется при принятии формы: крылья (полет со скоростью 40 футов и хорошей маневренностью), жабры (возможностью дышать под водой и скорость плавания 30 футов), или одиночную естественную атаку (коготь, укус, атака рогами, крушащая атака или атака хвостом, наносящие урон согласно размеру евангелиста) вместе с временным придатком, способным совершить данную атаку.","name":"Духовная форма (Spiritual Form) (Св)"}],"hitDie":"d8","kind":"prestige","nameEn":"Evangelist","nameRu":"Евангелист","originalUrl":"https://pathfinder.family/class/prestige/evangelist","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Послушание, Умелый","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Связанный класс, Защитная грация +1","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Божественный дар 1","will":"+1"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Дар полиглота","will":"+1"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Множество талантов","will":"+2"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Божественный дар 2","will":"+2"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Защитная грация +2","will":"+2"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Дар полиглота","will":"+3"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Божественный дар 3","will":"+3"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Духовная форма","will":"+3"}],"requirements":[{"kind":"Мировоззрение","text":"в пределах одного шага от мировоззрения выбранного божества."},{"kind":"Божество","text":"Должен поклоняться одному конкретному божеству. Хотя любой поклонник любого божества может стать евангелистом, уникальная направленность каждой веры вдохновляет людей разного происхождения стремиться к этому пути в рамках этой веры. Ниже приведены примеры типов классов, которые с наибольшей вероятностью станут евангелистами в каждой из основных религий региона Внутреннего моря."},{"kind":"Черты","text":"Божественное послушание."},{"kind":"Особое","text":"одно из следующего: БМА +5; 5 рангов в любом навыки кроме Знания (религия); Возможность применять заклинания 3-го круга."}],"skillRanks":"6 + Инт","slug":"evangelist"},{"book":"Adventurer's Guide","classSkills":["Верховая езда","Выживание","Лазание","Лечение","Плавание"],"features":[{"description":"Золотые Легионеры умеют обращаться со всем простым и воинским оружием, а также со всеми видами доспехов и щитами.","name":"Ношение брони и обращение с оружием"},{"description":"В качестве сопутствующего действия Золотой Легионер может отдавать приказы нескольким союзникам до половины своего уровня персонажа, которые находятся в пределах 30 футов и могут видеть, слышать и понимать его. До тех пор, пока хотя бы один выбранный союзник подчиняется приказам Золотого Легионера во время этого раунда, Золотой Легионер и каждый выполнивший приказ союзник получают бонус компетентности +1 к броскам атаки, броскам урона оружия и испытаниям, а также к КБ на 1 раунд. Затронутые союзники не обязаны подчиняться этим приказам, но не получают бонусов, если они игнорируют их. На 6-м уровне этот бонус увеличивается до +2. На 8-м уровне Золотой Легионер может использовать авторитетный приказ в качестве быстрого действия.","name":"Авторитетный приказ (Экс)"},{"description":"Золотой легионер получает бонус +2 к испытаниям против одной из следующих опасностей: чары и принуждения, проклятия, болезни, страх, яды, ловушки или врожденные магические способности (псевдозаклинания и сверхъестественные способности, не полученные с уровнем классов) одного типа существа (и подтипа, если применимо), выбранного из списка избранных врагов следопыта. На 5-м уровне, а также на 9-м уровне Золотой Легионер получает дополнительный бонус +2 к другой опасности; в качестве альтернативы он может увеличить бонус против ранее выбранной опасности на 2.","name":"Бросить вызов опасности (Экс)"},{"description":"Золотой Легионер получает следующие бонусные черты на определенных уровнях, даже если он не выполняет предварительных требований: 2-й уровень – Задержание, 4-й уровень – Телохранитель, 6-й уровень – Во вред себе, 8-й уровень - Быстрая Помощь. Если у него уже есть черта для определенного уровня, он может вместо этого взять любую другую Боевую черту, чьим требованиям он соответствует.","name":"Черты Легионера"},{"description":"На 2-м уровне Золотой Легионер получает бонус, равный половине его классового уровня при проверке боевого маневра при использовании черты Задержание, и тот же бонус к его ЗБМ, когда противник пытается пройти через клетку, которую контролирует Золотой Легионер, используя Акробатику.","name":"Перехват (Экс)"},{"description":"На 2-м уровне Золотой Легионер может выбрать одного союзника в качестве быстрого действия. Пока он находится рядом с этим союзником, Золотой Легионер получает штраф -1 к КБ, а выбранный союзник получает бонус уклонения +2 к КБ в течение 1 раунда. На 6-м уровне и снова на 10-м уровне Золотой Легионер получает дополнительный штраф -1 к КБ, а бонус уклонения увеличивается еще на 2.","name":"Совместная оборона (Экс)"},{"description":"На 3-м уровне, если Золотой Легионер видит, что существо в пределах 60 футов от него атакует союзника или любое дружественное существо, включая его самого, он может выбрать этого атакующего в качестве назначенного противника. Когда Золотой Легионер делает это, он получает +1 бонус морали на броски атаки и броски урона от оружия против назначенного противника на количество раундов, равное его уровню класса. Золотой Легионер может иметь количество назначенных противников до одной трети его уровня класса. Если у него уже выбрано максимальное количество назначенных противников, он может прекратить действие возмездия против одного из ранее назначенных противников и выбрать нового. Золотой Легионер может повторно выбрать существо, которое уже является назначенным противником, если оно снова атакует союзника или дружественное существо, позволяя ему возобновить действие эффекта. На 7-м уровне бонус морали увеличивается до +2.","name":"Возмездие союзника (Экс)"},{"description":"На 4-м уровне, когда Золотой Легионер успешно использует помощь другому в бою, бонус к броску атаки союзника или к его КБ увеличивается на 1. На 9-м уровне бонус увеличивается еще на 1.","name":"Улучшенная помощь (Св)"},{"description":"На 5-м уровне, если существо делает 5-футовый шаг из области как соседней с Золотым Легионером, так и контролируемой им, или если существо отступает из этой области, оно вызывает у него внеочередную атаку.","name":"Держать строй (Экс)"},{"description":"На 7-м уровне Золотой Легионер может совершить внеочередную атаку по врагу, который перемещается в любой квадрат, который контролирует Золотой Легионер, независимо от того, будет ли это движение обычно провоцировать внеочередную атаку. Он может использовать эту способность против каждого противника один раз в день и не более одного раза за раунд.","name":"Упреждающий удар (Экс)"},{"description":"На 9-м уровне, один раз в раунд, когда существо, которому угрожает Золотой Легионер, атакует и поражает союзника, соседнего с Золотым Легионером, он может совершить внеочередную атаку против этого существа.","name":"Месть (Св)"},{"description":"На 10-м уровне один раз в день в качестве прерывающего действия Золотой Легионер может перебросить один бросок атаки или испытания или заставить противника перебросить бросок атаки, сделанный против легионера или соседнего союзника, после того, как результат броска атаки будет определен.","name":"Страж свободы (Экс)"}],"hitDie":"d10","kind":"prestige","nameEn":"Golden Legionnaire","nameRu":"Золотой Легионер","originalUrl":"https://pathfinder.family/class/prestige/goldenLegionnaire","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Авторитетный приказ +1, Бросить вызов опасности 1","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Черта Легионера, Перехват, Совместная оборона +2","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Возмездие союзника +1","will":"+1"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Улучшенная помощь +1, Черта Легионера","will":"+1"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Бросить вызов опасности 2, Держать строй","will":"+2"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Авторитетный приказ +2, Черта Легионера, Совместная оборона +4","will":"+2"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"Возмездие союзника +2, Упреждающий удар","will":"+2"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Авторитетный приказ (Быстрое действие), Черта Легионера","will":"+3"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Бросить вызов опасности 3, Улучшенная помощь +2, Месть","will":"+3"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Страж свободы, Совместная оборона +6","will":"+3"}],"requirements":[{"kind":"Мировоззрение","text":"Любое доброе."},{"kind":"Ношение тяжелой брони","text":"Должен быть опыт с тяжелой броней."},{"kind":"БМА","text":"+5."},{"kind":"Навыки","text":"Дипломатия 5, Запугивание 5."},{"kind":"Особое","text":"Старший Орлиный Рыцарь должен пригласить персонажа в организацию."}],"skillRanks":"2 + Инт","slug":"goldenLegionnaire"},{"book":"Inner Sea World Guide","classSkills":["Блеф","Дипломатия","Знание (краеведение)","Знание (магия)","Знание (планы)","Знание (религия)","Исполнение","Использование магических устройств","Колдовство","Профессия","Ремесло"],"features":[{"description":"гадатели не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"когда гадатель достигает следующего уровня, он получает дополнительные заклинания в день, как если бы получил уровень в том классе заклинателя, который был у него до взятия престиж-класса. Однако он не получает преимуществ от того класса, кроме дополнительных ячеек заклинаний в день. Он добавляет уровень в престиж-классе гадателя к уровню того класса заклижателя, который у него был. Если у гадателя до получения престиж-класса было несколько классов, дающих доступ к заклинаниям, он должен выбрать к какому из классов он будет добавлять уровни для определения количества заклинаний в день. Гадатель добавляет во все свои списки заклинаний гадание как заклинание 3 круга, если его ещё там нет.","name":"Заклинания в день"},{"description":"раз в день гадатель может погадать для себя и всех союзников в пределах 20 футов. Гадание занимает 10 минут, и все время союзники, подпадающие под его действие должны оставаться в пределах 20 футов от гадателя. По завершении гадания подсчитайте количество выпавших карт каждой масти. Гадание дает бонус в зависимости от масти большинства карт. Если разине масти набрали одинаковое число карт, выберите одну из них. Действие бонуса длится 24 часа. Масти дают следующие бонусы (интуитивные): Сила - +1 к проверкам атаки; Ловкость - +1 к КБ; Выносливость - +1 к проверкам урона оружием; Интеллект - +1 ко всем проверкам навыков; Мудрость - +1 ко всем испытаиннм; Харизма - +1 к проверкам УЗ и концентрации.","name":"Благословение гадателя (Св)"},{"description":"начинам со 2 уровня, гадатель при сотворении заклинания может вытянуть три карты из своей колоды Харо. Это добавляет к заклинанию жестовый компонент (если в заклинании его еще нет) и фокусирующий предмет (колоду Харо), но не увеличивает время сотворения заклинания. В зависимости от уровня гадателя, карты, которые он вытягивает, могут менять параметры его заклинаний или давать другие преимущества, как описано в особенностях Башен. Гадатель получает все доступные ему особенности Башен. Если он вытягивает карты, возможности которых ему еще не доступны, эти карты не дают никаких преимуществ. Каждая вытянутая гадателем карта, точно соответствующая его мировоззрению, считается за две карты этой масти. На одно заклинание не могут влиять одновременно заклинание гадателя и метамагическая черта. Количество раз в день, которое гадатель может использовать эту способность, равно его уровню в классе.","name":"Заклинание гадателя (Св)"},{"description":"начиная со 2 уровня, каждый раз, когда гадатель использует способность заклинание гадателя, за каждую вытянутую карту масти Интеллекта он получает бонус +1 к проверкам УЗ для преодоления устойчивости к магии.","name":"Башня Интеллекта (Св)"},{"description":"начиная с 3 уровня, каждый раз, когда гадатель использует способность заклинание гадателя, чтобы усилить заклинание, которое наносит урон ПЗ, это заклинание наносит +1 урон за кость за каждую вытянутую карту масти Силы.","name":"Башня Силы (Св)"},{"description":"начиная с 4 уровня, каждый раз, когда гадатель использует способность заклинание гадателя, за каждую вытянутую карту масти Харизмы СЛ испытания против заклинания повышается на 1.","name":"Башня Харизмы (Св)"},{"description":"гадатель 5 уровня может в качестве основного действия призвать мерцающую прозрачную колоду Харо, состоящую нз магической силы. Она пролетает по воздуху и окутывает цель в пределах 30 футов вихрем карт с бритвенно острыми краями. Затем гадатель вытягивает из своей личной колоды количество карт, равное его уровню гадателя, и призрачная колода наносит урон согласно количеству вытянутых карт, совпадающих с его мировоззрением, как указано в таблице ниже. Каждое точное совпадение наносит 5 урона, каждое частичное совпадение наносит 3 урона, каждая несовпадающая карта наносит 1 урон, а каждая противоположная карта урона не наносит. Количество раз в день, которое заклинатель может использовать эту способность, равно 1 + его модификатор Харизмы (минимум 1/день).","name":"Призрачная колода (Св)"},{"description":"гадатель 6 уровня получает способность раз в день в качестве псевдозаклинания творить прорицание. Его УЗ при этом равен общему уровню персонажа.","name":"Прорицание (Пс)"},{"description":"начиная с 7 уровня, каждый раз, когда гадатель использует способность заклинание гадателя, за каждую вытянутую карту масти Выносливости он исцеляет 1d6 урона.","name":"Башня Выносливости (Экс)"},{"description":"на 8 уровне каждый раз, когда гадатель использует способность заклинание гадателя, за каждую вытянутую карту масти Ловкости он получает +1 к испытаниям Реакции и КБ до начала его следующего хода.","name":"Башня Ловкости (Св)"},{"description":"на 9 уровне каждый раз, когда гадатель использует способность заклинание гадателя, за каждую вытянутую карту масти Мудрости его УЗ для этого заклинания увеличивается на 1.","name":"Башня Мудрости (Св)"},{"description":"когда гадатель 10 уровня вытягивает карты из любой колоды, чтобы активировать классовую способность (такую как заклинание гадателя) или эффект волшебного предмета, он может вытянуть дополнительную карту, а взамен сбросить одну карту по своему выбору и за мешать ее обратно в колоду. Эта способность недоступна во время гадания, но можно применить ее при использовании способности заклинание гадателя или призрачная колода. Гадатель также может применять эту способность, вытягивая карты нз волшебных колод, таких как колода чудес. Он может использовать эту способность неограниченно, но должен делать перерыв между использованиями на 1d4 раунда.","name":"Чтение знаков (Экс)"}],"hitDie":"d6","kind":"prestige","nameEn":"Harrower","nameRu":"Гадатель","originalUrl":"https://pathfinder.family/class/prestige/harrower","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+0","special":"Благословение гадателя","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Заклинание гадателя, Башня Интеллекта","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":3,"ref":"+1","special":"Башня Силы","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+1","level":4,"ref":"+1","special":"Башня Харизмы","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+2","level":5,"ref":"+2","special":"Призрачная колода","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":6,"ref":"+2","special":"Прорицание","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":7,"ref":"+2","special":"Башня Выносливости","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":8,"ref":"+3","special":"Башня Ловкости","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":9,"ref":"+3","special":"Башня Мудрости","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"},{"bab":"+5","fort":"+3","level":10,"ref":"+3","special":"Чтение знаков","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"}],"requirements":[{"kind":"Мировоззрение","text":"должно быть хаотичным, злым, добрым или принципиальным (не может быть истинно нейтральным). Большинство гадателей - представители крайних мировоззрений: принципиальный добрый, хаотичный добрый, принципиальный злой или хаотичный злой."},{"kind":"Черты","text":"Гадание."},{"kind":"Навыки","text":"Знание (магия или религия) 5, Исполнение (любое) 5."},{"kind":"Заклинания","text":"способность творить заклинания 3 круга. Должен быть способен творить как минимум три заклинания школы прорицании."},{"kind":"Особое","text":"у персонажа должна быть колода Харо."}],"skillRanks":"2 + Инт","slug":"harrower"},{"book":"Inner Sea World Guide","classSkills":["Верховая езда","Внимание","Запугивание","Знание (краеведение)","Проницательность"],"features":[{"description":"Рыцари Преисподней не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"сила ауры принципиальности Рыцаря Преисподней (см. заклинание определение мировоззрения (принципиальность)) равна общему уровню персонажа.","name":"Аура принципиальности (Экс)"},{"description":"эта способность действует аналогично способности паладина определение мировоззрения (зло), только определяет хаос.","name":"Определение мировоззрения (хаос) (Пс)"},{"description":"персонаж должен выбрать один из орденов Рыцарей Преисподней. Выбор ордена определяет, к каким дисциплинам персонаж получает доступ.","name":"Орден"},{"description":"эта способность действует аналогично способности паладина сокрушение зла, только против хаотичных существ. Эффект этой способности увеличивается вдвое, если она направлена на потусторонних существ с хаотичным подтипом, хаотичные аберрации или фей.","name":"Сокрушение хаоса (Св)"},{"description":"на 2 уровне Рыцарь Преисподней может применять выявление лжи в качестве псевдозаклинания. Рыцарь Преисподней может использовать эту способность в количестве 3 раза в день + модификатор Харизмы. Его УЗ равен общему уровню персонажа.","name":"Выявление лжи (Пс)"},{"description":"на 2 уровне Рыцарь Преисподней получает право носить доспех Рыцаря Преисподней. Ношение этой брони снижает штраф за доспехи на 1, повышает максимальный модификатор Ловкости на 1 и позволяет двигаться с полной скоростью. Ha 5 уровне эти изменения увеличиваются до 2. На 8 уровне изменения увеличиваются до 3.","name":"Доспех Рыцаря Преисподней (Экс)"},{"description":"Рыцарь Преисподней 3 уровня получает доступ к своей первой дисциплине, выбирая одну из тех, что соответствуют его ордену. На б уровне Рыцарь Преисподней получает доступ ко второй дисциплине, выбирая ее из доступных для всех орденов. На 9 уровне Рыцарь Преисподней получает доступ к третьей дисциплине, выбирая любую из приведенных ниже, даже если она недоступна его ордену, за исключением пятибожия. Когда это применимо, СЛ испытания против эффекта дисциплины равна 10 + уровень Рыцаря Преисподней + модификатор Харизмы Рыцаря Преисподней. Рыцарь Преисподней может использовать каждую дисциплину столько раз в день, сколько всего дисциплин ему доступно. Например на 3 уровне он может использовать дисциплину 1 раз в день, на 6 уровне - каждую из двух дисциплин по 2 раза в день, на 9 уровне - каждую из трёх дисциплин по 3 раза в день. Бдительность (Св; Орден Плети): Рыцарь Преисподней получает сумеречное зрение (постоянный эффект). Кроме того, в качестве действия полного хода Рыцарь Преисподней может видеть сквозь преграду из камня, дерева или подобного материала толщиной не более 5 футов, словно ее не существует. Металл или более плотная преграда блокируют этот эффект. Каждый раз эффект длится, пока Рыцарь Преисподней концентрируется, но не больше раундов, чем уровень Рыцаря Преисподней. Выслеживание (Пс; любой орден): Рыцарь Преисподней может призвать существо на помощь как в бою, так и при выслеживании врага, аналогично использованию заклинания призыв чудовища, за исключением того, что призванное существо остаётся на 1 час, а потом исчезает. Рыцарь Преисподней 6 уровня может призвать орла, ездовую собаку, волка или леопарда. Рыцарь Преисподней 9 уровня может вместо этого вызвать свирепого волка или адскую гончую. Клеймо (Пс; Орден Погребального Костра): Рыцарь Преисподней может использовать метку справедливости в качестве псевдозаклинания. Оковы (Св; Орден Цепи): когда Рыцарь Преисподней использует способность сокрушение хаоса против существа, он может уменьшить его подвижность. Противник может отменить этот эффект, успешно пройдя испытание Воли; иначе эффект действует на него аналогично заклинанию замедление в течение 1d4 раундов. Поражение ужасом (Экс; любой орден): если Рыцарь Преисподней при помощи навыка Запугивание делает какое-либо существо в пределах 10 футов потрясённым, он вместо этого может сделать это существо напуганным. Призыв дьявола (Пс; Орден Врат): Рыцарь Преисподней может использовать призыв чудовища V в качестве псевдозаклинания для призыва 1 бородатого дьявола. На 6 уровне это псевдозаклинание заменяется призывом чудовища VI, позволяющим Рыцарю Преисподней призвать 1d3 бородатых дьяволов или 1 эринию. На 9 уровне псевдозаклинание заменяется призывом чудовища VII, что позволяет призвать 1d4+1 бородатых дьяволов, 1d3 эриний или 1 костяного дьявола. Пятибожие (Экс; только Орден Божьего Когтя): эта способность позволяет Рыцарю Преисподней выбрать одну из следующих сфер: Благородства, Войны, Защиты, Знания, Магии, Путешествий, Силы, Славы, Созидания, Принципиальности и Рун. Рыцарь Преисподней получает все дарованные силы (но не заклинания) этой сферы. Чтобы определить, к каким способностям сферы он имеет доступ, он использует свой уровень Рыцаря Преисподней в качестве уровня жреца. Расплата болью (Св; любой орден): Рыцарь Преисподней может, совершив в качестве основного действия атаку касанием, причинить существу невероятную боль. Цель получает 1d6 урона + модификатор Харизмы Рыцаря Преисподней и должна пройти испытание Воли. При провале она становится ошеломленной на 1d4 раунда. Стремительная атака (Св; Орден Гвоздя): раз в день в качестве свободного действия Рыцарь Преисподней увеличивает свою базовую скорость на 10 футов и получает бонус +4 к Силе на 1 раунд. Если Рыцарь Преисподней верхом, эти бонусы применяются также к его скакуну. Цензор (Св; Орден Дыбы): когда Рыцарь Преисподней использует против существа сокрушение хаоса, он может поразить его немотой на 1d4 раунда, если оно провалит испытание Воли. Немое существо не может говорить, а также сотворять заклинания со словесным компонентом или использовать языковые эффекты.","name":"Дисциплины"},{"description":"на 3 уровне Рыцарь Преисподней получает бонус +2 к испытаниям Воли против заклинаний с одним из следующих дескрипторов: морок, обольщение, принуждение, ужас, узор, фантазм или фикция. На 6 уровне Рыцарь Преисподней выбирает другую подшколу или дескриптор и получает бонус +2 к испытаниям Воли против них, а бонус от первого выбора увеличивается до +4. На 9 уровне Рыцарь Преисподней снова выбирает из списка, и бонусы ранее выбранных дескрипторов или подшкол повышаются на +2, так что в итоге он получает бонусы к испытаниям против трех разных эффектов +6, +4 и +2 соответственно.","name":"Сила воли (Экс)"},{"description":"на 7 уровне атаки Рыцаря Преисподней считаются принципиальными при преодолении снижения урона.","name":"Страж закона (Экс)"},{"description":"если Рыцарь Преисподней 9 уровня носит доспех Рыцаря Преисподней, он получает бонус +2 ко всем проверкам Харизмы, сделанным во время взаимодействия с принципиальными недобрыми существами. Кроме того, он получает способность отчётливо видеть в любой темноте, устойчивость к огню 30, устойчивость к кислоте 10 и устойчивость к холоду 10.","name":"Адская броня (Св)"},{"description":"на 10 уровне Рыцарь Преисподней может придать оружию, которое он держит или которого касается, свойство нечестивого, огненного взрыва или праведного. Оружие сохраняет приобретенное свойство, пока Рыцарь Преисподней находится в радиусе 100 футов от него. Рыцарь Преисподней может поддерживать дополнительное свойство лишь одного оружия единовременно. Рыцарь Преисподней также становится невосприимчивым к огню, пока носит доспех Рыцаря Преисподней.","name":"Воин Преисподней (Св)"}],"hitDie":"d10","kind":"prestige","nameEn":"Hellknight","nameRu":"Рыцарь преисподней","originalUrl":"https://pathfinder.family/class/prestige/hellknight","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Аура принципиальности, определение мировоззрения (хаос), орден, сокрушение хаоса 1/день","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Выявление лжи, доспех Рыцаря Преисподней 1","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Дисциплина 1, сила воли 1","will":"+1"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Сокрушение хаоса 2/день","will":"+1"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Доспех Рыцаря Преисподней 2","will":"+2"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Дисциплина 2, сила воли 2","will":"+2"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"Страж закона, сокрушение хаоса 3/день","will":"+2"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Доспех Рыцаря Преисподней 3 (полная скорость)","will":"+3"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Дисциплина 3, сила воли 3, адская броня","will":"+3"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Воин Преисподней, сокрушение хаоса 4/день","will":"+3"}],"requirements":[{"kind":"Базовый модификатор атаки","text":"+5."},{"kind":"Навыки","text":"Запугивание 5, Знание (планы) 2."},{"kind":"Ношение брони","text":"способность носить тяжелую броню."},{"kind":"Мировоззрение","text":"любое принципиальное."},{"kind":"Особое","text":"вы должны убить дьявола с КЗ больше, чем у вас. Эту победу должен засвидетельствовать Рыцарь Преисподней."}],"skillRanks":"2 + Инт","slug":"hellknight"},{"alignment":"Любой может жаждать новых перспектив и постоянных путешествий, поэтому горизонтоход может быть любого мировоззрения.","book":"Advanced Player's Guide","classSkills":["Внимание","Выживание","Дипломатия","Дрессировка","Знание (география)","Знание (планы)","Знание (природа)","Лазание","Плавание","Скрытность","Языкознание"],"features":[{"description":"Горизонтоход не получает навыков обращения с каким-либо оружием или доспехами.","name":"Ношение брони и обращение с оружием (Weapon and Armor Proficiency)"},{"description":"На 1-м уровне горизонтоход может выбрать излюбленную местность из таблицы «Излюбленная местность» следопыта. Это работает точно так же, как способность следопыта излюбленная местность. Горизонтоход получает дополнительную излюбленную местность на 2, 4, 5, 7, 8 и 10 уровнях и может увеличить бонус от существующей излюбленной местности, как описано в способности следопыта. Если у горизонтохода есть способности других классов, которые работают только на излюбленной местности (например, способности следопыта камуфляж и мастер незаметности), эти способности работают на излюбленной местности, выбранной горизонтоходом.","name":"Излюбленная местность (Favored Terrain)"},{"description":"На 2-м уровне горизонтоход выбирает излюбленную местность для освоения. Находясь внутри этой местности, горизонтоход может в качестве сопутствующего действия предоставить бонус +2 к проверкам Лазания, Скрытности, Внимания и Выживания, совершаемым всеми союзниками в пределах 30 футов, которые могут видеть и слышать его. Этот бонус длится количество раундов, равное модификатору Мудрости горизонтохода (минимум 1). Персонаж осваивает по одной дополнительной местности на 4, 6 и 8 уровнях. Мастерство над каждой местностью дает дополнительные преимущества, описанные ниже; эти преимущества применимы к горизонтоходу всегда, независимо от того, находится он на соответствующей местности или нет. Астральный план (Astral Plane): Скорость полета горизонтохода увеличивается на +30 футов на планах без гравитации или субъективной гравитации. Холодные края (Cold): Горизонтоход получает устойчивость к холоду 10. Пустыня (Desert): Горизонтоход получает невосприимчивость к бессилию; все, что может привести к его бессилию, вместо этого делает его утомленным. Эфирный план (Ethereal Plane): Горзонтоход игнорирует 20%-ный шанс промаха из-за плохой видимости от тумана и дыма и рассматривает отсутствие видимости от этих источников как плохую видимость. Лес (Forest): Горизонтоход получает бонус мастерства +4 к проверкам Скрытности. Джунгли (Jungle): Горизонтоход получает бонус мастерства +4 к проверкам Изворотливости и увеличивает свою ЗБМ против захвата на +4. Горы (Mountain): Горизонтоход получает бонус мастерства +4 к проверкам Лазания и не теряет свой модификатор Ловкости к КБ во время лазания. Равнины (Plains): Движение горизонтохода не уменьшается при ношении средней брони или при переноске среднего груза. План Воздуха (Plane of Air): Горизонтоход получает бонус мастерства +4 к проверкам Полета и бонус мастерства +1 ко всем броскам атаки и урона против летающих существ. Он получает способность дышать воздухом, если еще не может этого делать. План Земли (Plane of Earth): Горизонтоход получает СУ 1/адамантин. План Огня (Plane of Fire): Горизонтоход получает устойчивость к огню 10. План Воды (Plane of Water): Горизонтоход получает бонус мастерства +4 к проверкам Плавания и бонус мастерства +1 ко всем броскам атаки и урона против плавающих существ. Он получает способность дышать под водой, если еще не может этого делать. Мировоззренческий план (Plane, aligned): Если горизонтоход выбирает план с особенностью мировоззрения, он может выбрать обнаружение этого мировоззрения (обманув все формы магического предсказания) в качестве прерывающего действия; эта способность действует до тех пор, пока он не отменит ее (свободное действие). Болото (Swamp): Горизонтоход получает бонус мастерства +4 к проверкам Внимания. Подземелье (Underground): Горизонтоход получает Бой вслепую в качестве бонусной черты. Город (Urban): Горизонтоход получает бонус мастерства +4 к проверкам Дипломатии. Вода (Water): Горизонтоход получает бонус мастерства +4 к проверкам Плавания и бонус мастерства +1 ко всем броскам атаки и урона против плавающих существ.","name":"Мастерство местности (Terrain Mastery)"},{"description":"На 3-м уровне горизонтоход учится полному господству над одной местностью, которую он уже выбрал для мастерства местности. Имея дело с существами, обитающими в этой местности, горизонтоход рассматривает свой бонус излюбленной местности для этой местности как бонус заклятого врага (как особенность класса следопыт) против этих существ. Этот бонус перекрывается (не суммируется) с бонусами, полученными при сражении с заклятым врагом. Каждое господство на местности дает дополнительные способности, подробно описанные ниже. Когда горизонтоход получает новое господство на местности, он может, если пожелает, вместо этого выбрать дополнительное мастерство местности. Астральный план (Astral Plane): Горизонтоход получает бонус мастерства +1 к броскам атаки и урона против потусторонних существ. Он получает дверь в пространстве как псевдозаклинание количество раз в день, равное 3 + модификатор Мудрости персонажа (уровень заклинателя равен уровню персонажа). Холодные края (Cold): Горизонтоход получает устойчивость к холоду 20 (это заменяет устойчивость к холоду персонажа от мастерства холодных краёв) и бонус мастерства +1 ко всем броскам атаки и урона против существ холодного подтипа. Пустыня (Desert): Горизонтоход получает устойчивость к огню 10 и невосприимчивость к утомлению. Эфирный план (Ethereal Plane): Горизонтоход получает эфирную прогулку как псевдозаклинание один раз в день (уровень заклинателя равен уровню персонажа). Он должен быть как минимум 7-го уровня, чтобы выбрать эту способность. Лес (Forest): Горизонтоход получает иллюзорную местность как псевдозаклинание количество раз в день, равное 3 + модификатор Мудрости персонажа (уровень заклинателя равен уровню персонажа). Горизонтоход может использовать эту способность только для создания иллюзорных лесов. Джунгли (Jungle): Горизонтоход получает приворот (чудовище) как псевдозаклинание количество раз в день, равное 3 + модификатор Мудрости персонажа (уровень заклинателя равен уровню персонажа). Это заклинание действует только на животных, волшебных зверей и существ, обитающих в основном в джунглях. Горы (Mountain): Горизонтоход получает СУ 2/адамантин. Равнины (Plains): Базовая скорость горизонтохода увеличивается на +10 футов. План Воздуха (Plane of Air): Горизонтоход получает полет как псевдозаклинание количество раз в день, равное 3 + модификатор Мудрости персонажа (уровень заклинателя равен уровню персонажа). План Земли (Plane of Earth): Горизонтоход получает виброчувствительность на расстоянии 30 футов. Он должен быть как минимум 5-го уровня, чтобы выбрать этот план для этой способности. План Огня (Plane of Fire): Горизонтоход получает устойчивость к огню 20 (это заменяет устойчивость персонажа от мастерства Плана Огня) и бонус мастерства +1 ко всем броскам атаки и урона снова существам огненного подтипа. План Воды (Plane of Water): Движения и действия горизонтохода не ограничиваются под водой. Это позволяет ему говорить, атаковать и произносить заклинания под водой (как если бы он использовал свободу движений). Мировоззренческий план (Plane, aligned): В целях обхода снижения урона рукотворное и естественное оружие горизонтохода считается противоположным мировоззрением выбранного им мировоззренческого плана. Если выбранный им план имеет более одного типа мировоззрения, он должен выбрать один из этих типов для этой способности. Например, если он выбирает «Ад» (злой, принципиальный план) для своей способности господства на местности, он может выбрать «зло» или «принципиальность», что означает, что его атаки обходят доброе или хаотичное снижение урона соответственно. Альтернативно, если местные существа выбранного им плана уязвимы к определенному особому материалу (например, холодному железу или серебру), он может выбрать, чтобы его оружие обходило уменьшение урона, как если бы оно было этим особым материалом. Если он выбирает этот план более одного раза для своей способности господства на местности, его атаки считаются дополнительным мировоззрением или специальным материалом (например, «добро и серебро» или «хаос и добро»). Болото (Swamp): Горизонтоход получает виброчувствительность на расстоянии 30 футов. Он должен быть как минимум 5-го уровня, чтобы выбрать эту способность. Подземелье (Underground): Горизонтоход получает ночное зрение на дальность 60 футов. Если у него уже ночное зрение 60 футов, его дальность увеличивается на 60 футов. Город (Urban): Горизонтоход получает приворот (гуманоид) как псевдозаклинание количество раз в день, равное 3 + модификатор Мудрости персонажа (уровень заклинателя равен уровню персонажа). Вода (Water): Горизонтоход получает скорость плавания 20 футов. Если у него уже есть естественная скорость плавания, его скорость плавания увеличивается на +20 футов.","name":"Господство на местности (Terrain Dominance)"},{"description":"На 10-м уровне горизонтоход знакомится со всеми возможными ландшафтами и чувствует себя комфортно. Его бонус на всех излюбленных местностях увеличивается на +2, и он рассматривает все остальные местности, как если бы они были излюбленными местностями (бонус +2). Если естественные условия температуры или погоды требуют проверки или испытания, он автоматически добивается успеха. Все союзники в пределах 60 футов от него получают бонус +2 к этим проверкам и испытаниям; если горизонтоход находится на местности, выбранной для способности мастерство местности, этот бонус увеличивается до +4.","name":"Мастер всех земель (Master of All Lands) (Св)"}],"hitDie":"d10","kind":"prestige","nameEn":"Horizon Walker","nameRu":"Горизонтоход","originalUrl":"https://pathfinder.family/class/prestige/horizonWalker","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Излюбленная местность","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Излюбленная местность, мастер местности","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Господство на местности","will":"+1"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Излюбленная местность, мастер местности","will":"+1"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Излюбленная местность","will":"+2"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Господство на местности, мастер местности","will":"+2"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"Излюбленная местность","will":"+2"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Излюбленная местность, мастер местности","will":"+3"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Господство на местности","will":"+3"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Излюбленная местность, мастер всех земель","will":"+3"}],"requirements":[{"kind":"Навыки (Skills)","text":"Знание (география) 6 рангов."},{"kind":"Черты (Feats)","text":"Двужильный."}],"role":"Горизонтоходы обладают точностью и стойкостью, чтобы противостоять боевым действиям на передовой. Они также обладают навыками и способностями, позволяющими стать отличными разведчиками, часто беря на себя роль первого члена группы, оказавшегося в опасности, и последнего выходящего из нее. Конечно, горизонтоходы блистают в приключениях в областях, которые соответствуют их любимым ландшафтам, но многие из приемов, которые они приобретают в определенных регионах, находят применение в широком диапазоне ситуаций, позволяя ему быть более мобильным и находчивым, чем типичные бойцы.","skillRanks":"6 + Инт","slug":"horizonWalker"},{"alignment":"Пираты Внутреннего моря часто хаотичны и редко бывают добрыми, но могут иметь любое отличающееся от принципиального мировоззрение.","book":"Pirates of the Inner Sea","classSkills":["Запугивание","Знание (природа)","Лазание","Оценка","Плавание","Профессия"],"features":[{"description":"Пираты Внутреннего моря умеют обращаться абордажными саблями, крюками, рапирами и короткими мечами. Пираты Внутреннего моря не получают мастерство ношения брони.","name":"Ношение брони и обращение с оружием"},{"description":"Эта способность в точности похожа на способность плута с тем же названием. Дополнительный наносимый урон увеличивается на +1d6 на 4-м уровне и каждые три последующих уровня. Если Пират Внутреннего моря получает бонус к атаке исподтишка от другого класса, то бонусы за урон складываются.","name":"Атака исподтишка (Экс)"},{"description":"По мере того как пират Внутреннего моря развивает свое мастерство, он учится целому ряду приемов, которые помогают ему в его работе. Он получает пиратский прием на 4-м уровне и каждые три уровня после этого. Глубоководный пират не может выбрать никакой прием более одного раза. Приемы, отмеченные звездочкой, добавляют эффекты к атаке исподтишка Пирата Внутреннего моря. Только один из этих приемов может быть применен к атаке, и решение должно быть принято до того, как будет сделан бросок атаки. Классический Дуэлянт (Экс): Пират Внутреннего моря получает бонус компетентности +1 к броскам атаки, сделанным с помощью абордажной сабли, рапиры или короткого меча. Глубокий вдох (Экс): Пират Внутреннего моря может задержать дыхание на несколько раундов, равное трем его модификаторам Выносливости, прежде чем он должен начать делать проверку Выносливости. Пить бесплатно (Экс): Эта способность предполагает, что Пирата Внутреннего моря восхищаются или боятся в тавернах, которые он часто посещает. Пират Внутреннего моря выбирает одну таверну за уровень в этом классе как \"любимую таверну\". Когда он находится в любимой таверне, Пират Внутреннего моря пьет бесплатно. Кроме того, он получает бонус +2 обстоятельства на проверки Дипломатии и Запугивания в таких тавернах. Дальновидец (Экс): Пираты по очереди служат дозорными. Пират Внутреннего моря, обладающий такой способностью, вдвое сокращает любые штрафы за расстояние при проверке Внимания, когда он находится по крайней мере в 10 футах от земли или над палубой корабля. Удар по руке* (Экс): Пират Внутреннего моря может ослабить руку противника с оружием, ударив с помощью атаки исподтишка. Когда он наносит урон от атаки исподтишка против противника, этого противника становится легче разоружить. До конца следующего хода пирата любой, кто попытается разоружить этого противника, получает бонус +2 к проверке боевого маневра (разоружение). Быстрая оценка (Экс): Пират Внутреннего моря должен время от времени быстро определять самые ценные предметы, которые следует забирать. Он оценивает предмет как сопутствующее действие и может определить самый ценный предмет в сокровищнице как основное действие. Такелажная обезьяна (Экс): Некоторые пираты становятся опытными в лазании по канатам и такелажу. Эта способность дает Пирату Внутреннего моря бонус +2 при проверке Лазания при использовании веревки, для подъема. Кроме того, при использовании веревки, взбираясь вверх, Пират Внутреннего моря может двигаться с половиной своей скорости. (Приняв штраф -5, он может двигаться со своей обычной скоростью.) Штормовой матрос (Экс): Пират Внутреннего моря относится ко всем штормам так, как если бы они были одной категорией меньше, при проверках плавания и навигации. (Это преимущество складывается с чертой Понимание Шторма и другими эффектами, связанными с ветровыми условиями.) Он может сделать проверку Акробатики, чтобы двигаться с нормальной скоростью по неровной земле, и он не получает штрафов за любые проверки Акробатики из-за слегка скользких, слегка неустойчивых или умеренно неустойчивых условий. Такелажник ветра (Экс): Пират Внутреннего моря научился хитрому искусству лавирования. С помощью проверки Профессии (моряк) СЛ 15 он может увеличить базовую скорость своего корабля на 5 футов в течение 1 часа.","name":"Пиратские приемы (Экс)"},{"description":"На 6-м, 8-м и 9-м уровнях Пират Внутреннего моря может выбрать один из следующих продвинутых приемов вместо пиратского приема. Взрыв скорости (Экс): Пират Внутреннего моря учится выжимать скорость из своего корабля, когда это действительно важно. С проверкой Профессии (моряк) СЛ 20 он удваивает базовую скорость своего корабля на 1 раунд. Он может использовать эту способность один раз в день. Оборонительный альпинист (Экс): Пират Внутреннего моря не теряет свой бонус ловкости к КБ при лазании. Страшное наступление* (Экс): если Пират Внутреннего моря наносит урон атакой исподтишка, он может сделать проверку Запугивания в качестве прерывающего действия, чтобы деморализовать поврежденного противника. Подсечка* (Экс): Пират Внутреннего моря учится сбивать с ног своих противников, когда они шатаются от боли от его точных атак. Если Пират Внутреннего моря наносит урон с помощью атаки исподтишка, он может совершить маневр Сбивание с ног на поврежденного противника в качестве прерывающего действия. Все обычные правила применяются для сбивания с ног, и такие черты, как Сбивание с ног+, изменяют атаку. Судовые полномочия (Экс): В качестве действия полного раунда один раз в день Пират Внутреннего моря может выкрикивать приказы своему экипажу. Все союзники в радиусе 30 футов от Пирата Внутреннего моря, которые могут услышать его, получают бонус морали +1 на броски атаки или при проверке определенного навыка на 1 раунд за уровень Пирата Внутреннего моря. Пират Внутреннего моря указывает, какой бонус применяется, когда он использует эту способность, и не может изменять бонус в течение всего срока действия этой способности.","name":"Продвинутые приемы (Экс)"}],"hitDie":"d8","kind":"prestige","nameEn":"Inner Sea Pirate","nameRu":"Пират Внутреннего моря","originalUrl":"https://pathfinder.family/class/prestige/innerSeaPirate","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Атака исподтишка +1d6","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Пиратский прием","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Пиратский прием","will":"+1"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Атака исподтишка +2d6","will":"+1"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Пиратский прием","will":"+2"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Продвинутый прием, Пиратский прием","will":"+2"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Атака исподтишка +3d6","will":"+2"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Пиратский прием","will":"+3"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Пиратский прием","will":"+3"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Атака исподтишка +4d6","will":"+3"}],"requirements":[{"kind":"Мировоззрение","text":"Любое непринципиальное."},{"kind":"Навыки","text":"Оценка 5, Профессия (моряк) 5, Плавание 5."}],"role":"В то время как многие моряки в водах Авистана и Гарунда работают пиратами, те, кто достаточно опытен, чтобы получить уровень в этом престиж-классе, проявляют больше таланта, чем обычные палубный экипаж. Пираты Внутреннего моря часто управляют своими собственными кораблями; те, кто обычно не служит офицерами или на борту печально известных кораблей под руководством опытных капитанов.","skillRanks":"6 + Инт","slug":"innerSeaPirate"},{"alignment":"Большинство хранителей тайн не утруждает себя бессмысленными философскими категориями вроде этики, а потому придерживается нейтральных, нейтральных добрых и нейтральных злых взглядов на мир.","book":"Core Rulebook","classSkills":["Дипломатия","Дрессировка","Знание (высший свет)","Знание (география)","Знание (инженерное дело)","Знание (история)","Знание (краеведение)","Знание (магия)","Знание (планы)","Знание (подземелья)","Знание (природа)","Знание (религия)","Исполнение","Использование магических устройств","Колдовство","Лечение","Оценка","Языкознание"],"features":[{"description":"Хранители тайн не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"На определенных уровнях персонаж получает дополнительные заклинания в день, как если бы он получил уровень в том классе заклинателя, который у него был до взятия престиж-класса. Он не получает иных преимуществ от того класса, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у хранителя тайн до получения престиж-класса было несколько классов, дающих доступ к заклинаниям, он должен выбрать, к какому из классов он будет добавлять уровни для определения количества заклинаний в день.","name":"Заклинания в день"},{"description":"На 1 уровне и на каждом втором уровне после этого (3, 5, 7 и 9) хранитель тайн выбирает один открывшийся ему секрет из таблицы секретов хранителя тайн. Чтобы выяснить, какие из этих секретов ему доступны, нужно сложить модификатор Интеллекта хранителя тайн и его уровень. Каждый секрет можно выбрать только один раз.","name":"Секрет"},{"description":"На 2 уровне хранитель тайн прибавляет половину своего уровня к проверкам любого Знания. Кроме того, Знание для него перестает считаться навыком, требующим обучения. Модификаторы этой особенности складываются с модификаторами эрудиции барда.","name":"Премудрость"},{"description":"Хранитель тайн может выучить любой новый язык на 4 и на 8 уровне.","name":"Дополнительный язык"},{"description":"На 6 уровне хранитель тайн обретает глубочайшее понимание волшебных предметов. Каждый раз, когда хранитель тайн пытается изучить магический предмет и узнать его свойства, он получает бонус +10 (ситуативный) к проверкам Колдовства.","name":"Великая премудрость (Экс)"},{"description":"На 10 уровне знания хранителя тайн становятся поистине обширными. Раз в день он может использовать эту способность, чтобы воспроизвести эффекты заклинания знание легенд или анализ чар. Если эта способность используется как знание легенд, время сотворения равно 1 минуте, вне зависимости от того, сколько информации уже известно об объекте иссдедования.","name":"Истинная премудрость (Экс)"}],"hitDie":"d6","kind":"prestige","nameRu":"Хранитель тайн","originalUrl":"https://pathfinder.family/class/prestige/loremaster","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+0","special":"Секрет","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Премудрость","spellcasting":"+1 уровень к имеющемуся классу","will":"+1"},{"bab":"+1","fort":"+1","level":3,"ref":"+1","special":"Секрет","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+1","level":4,"ref":"+1","special":"Дополнительный язык","spellcasting":"+1 уровень к имеющемуся классу","will":"+2"},{"bab":"+2","fort":"+2","level":5,"ref":"+2","special":"Секрет","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":6,"ref":"+2","special":"Великая премудрость","spellcasting":"+1 уровень к имеющемуся классу","will":"+3"},{"bab":"+3","fort":"+2","level":7,"ref":"+2","special":"Секрет","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":8,"ref":"+3","special":"Дополнительный язык","spellcasting":"+1 уровень к имеющемуся классу","will":"+4"},{"bab":"+4","fort":"+3","level":9,"ref":"+3","special":"Секрет","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"},{"bab":"+5","fort":"+3","level":10,"ref":"+3","special":"Истинная премудрость","spellcasting":"+1 уровень к имеющемуся классу","will":"+5"}],"requirements":[{"kind":"Навыки","text":"Два любых Знания по 7 пунктов в каждом."},{"kind":"Черты","text":"Три любые метамагические и/или созидательные черты, а также Эксперт (знание (любое))."},{"kind":"Заклинания","text":"Способность творить семь любых заклинаний школы прорицания, одно из которых должно быть не ниже 3 круга."}],"role":"Жизнь хранителя тайн проходит в учении, исследованиях и длительных экспедициях. Хотя первые два занятия и обеспечивают им в народе репутацию книжных червей, последнее волей-неволей вынуждает искать взаимовыгодного сотрудничества с бывалыми путешественниками и искателями приключений, способными обеспечить безопасность экспедиции и самого ученого в обмен на доступ к его невероятно обширным познаниям и колдовскому искусству. Многие хранители тайн попрекают своих коллег, предпочитающих отсиживаться в уютной тишине храмов и библиотек, указывая на то, что в книгах можно найти лишь устаревшие сведения и что новое знание следует извлекать из окружающего мира самостоятельно. Эти наиболее активные из хранителей тайн нередко присоединяются к группам искателей приключений, считая путешествие лучшим способом пополнить сокровищницу знаний.","skillRanks":"4 + Инт","slug":"loremaster"},{"book":"Inner Sea World Guide","classSkills":["Блеф","Верховая езда","Выживание","Дипломатия","Дрессировка","Запугивание","Знание (высший свет)","Знание (краеведение)","Знание (планы)","Изворотливость","Маскировка","Оценка","Проницательность","Ремесло","Скрытность","Языкознание"],"features":[{"description":"низший храмовник умеет обращаться с любым простым и любым особым оружием. Он умеет носить все виды брони и щитов.","name":"Ношение брони и обращение с оружием"},{"description":"при всех своих недостатках низший храмовник искусный боец, сражающийся с демонами Мировой Язвы. На 1 уровне низший храмовник получает бонус +1 ко всем проверкам атаки оружием и проверкам урона оружием против хаотичных злых потусторонних существ. Он получает такой же бонус ко всем испытаниям Воли против способностей хаотичных злых потусторонних существ. На 4 уровне эти бонусы увеличиваются до +2, на 7 уровне - до +3 и до +4 - на 10 уровне.","name":"Поборник (Экс)"},{"description":"низший храмовник умеет вставать на сторону победителя и с лёгкостью переметнется к врагу, если это ему выгодно. Он может исчезнуть в одном месте и появиться в другом, обзаведясь новыми связями и союзниками, не марая при этом своей репутации. Даже попавшись на противозаконном деянии, он легко уходит от обвинений. Низший храмовник получает бонус +2 ко всем проверкам Блефа н Маскировки и к проверкам Языкознания при подделке документов. Низший храмовник никогда не получает штрафа к значению Лидерства за частые путешествия, надменность, жестокость и потерю имеющихся соратников или последователей. Он может вдвое быстрее привлечь новых последователей взамен утраченных.","name":"Смена флага (Экс)"},{"description":"низший храмовник сочетает благородное соперничество и рыцарский устав с постыдными манерами кабацкого драчуна. Он не брезгует никакими уловками. Низший храмовник не получает штрафов за неумение обращаться с оружием к проверке атаки импровизированным оружием. Он получает бонус +2 ко всем проверкам боевых маневров. Кроме того, каждый раз, когда он подтверждает критический удар, низший храмовник может не наносить дополнительный урон, а вместо этого совершить бросок d6 и применить соответствующий эффект из таблицы ниже: Если критический множитель равен хЗ, длительность эффекта удваивается. Если критический множитель х4, длительность утраивается.","name":"Нечестный бой (Экс)"},{"description":"эта способность работает точно так же, как аналогичная способность плута. На 8 уровне наносимый дополнительный урон увеличивается на 1d6. Если низший храмовник получает бонус к атаке исподтишка из другого источника, бонусы к урону суммируются.","name":"Атака исподтишка (Экс)"},{"description":"по мере повышения уровня низший храмовник должен наконец решить, насколько строго он желает следовать своей клятве и идеалам добра и порядка, которые исповедуют поборники Иомедэй. Если он выбирает путь света, то может игнорировать принципиальный или добрый аспект своего мировоззрения (выберите один) при определении зависящего от мировоззрения магического эффекта (например, снижая урон от нечестивой погибели или нечестивого оружия, маскируя свое мировоззрение от определения мировоззрения (добро) или игнорируя некоторые эффекты магического круга против добра). Он также получает бонус +2 (ситуативный) к проверкам Дипломатии против существ принципиального или доброго подтипов. Если же низший храмовник выбирает путь тьмы, он игнорирует в своем мировоззрении хаос или зло и получает бонус к Дипломатии против существ хаотичного или злого подтипов.","name":"Путь света/путь тьмы (Св)"},{"description":"на 5 уровне низший храмовник может отступить в качестве основного действия, но при этом он двигается только со своей обычной скоростью (без удвоения).","name":"Отступить - не значит сдаться"},{"description":"каждый раз, когда низший храмовник убивает врага или приводит его в состояние при смерти атакой в ближнем бою, он может немедленно в качестве быстрого действия предпринять еще одну атаку тем же оружием с тем же модификатором атаки. Эта дополнительная атака может быть направлена на любую доступную цель. Низший храмовник получает бонус к урону этой атаки быстрым действием, равный своему уровню персонажа.","name":"Безжалостность (Экс)"},{"description":"на 9 уровне низший храмовник может предпринять отступление в качестве сопутствующего действия, но при этом он двигается только со своей обычной скоростью (без удвоения).","name":"Прощальный поклон (Экс)"},{"description":"на 10 уровне низший храмовник должен сделать окончательный выбор, каким духовным путём следовать. Он может скрыть второй аспект своего мировоззрения для защиты от основанных на мировоззрении магических эффектов, аналогично особенности путь света/путь тьмы. Низший храмовник может на 5 уровне выбрать путь тьмы, а на 10 уровне - путь искупления (или наоборот). После того как низший храмовник делает выбор между проклятием и искупление» он приобретает потустороннего соратника, подходящего его нынешнему мировоззрению, как если бы он получил черту Лидерство. Потусторонний соратник немедленно является перед низшим храмовником и присягает ему на верность. Если соратник погибает, низший храмовник должен выждать неделю, прежде чем призывать нового. Если у низшего храмовника уже есть черта Лидерство, он получает к значению Лидерства бонус +1. Если он заменяет соратника, полученного согласно черте Лидерство, потусторонним соратником, максимальный уровень потустороннего соратника может быть не на 2, а всего на 1 ниже уровня самого персонажа в классе храмовника.","name":"Проклятие/искупление (Св)"}],"hitDie":"d10","kind":"prestige","nameEn":"Low Templar","nameRu":"Низший храмовник","originalUrl":"https://pathfinder.family/class/prestige/lowTemplar","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Поборник +1, смена флага","will":"+0"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Нечестный бой","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Атака исподтишка +1d6","will":"+1"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Поборник +2","will":"+1"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Отступить - не значит сдаться, путь света/путь тьмы","will":"+2"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Безжалостность","will":"+2"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"Поборник +3","will":"+2"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Атака исподтишка +2d6","will":"+3"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Прощальный поклон","will":"+3"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Поборник +4, проклятие/искупление","will":"+3"}],"requirements":[{"kind":"Черты","text":"Бой верхом, Уверенное владение оружием (любое особое оружие)."},{"kind":"Навыки","text":"Блеф 5, Верховая езда 5, Знание (высший свет или планы) 2."}],"skillRanks":"2 + Инт","slug":"lowTemplar"},{"alignment":"Мотивы теургов редко имеют отношение к альтруизму и филантропии - в основном они склонны придерживаться нейтрального, нейтрального доброго или нейтрального злого мировоззрения. Принципиальные теурги, нейтральные, добрые и злые, встречаются куда реже - именно они склонны использовать свою силу на благо общества или для контроля над ним. Хаотичные теурги еще более редки, поскольку этот путь требует строжайшей самодисциплины.","book":"Core Rulebook","classSkills":["Знание (магия)","Знание (религия)","Колдовство","Проницательность"],"features":[{"description":"Теурги не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"Достигнув нового уровня в престиж-классе теурга, персонаж повышает эффективный уровень двух своих основных классов заклинателя - одного мистического и одного сакраkьного. Он не получает иных преимуществ от этих классов, кроме дополнительных ячеек заклинаний в день, знания новых чар (для спонтанных заклинателей) и увеличения УЗ. Если у теурга до получения престиж-класса было несколько классов, дающих доступ к заклинаниям одного типа, он должен выбрать, к какому из классов он будет добавлять уровни для определения количества заклинаний в день.","name":"Заклинания в день"},{"description":"Теург может подготавливать и творить любые известные ему заклинания, используя ячейки заклинаний любого из своих классов заклинателя. Заклинание, подготовленное при помощи этой способности, занимает ячейку на один круг выше обычного. Если заклинание, подготовленное при помощи этой способности, доступно заклинателю и как сакрааьное, и как мистическое, его нельзязя творить как заклинание более низкого круга с помощью этой способности. На 1 уровне теург может подготавливать заклинания 1 круга одного из своих классов в ячейках 2 круга другого своего класса. На каждом нечетном уровне после этого круг заклинаний, на который действует эта способность, повышается, вплоть до максимального 5 круга на 9 уровне (их теургу придется готовить как заклинания 6 круга). Компоненты заклинаний при этом остаются прежними, но само заклинание творится в соответствии с правилами того класса, для которого оно было подготовлено. Спонтанные заклинатели могут сотворять таким образом только уже подготовленные заклинания класса, подготавливающего чары, даже если это заклинание уже было сотворено. Например, жрец/чародей/теург может использовать эту способность для спонтанного сотворения благословения как одного из чародейских заклинаний 2 круга, но только если персонаж подготовил это благословение как сакральное заклинание 1 круга, и неважно, творил он его в этот день или еще нет.","name":"Комбинирование заклинаний (Св)"},{"description":"На 10 уровне теург получает возможность сотворить два заклинания разных классов одновременно. Оба заклинания должны иметь одинаковое время сотворения. Параметры каждого из заклинаний теург задает независимо. Цель, на которую воздействуют оба заклинания, получает штраф -2 к испытаниям против каждого из них. Сам же теург при этом получает +2 к проверкам УЗ для преодоления УкМ. Теург может использовать эту способность один раз в день.","name":"Синтез заклинаний (Св)"}],"hitDie":"d6","kind":"prestige","nameRu":"Теург","originalUrl":"https://pathfinder.family/class/prestige/mysticTheurge","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+0","special":"Комбинирование заклинаний (1 круг)","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+1"},{"bab":"+1","fort":"+1","level":3,"ref":"+1","special":"Комбинирование заклинаний (2 круг)","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+2"},{"bab":"+2","fort":"+1","level":4,"ref":"+1","special":"","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+2"},{"bab":"+2","fort":"+2","level":5,"ref":"+2","special":"Комбинирование заклинаний (3 круг)","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+3"},{"bab":"+3","fort":"+2","level":6,"ref":"+2","special":"","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+3"},{"bab":"+3","fort":"+2","level":7,"ref":"+2","special":"Комбинирование заклинаний (4 круг)","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+4"},{"bab":"+4","fort":"+3","level":8,"ref":"+3","special":"","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+4"},{"bab":"+4","fort":"+3","level":9,"ref":"+3","special":"Комбинирование заклинаний (5 круг)","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+5"},{"bab":"+5","fort":"+3","level":10,"ref":"+3","special":"Синтез заклинаний","spellcasting":"+1 уровень мистического заклинателя; +1 уровень сакрального заклинателя","will":"+5"}],"requirements":[{"kind":"Навыки","text":"Знание (магия) 3, Знание (религия) 3."},{"kind":"Заклинания","text":"Способность творить сакральные и мистические заклинания 2 круга."}],"role":"Теург - полезный участник любой группы искателей приключений, универсальный источник атакующих, защитных и лечебных заклинаний. Теурги путешествуют по всему миру в поисках священных артефактов, знаний о магии и божественных откровений. Большинство из них не имеет ничего против компании опытных искателей приключений, цели которых не слишком конфликтуют с их собственными.","skillRanks":"2 + Инт","slug":"mysticTheurge"},{"alignment":"Мировоззрение летописца Искателей в немалой степени определяет его мотивацию. Добрые персонажи чаще всего считают свою миссию важным, благородным делом, нейтральные склонны придерживаться идеи сохранения знаний ради самих знаний, в то время как злых интересует слава и богатство.","book":"Core Rulebook","classSkills":["Блеф","Верховая езда","Внимание","Выживание","Дипломатия","Запугивание","Знание (высший свет)","Знание (география)","Знание (инженерное дело)","Знание (история)","Знание (краеведение)","Знание (магия)","Знание (планы)","Знание (подземелья)","Знание (природа)","Знание (религия)","Изворотливость","Исполнение","Использование магических устройств","Ловкость рук","Маскировка","Оценка","Проницательность","Языкознание"],"features":[{"description":"Летописцы Искателей не обучаются обращению с оружием и доспехами.","name":"Ношение брони и обращение с оружием"},{"description":"Эта способность действует как одноименная классовая способность, а общий уровень барда для нее в данном случае равен сумме уровней каждого из классов, дающих к ней доступ.","name":"Эрудиция барда (Экс)"},{"description":"Летописец Искателей собирает не только знания, но и материальные свидетельства, прихватывая на память то одно, то другое. В результате при нем всегда имеется некоторое количество не определенного заранее снаряжения общей стоимостью 100 зм за уровень летописца. Это может быть что угодно, в том числе свитки и зелья (но не другие волшебные предметы), - главное, чтобы предмет помещался в рюкзак. В качестве действия полного хода летописец может порыться у себя в карманах и вытащить оттуда нужный ему предмет - стоимость предмета вычитается из общей суммы неопределенного снаряжения, рассованного по карманам летописца. Вес этого предмета не может превышать 10 фунтов. Когда сумма исчерпается, летописец утратит возможность использовать эту способность до тех пор, пока его глубокие карманы не будут наполнены вновь. Для этого ему понадобится несколько часов и достаточно денег, чтобы восполнить потраченное вплоть до максимума в 100 зм за уровень летописца. Кроме того, если летописец потратит 1 час на упаковку вещей, он получит +4 к значению Силы для подсчета веса легкой нагрузки. Хотя вес максимальной нагрузки при этом не увеличится, багаж, уложенный с умом, значительно облегчает жизнь. Наконец, летописец получает +4 к проверкам Ловкости рук, когда пытается спрятать на себе какой-нибудь небольшой предмет.","name":"Глубокие карманы (Экс)"},{"description":"Персонаж использует значение своего уровня летописца Искателей как модификатор к проверкам Языкознания и Профессии (писец), а также к проверкам Использования магических устройств для чтения свитков или иных волшебных предметов, снабженных текстами. Летописец может разбирать зашифрованные тексты при помощи Языкознания в качестве действия, требующего полного хода. Кроме того, он может без броска брать результат 10 на проверках Языкознания и Профессии (писец), даже если имеются отвлекающие и угрожающие факторы.","name":"Мастер-писец (Экс)"},{"description":"Начиная со 2 уровня один раз в день (и еще по разу в день за каждые два уровня после 2) летописец Искателей получает возможность повторно пройти испытание против любого длительного воздействия, которое он уже провалил в прошом раунде, даже если в обычной ситуации последствия этого провала нельзя бьло бы отменить. Эта способность не работает против мгновенных воздействий и воздействий, вообще не подразумевающих прохождения испытаний.","name":"Будет о чем рассказать (Экс)"},{"description":"На 2 уровне летописец Искателей вырабатывает великолепное чувство направления, умение пользоваться древними картами и прокладывать удобные маршруты по пересеченной местности. Летописец получает +5 к проверкам Выживания, которые он проходит, чтобы не заблудиться, а также к проверкам Интеллекта, которые он проходит, чтобы избавиться от эффекта заклинания лабиринта. Кроме того, при подсчете скорости путешествия летописец всегда использует множитель местности, соответствующий «дороге или тропинке», даже если никакой дороги или тропинки нет и в помине. Эта особенность работает как при пеших, так и при верховых переходах. Если летописец успешно пройдет проверку Выживания со СЛ 15, он может распространить эффект этой способности на своих спутников из расчета один спутник на уровень летописца.","name":"Проводник (Экс)"},{"description":"На 3 уровне летописец получает способность, которая действует как одноименная классовая способность барда. Эффективным уровнем барда для этой особенности считается уровень летописца - 2. К этому прибавляются эффективные уровни барда других классов, дающих доступ к этой особенности..","name":"Выступление барда (Св)"},{"description":"Начиная с 3 уровня летописец Искателей, оказывая помощь товарищу, дает ему +4 вместо +2 к проверкам навыков, атаке или защите.","name":"Отличный помощник (Экс)"},{"description":"На 4 уровне летописец Искателей получает возможность написать историю столь запоминающуюся и столь волнующую, что эффект, который она окажет на читателя, будет сродни эффекту выступления барда. Чтобы создать эпос, летописец должен решить, сколько раундов выступления барда он потратит в процессе его написания. Эпос будет действовать вдвое меньше (максимальная длительность эпоса - 10 раундов). В данном случае также требуется проверка навыка, но не Исполнения, как обычно, а Профессии (писец). Эпос подействует только на того, кто его прочитает, но сам эффект будет ровно таким же, как и от обычного выступления. Любые черты, которые оказывают влияние на выступления барда, работают и в случае с эпосами летописца. Записанный эпос сохраняет свои волшебные свойства на протяжении 1 дня за уровень летописца Искателей (или пока его кто-нибудь не прочтет, в зависимости от того, что случится раньше). Написание эпоса занимает 1 час, а применение требует действия полного хода.","name":"Эпос (Св)"},{"description":"Летописцы Искателей воздействуют на мир, контролируя информацию и оказывая влияние на общественное мнение. На 5 уровне летописец получает возможность использовать выступление барда, чтобы, бросив в лицо человеку самые чудовищные оскорбления, наложить на него эффект заклинания погибель, как если бы летогшсец Искателей был жрецом того же уровня. Это языковой эффект. Летописец может также очернить (или обелить) репутацию цели (отдельной личности или целой группы) в глазах широкой публики. Эта разновидность выступления барда в целом воспроизводит эффект заклинания захватывающая речь, но по истечении представления те, кто провадил испытание Воли, меняют свое отношение к цели выступления на одну ступень (в худшую или в лучшую сторону - решать летописцу). Этот эффект длится 1 день за каждый уровень летописца Искателей.","name":"Закулисная кампания (Экс)"},{"description":"На 6 уровне летописец Искателей получает возможность использовать выступление барда, чтобы позволить своему союзнику тут же предпринять дополнительное сопутствующее действие (помимо всех остальных действий, доступных ему в этом раунде). На 9 уровне летописец может вместо этого позволить своему союзнику тут же предпринять дополнительное основное действие.","name":"Побуждение к действию (Св)"},{"description":"На 7 уровне один раз в неделю летописец Искателей может предпринять действие, требующее полного хода, чтобы призвать 2d4 варваров 4 уровня, как при использовании бронзового рога Вальхаллы. Эти призванные варвары, совершенно похожие на людей, - конструкции, беспрекословно подчиняющиеся летописцу. У каждого из них при себе имеется стандартное для варваров стартовое снаряжение.","name":"Героическое предание (Св)"},{"description":"На 8 уровне написанные летописцем Искателей слова обретают свою истинную силу. Эта способность работает в точности как способность летописца эпос, за исключением того, что великий эпос, прочитанный вслух, срабатывает как полноценное выступление барда, но цели представления определяет не бард, а чтец, и вместо Харизмы барда используется Харизма чтеца.","name":"Великий эпос (Св)"},{"description":"На 10 уровне один раз в неделю летописец Искателей может предпринять действие, требующее полного хода, чтобы призвать 1d4+1 варваров 5 уровня, как при использовании железного рога Вальхаллы, - эти призванные варвары похожи на людей, но являются бестелесными конструкциями (получают 50% урона от материальных источников и не получают урона вовсе, если источник немагический). Они облачены в +2 клепаные кожаные доспехи, вооружены +1 двуручными топорами призрачного касания (позволяющими наносить полный урон бестелесным противникам) и беспрекословно подчиняются летописцу. Для летописца и его союзников эти мертвецы являются в образе благородных небесных воителей, но врагам гнев этих древних героев внушает ужас. Противники летописца должны пройти испытание Воли (СЛ 15 + модификатор Харизмы летописца Искателей). Каждый, кто провалит испытание, оказывается потрясенным на 1 раунд за каждого призванного варвара.","name":"Баллада о славной смерти (Св)"}],"hitDie":"d8","kind":"prestige","nameRu":"Летописец Искателей","originalUrl":"https://pathfinder.family/class/prestige/pathfinderChronicler","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Эрудиция барда, глубокие карманы, мастер-писец","will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Будет о чем рассказать, проводник","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Выступление барда, отличный помощник","will":"+2"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Эпос","will":"+2"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Закулисная кампания","will":"+3"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Побуждение к действию (сопутствующее)","will":"+3"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Героическое предание","will":"+4"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Великий эпос","will":"+4"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Побуждение к действию (основное)","will":"+5"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Баллада о славной смерти","will":"+5"}],"requirements":[{"kind":"Навыки","text":"Языкознание 3, Исполнение (красноречие) 5, Профессия (писец) 5."},{"kind":"Особое","text":"Персонаж должен составить и продать некий письменный или устный труд, за который другой персонаж (не персонаж игрока) заплатит сумму не менее 50 зм. Свитки и иные волшебные предметы не в счет."}],"role":"Важность миссии летописца Искателей нередко делает его лидером группы путешественников, да и сами приключения нередко завязываются и развиваются вокруг его бесконечных изысканий.","skillRanks":"8 + Инт","slug":"pathfinderChronicler"},{"book":"Inner Sea World Guide","classSkills":["Акробатика","Блеф","Внимание","Запугивание","Знание (высший свет)","Знание (краеведение)","Знание (природа)","Знание (религия)","Изворотливость","Лазание","Лечение","Маскировка","Оценка","Проницательность","Скрытность"],"features":[{"description":"ассасин Красного Богомола умеет обращаться с любым простым оружием и всеми видами одноручного особого оружия, а также с лёгкими доспехами, но не щитами.","name":"Ношение брони и обращение с оружием (Weapon and Armor Proficiency)"},{"description":"ассасин Красного Богомола умеет творить мистические заклинания иллюзии и превращения из списка заклинаний чародея/волшебника. Он может сотворить любое известное ему заклинание, не готовя его заранее. Чтобы освоить или применить заклинание, ассасин Красного Богомола должен иметь значение Харизмы не менее 10 + круг заклинания. Его дополнительные заклинания связаны с Харизмой, и СЛ испытания против заклинаний ассасина Красного Богомола равна 10 + круг заклинания + модификатор его Харизмы (если есть). Его набор заклинаний крайне ограничен - на каждом уровне Красный Богомол получает одно или несколько новых заклинаний, как указано в таблице «Заклинания ассасина Красного Богомола». На 4, 6, 8 и 10 уровне он может выучить по одному новому заклинанию взамен уже известного. Новое заклинание должно быть того же круга, что и старое. Как сказано выше, ассасину Красного Богомола доступны только заклинания иллюзии и превращения из списка чародея/волшебника, но по мере повышения уровня к списку известных заклинаний добавляется некоторое число новых. Когда эти заклинания становятся доступны, он не выучивает их автоматически - их нужно выбрать в добавление к уже известным заклинаниям. На 2 уровне ассасин Красного Богомола добавляет к своему списку заклинаний непроглядный туман и верный удар. На 4 уровне он добавляет тьму и призыв стаи тварей. На 6 уровне - облако тумана и увидеть невидимое. На 8 уровне - ясновидение/яснослышание и паралич (гуманоид). На 10 уровне - дверь в пространстве и манипуляцию памятью.","name":"Заклинания (Spells)"},{"description":"эта способность действует точно так же, как аналогичная способность плута. Если у ассасина Красного Богомола уже есть модификаторы за атаку исподтишка, бонусы к урону суммируются.","name":"Атака исподтишка (Sneak Attack) (Экс)"},{"description":"на 1 уровне ассасин Красного Богомола получает дополнительную черту Привычное оружие (зазубренная сабля). На 5 уровне он получает дополнительную черту Уверенное владение оружием+ (зазубренная сабля), а на 7 уровне - дополнительную черту Привычное оружие+ (зазубренная сабля).","name":"Владение саблей (Sabre Fighting) (Экс)"},{"description":"на 2 уровне ассасин Красного Богомола осваивает особый стиль убийства, характерный для этого ордена. Чтобы начать атаку, ассасин должен находиться в пределах 30 футов, держать зазубренную саблю (или сабли) остриём вниз, подобно конечностям богомола, и быть видимым для своей жертвы. Атака молельщика выполняется в качестве основного действия. Если жертва проваливает испытание Воли, то становится заворожённой ассасином (СЛ 10 + уровень ассасина Красного Богомола + его модификатор Харизмы; если он использует две зазубренные сабли, СЛ повышается еще на 2). Концентрируясь, ассасин может поддерживать завораживающий эффект. При появлении любой другой угрозы (кроме самого воздействующего на нее ассасина) жертва может снова попытаться пройти испытание, что освободиться от эффекта завораживания. В любой момент после 3 раундов ассасин может нанести жертве добивающий удар, если она еще заворожена. Активация или концентрация на атаке молельщика не провоцирует внеочередной атаки.","name":"Атака молельщика (Prayer Attack) (Св)"},{"description":"на 3 уровне ассасин Красного Богомола получает способность создавать вокруг себя завесу красного тумана. Он может использовать эту способность столько раз в день, сколько составляет его модификатор Выносливости (минимум 1/день), в качестве сопутствующего действия. Эффект красного савана длится 1 раунд за каждый уровень в классе. Он даёт бонус +1 (уклонение) к КБ и быстрое исцеление, равное модификатору Выносливости персонажа (минимум быстрое исцеление 1). Такой туман не развеивается ветром. Если ассасин Красного Богомола убит, пока эта способность активна, он может выбрать, остаться ли трупом или развеяться облачком красного тумана, оставив после себя только снаряжение, чтобы враги не получили останки.","name":"Красный саван (Red Shroud) (Св)"},{"description":"раз в день на 4 уровне ассасин Красного Богомола может призвать усиленного гигантского богомола-бестию, 1d3 гигантских богомола-бестии или 1d4+1 гигантских богомолов, как при призыве чудовища V. Он может мысленно руководить действиями призванных тварей в качестве свободного действия. Все призванные этим псевдозаклинанием богомолы - кроваво-красные и не имеют бонуса народа к проверкам Скрытности в лесу.","name":"Призыв богомола (Summon Mantis) (Пс)"},{"description":"на 5 уровне ассасин Красного Богомола получает способность чувствовать, если существо, убитое им в течение года, вернулось к жизни (при условии что оба находятся на одном плане).","name":"Чутьё на воскрешение (Resurrection Sense) (Св)"},{"description":"на б уровне ассасин Красного Богомола может раз день в качестве основного действия превратиться в кроваво-красного гигантского богомола, как если бы он сотворил заклинание облик вредителя II (уровень заклинателя равен уровню в классе ассасина Красного Богомола). Помимо стандартных изменений Силы, Ловкости и естественной брони от этого заклинания, ассасин Красного Богомола получает от гигантского богомола следующие экстраординарные способности: ночное зрение 60 футов, захват, выпад, жвалы и внезапный удар. Но ассасину не передаются невосприимчивость к эффектам, воздействующим на разум, и модификаторы народа к Вниманию и Скрытности, присущие богомолу. Если во время превращения он держит в руке волшебную зазубренную саблю, то магические улучшения этого оружия применяются к соответствующей атаке когтем; если он держит две сабли, то улучшения каждого оружия применяются к атаке соответствующим когтем. Кровавый богомол (Blood Mantis): на 8 уровне его атака когтем при попадании дополнительно вызывает 1d6 урона от кровотечения. Ассасин Красного Богомола также получает СУ 5/добро, пока находится в этом облике. Богомол смерти (Death Mantis): на 10 уровне всякий раз, когда ассасин Красного Богомола использует для атаки жвалы, цель успешней атаки получает 1 отрицательный уровень. За каждый наложенный таким образом отрицательный уровень ассасин Красного Богомола получает 5 временных ПЗ, которые сохраняются в течение 1 часа. СЛ испытания для снятия отрицательных уровней равна 20 + модификатор Выносливости ассасина Красного Богомола. Кроме того, СУ ассасина Красного Богомола повышается до 10/добро, пока он находится в этом облике.","name":"Облик богомола (Mantis Form) (Св)"},{"description":"на 8 уровне ассасин Красного Богомола приобретает способность становиться эфирным в качестве свободного действия. Он может использовать эту способность столько раз в день, сколько составляет его модификатор Выносливости (минимум 1/день), - сразу, как только его атакуют оружием или вынуждают пройти испытание Реакции. Ассасин Красного Богомола должен выбрать, активировать эту способность перед проверкой атаки оружием или перед объявлением эффектов заклинания. Это позволит ассасину Красного Богомола с вероятностью 50% избежать урона от атаки или действия заклинания.","name":"Растворение в воздухе (Fading) (Св)"},{"description":"на 9 уровне ассасин Красного Богомола получает возможность трижды в день применять ползучую погибель в качестве псевдозаклинания. Эта версия заклинания призывает стаю ядовитых богомолов, но в остальном действует аналогично.","name":"Богомолья погибель (Mantis Doom) (Пс)"}],"hitDie":"d8","kind":"prestige","nameEn":"Red Mantis Assassin","nameRu":"Ассасин Красного Богомола","originalUrl":"https://pathfinder.family/class/prestige/redMantisAssassin","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Атака исподтишка +1d6, владение саблей 1","spells":["1"],"will":"+1"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Атака молельщика","spells":["2"],"will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Красный саван","spells":["3"],"will":"+2"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Призыв богомола, атака исподтишка +2d6","spells":["3","1"],"will":"+2"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Чутье на воскрешение, владение саблей 2","spells":["4","2"],"will":"+3"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Облик богомола","spells":["4","3"],"will":"+3"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Атака исподтишка +3d6, владение саблей 3","spells":["4","3","1"],"will":"+4"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Облик кровавого богомола, растворение а воздухе","spells":["4","4","2"],"will":"+4"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Богомолья погибель","spells":["5","4","3"],"will":"+5"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Облик богомола смерти, атака исподтишка +4d6","spells":["5","4","3","1"],"will":"+5"}],"requirements":[{"kind":"Мировоззрение","text":"принципиальное злое."},{"kind":"Навыки","text":"Внимание 5, Запугивание 5, Скрытность 5."},{"kind":"Черты","text":"Бдительность, Обращение с экзотическим оружием (зазубренная сабля), Парное оружие, Уверенное владение оружием (зазубренная сабля)."}],"skillRanks":"6 + Инт","slug":"redMantisAssassin","spellCircles":[1,2,3,4]},{"book":"Adventurer's Guide","classSkills":["Блеф","Внимание","Дипломатия","Запугивание","Знание (высший свет)","Знание (краеведение)","Лазание","Полет","Проницательность"],"features":[{"description":"При проверке Запугивания на кроваво-красного ангела, на проверяющего накладывается штраф, равный двойному уровню ангела, на эту проверку.","name":"Закалённое сердце (Экс)"},{"description":"Кроваво-красный ангел воспринимается как будто она использует черту Парное оружие каждый раз, когда она орудует длинным мечом и щитом. Она может брать черты, требующие Парное оружие, несмотря на как таковое отсутствие этой черты или нужного количества Ловкости, однако все эти черты могут быть использованы лишь тогда, когда Кроваво-красный ангел держит в руках длинный меч и щит.","name":"Щит Девы (Экс)"},{"description":"Инициация Компании Эриний довольно внушительна, поэтому все кроваво-красные ангелы так же верны Его Адскому Величеству, как Серые Девы верны Королеве Илеосе. На 2-ом уровне, Кроваво-красный ангел опирается на идеологическое воспитание, тактические тренировки и преданность тирании для развития могущественных талантов. Она выбирает дисциплину из следующего списка на 2-ом уровне и каждые 2 уровня после этого. Рокировка: Ангел может совершить 5-футовый шаг в клетку союзника. При совершении этого действия, ангел меняется с союзником местами, не тратя при этом действий. Нападение: При совершении атаки полного хода, Кроваво-красный ангел может принять штраф -2 к атакам в ближнем бою на 1 раунд. В этом случае, при первом же попадании по существу того же размера, что и ангел, или меньше, ангел может предпринять попытку протаранить противника на 5 футов назад. Она получает бонус +2 к МБМ при совершении этого манёвра и не провоцирует внеочередные атаки, но взамен она не может отбросить противника дальше, чем на 5 футов. Также ангел может переместиться в точку, где стоял противник, подвергшийся тарану, не провоцируя внеочередные атаки. Яростная охотница: Кроваво-красный ангел добавляет свой модификатор Силы вместо модификатора Ловкости при стрельбе из лука. Убийца семей: Кроваво-красный ангел получает заклятого врага (гуманоид (человек) +2), идентичного способности следопыта. Если у ангела уже имеется этот заклятый враг, бонус увеличивается на 2. Беспощадная резня: Когда Кроваво-красный ангел попадает по существу, находящемуся в панике или страхе, или по существу с отрицательным ПЗ атакой ближнего боя, она может нанести дополнительно 1d8 + уровень ангела урона по этому существу. Клинок Королевы: Бонус Мастерства владения оружием (тяжёлые клинки) Кроваво-красный ангела повышается на 1. Ангел обязан быть как минимум 4-ого уровня в этом классе и иметь Мастерство владения оружием (тяжёлые клинки) для взятия этой дисциплины. Она также может выбрать эту дисциплину ещё раз на 8-ом уровне или выше. Непреклонный: Кроваво-красный ангел получает СУ 1/- при ношении полных лат. Персонаж обязан иметь хотя бы 6-ой уровень в этом классе для взятия этой дисциплины. СУ возрастает на 1 на 8-ом и 10-ом уровнях. СУ из этого класса не складывается с другими СУ из других источников.","name":"Дисциплина тирана (Экс)"},{"description":"На 3-ем уровне, Кроваво-красный ангел получает Мастерство ношения брони, расценивая свой уровень как уровень воина при ношении полных лат. Если эта способность была получена из других источников, бонусы Мастерства ношения брони складываются, но только если ангел носит полные латы.","name":"Бронированный ангел (Экс)"},{"description":"Вдова Иллюзии, первая Королева Ночи, в качестве одолжения Компании Эриний, даровала им глаза, способные прорваться через ложь. На 5-ом уровне, Кроваво-красный ангел получает Бдительность как дополнительную черту и бонус +4 к испытаниям Воли против иллюзий. Также, раз в день в качестве быстрого действия ангел может нанести себе 1d4 урона Харизме, чтобы получить преимущества заклинания истинное зрение на количество раундов, равное уровню ангела.","name":"Око Махаталлы (Св)"},{"description":"Хотя многие ангелы не подвергаются соблазну, Конец Невинности дарует им влияние над другими несмотря ни на что. На 7-ом уровне, Кроваво-красный ангел получает бонус +4 к проверкам Дипломатии и Запугивания против существ того же типа что и ангел. Один раз в день, Кроваво-красный ангел может использовать подчинение гуманоида как псевдозаклинание (УЗ = уровень ангела).","name":"Тайна Ардад Лили (Экс или Пс)"},{"description":"Подарок Нашей Леди Боли - свобода. Свобода от ужаса и боли, горя и страха. На 9-ом уровне, Кроваво-красный ангел получает Крепкий орешек в качестве дополнительной черты. Также, она получает бонус +4 на испытания против эффектов эмоций и боли, а ещё она невосприимчива к эффектам страха.","name":"Пустота Долорас (Экс)"},{"description":"Лучшие из ангелов получают уважение Королевы Эриний Эйсет, что превращает их в адских прислужников. На 10-ом уровне, тип Кроваво-красного ангела меняется на потусторонний (злой, экстрапланарный, принципиальный), а Преисподняя становится её родным планом. Она получает сопротивление огню 30, телепатию (дистанция - 50 футов), а также сумеречное зрение как особую способность чудовищ. Черные крылья отрастают на спине ангела, давая ей полёт (скорость - 50 футов) с хорошей манёвренностью.","name":"Ангел Эйсет (Св)"}],"hitDie":"d10","kind":"prestige","nameEn":"Sanguine Angel","nameRu":"Кроваво-Красный Ангел","originalUrl":"https://pathfinder.family/class/prestige/sanguineAngel","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Закалённое сердце, Щит Девы","will":"+1"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Дисциплина тирана","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Бронированный ангел","will":"+2"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Дисциплина тирана","will":"+2"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"Око Махаталлы","will":"+3"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Дисциплина тирана","will":"+3"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"Тайна Ардад Лили","will":"+4"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Дисциплина тирана","will":"+4"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Пустота Долорас","will":"+5"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"Дисциплина тирана, Ангел Эйсет","will":"+5"}],"requirements":[{"kind":"Мировоззрение","text":"принципиальное злое, принципиальное нейтральное или нейтральное злое."},{"kind":"Ношение брони","text":"возможность носить тяжёлую броню."},{"kind":"БМА","text":"+5."},{"kind":"Черты","text":"Стальная воля, Удар щитом+, Уверенное владение оружием (длинный меч)."},{"kind":"Пол","text":"Женский."},{"kind":"Язык","text":"Дьявольский."}],"skillRanks":"2 + Инт","slug":"sanguineAngel"},{"alignment":"Благодаря своей (отчасти заслуженной) репутации двуличных обманщиков, танцорами теней редко становятся приверженцы принципиальных взгдялов; более того, большая часть их талантов направлена как раз на то, чтобы избежать бдительного ока представителей закона. Несмотря на связь с тьмой, танцоры теней не испытывают склонности ни к злу, ни к добру. Тьма для них - просто тьма; это их инструмент, и этому инструменту не присуще ни одно из тех качеств, которыми наделяют его непосвященные.","book":"Core Rulebook","classSkills":["Акробатика","Блеф","Внимание","Дипломатия","Изворотливость","Исполнение","Ловкость рук","Маскировка","Скрытность"],"features":[{"description":"Танцоры теней умеют обращаться с дубинками, арбалетами (ручными, легкими и тяжелыми), кинжалами (любыми), дротиками, булавами, моргенштернами, боевыми посохами, рапирами, мягкими дубинками, короткими луками (простыми и композитными), короткими мечами и легкими доспехами, но не умеют обращаться со щитами.","name":"Ношение брони и обращение с оружием"},{"description":"Танцор теней может использовать навык Скрытность, даже если ему негде спрятаться от чужих глаз. Для этого ему нужно просто находиться не далее 10 футов от области низкой освещенности (не считая его собственной тени).","name":"Мастер незаметности (Св)"},{"description":"Если танцор теней успешно проходит испытание Реакции, в результате которого наносимый ему урон уменьшается вдвое, он вообще не получает этого урона. Эта способность достается ему на 2 уровне и действует, только если танцор теней облачен в легкие доспехи (или вообще обходится без брони).","name":"Уклонение (Экс)"},{"description":"На 2 уровне танцор теней получает ночное зрение, которое действует на расстоянии 60 футов. Если у него уже есть ночное зрение, область его действия увеличивается на 30 футов.","name":"Ночное зрение (Экс)"},{"description":"Начиная со второго уровня танцора теней нельзя застать врасплох, и он не теряет положительный модификатор Ловкости к КБ, если его противник невидим. Танцор теней все же теряет его, если не может двигаться, а также если противник успешно применит против него финт. Если у танцора теней уже есть особенность невероятное укдонение, полученная от другого класса, он автоматически получает невероятное уклонение+.","name":"Невероятное уклонение (Экс)"},{"description":"На 3 уровне (и на каждом следующем третьем уровне) танцор теней получает способность, которая работает точно так же, как одноименная классовая способность плута. Танцор теней не может выбирать один и тот же прием дважды. Если у него уже есть доступ к продвинутым приемам, он может выбрать как простой, так и продвинутый прием.","name":"Воровской прием"},{"description":"Когда танцор теней достигает 3 уровня, он получает возможность создавать зрительные иллюзии. Эта способность действует в точности как заклинание немой образ, УЗ которого равно уровню танцора теней. Персонаж может воспользоваться этой способностью один раз в день за каждые два уровня танцора теней. СЛ испытания этой способностью связана с Харизмой заклинателя.","name":"Теневая иллюзия (Пс)"},{"description":"На 3 уровне танцор теней получает возможность призвать тень - призрачную нежить. В отличие от большинства своих сородичей, эта сущность обладает тем же мировоззрением, что и призвавший ее персонаж, и не умеет порождать отродий. Призванная тень получает +4 к испытаниям Воли, которые она проходит, чтобы уменьшить урон от позитивной энергии, и ее нельзя изгнать или взять под контроль, как любую другую тень. Эта тень разумна, обладает даром речи и становится верным спутником персонажа. Количество ПЗ тени равно половине общего количества ПЗ танцора теней. Значения БМА, Стойкости, Реакции и Воли тень перенимает от своего хозяина. В остальном параметры сущности полностью совпадают с параметрами тени. Если эта тень будет уничтожена или если танцор теней изгонит ее по собственной воле, он должен пройти испытание Стойкости со СЛ 15. При успехе ничего не происходит. При провале танцор теней получает один постоянный отрицательный уровень. Уничтоженную или изгнанную тень можно призвать повторно не ранее чем через 30 дней.","name":"Призыв тени (Св)"},{"description":"На 4 уровне танцор теней может создавать теневые подобия различных существ и явлений. Эта способность действует в точности как заклинание теневое воплощение, УЗ которого соответствует уровню танцора теней. Персонаж может воспользоваться этой способностью один раз в день и еще по разу в день за каждые два уровня после 4 (2 раза в день на 6 уровне, 3 раза в день на 8 и 4 раза в день на 10). По достижении 10 уровня эта способность начинает действовать как заклинание высшее теневое воплощение. СА испытаний против этой способности зависит от Харизмы заклинателя.","name":"Зов теней (Пс)"},{"description":"На 4 уровне танцор теней получает способность путешествовать между тенями, как при помощи двери в пространстве. Эта способность работает, только если начальная и конечная точка прыжка располагаются на клетках с низким уровнем освещенности. При помощи этой способности танцор теней может совершить любое количество прыжков в день, главное, чтобы их суммарная дистанция не превышала 40 футов. Это может быть как один прыжок длиной 40 футов, так и четыре прыжка длиной 10 футов каждый. Обратите внимание, что прыжок менее чем на 10 футов с точки зрения дневного лимита считается прыжком на 10 футов. За каждые два уровня после 4 дневной лимит прыжков удваивается (80 футов на 6 уровне, 160 футов на 8 и 320 футов на 10).","name":"Теневой прыжок (Св)"},{"description":"Начиная с 5 уровня раз в день танцор теней получает шанс избежать удара, который стал бы для него смертельным. Эта способность работает точно так же, как одноименный продвинутый воровской талант.","name":"Смягчение удара (Экс)"},{"description":"Начиная с 5 уровня танцора теней больше нельзя взять в тиски. Плут при этом не может атаковать его исподтишка, взяв в тиски, если только уровень плута не превышает уровень танцора теней на 4. Если у танцора теней уже есть полученная от другого класса особенность невероятное уклонение (см. выше), уровни в этих классах складываются для определения того, какой минимальный уровень плута нужен для взятия персонажа в тиски.","name":"Невероятное уклонение+ (Экс)"},{"description":"На 7 уровне танцор теней становится менее восприимчивым к заклинаниям очарования. Эта способность работает точно так же, как одноименный продвинутый воровской тадант.","name":"Скользкий разум (Экс)"},{"description":"На 8 уровне танцор теней получает возможность взывать к разрушительной силе теней. Эта способность работает в точности как заклинание теневое разрушение, УЗ которого соответствует уровню танцора теней. Персонаж может воспользоваться этой способностью один раз в день и еще раз в день начиная с 10 уровня. СЛ испытаний этой способностью связана с Харизмой заклинателя.","name":"Сила теней (Пс)"},{"description":"Эта способность, которую танцор теней получает на 10 уровне, работает точно так же, как уклонение (см. выше), за исключением того, что танцор теней, который проваливает испытание Ловкости, получает не весь причитающийся ему урон, а только половину.","name":"Уклонение+ (Экс)"},{"description":"На 10 уровне танцор теней, находящийся в области с низким уровнем освещенности, получает СУ 10/- и +2 (удача) ко всем испытаниям. Кроме того, если танцор теней наносит критический удар противнику, находящемуся в области низкой освещенности, противник слепнет на 1d6 раундов.","name":"Владыка теней (Св)"}],"hitDie":"d8","kind":"prestige","nameRu":"Танцор теней","originalUrl":"https://pathfinder.family/class/prestige/shadowdancer","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Мастер незаматности","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Уклонение, ночное зрение, невероятное уклонение","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Воровской прием, теневая иллюзия, призыв тени","will":"+1"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Зов теней, теневой прыжок 40 футов","will":"+1"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Смягчение удара, невероятное уклонение+","will":"+2"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Воровской прием, теневой прыжок 80 футов","will":"+2"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Скользкий разум","will":"+2"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Теневой прыжок 160 футов, сила теней","will":"+3"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Воровской прием","will":"+3"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Уклонение+, теневой прыжок 320 футов, владыка теней","will":"+3"}],"requirements":[{"kind":"Навыки","text":"Скрытность 5, Исполнение (танец) 2."},{"kind":"Черты","text":"Боевые рефлексы, Уворот, Подвижность."}],"role":"Танцоры теней отправляются на поиски приключений по самым разным причинам. Они считаются незаменимыми соратниками, их высоко ценятся за непревзойденное умение оставаться незамеченными и наносить удар там, где враг ожидает его меньше всего. Нет ничего удивительного в том, что в команде эти персонажи чаще всего играют роль разведчиков и шпионов.","skillRanks":"6 + Инт","slug":"shadowdancer"},{"alignment":"Любой может быть упрямым, как скала, и стремиться удержать одну точку любой ценой, поэтому стойкие защитники могут быть любого мировоззрения. Однако самоотверженность и практика, необходимые для изучения талантов стойкого защитника, легче даются персонажам с сильным уважением к порядку и организации, поэтому принципиальные стойкие защитники встречаются гораздо чаще, чем хаотичные.","book":"Advanced Player's Guide","classSkills":["Акробатика","Внимание","Запугивание","Лазание","Проницательность"],"features":[{"description":"Стойкий защитник умеет обращаться со всем простым и особым оружием, всеми типами доспехов и щитами (включая башенные).","name":"Ношение брони и обращение с оружием (Weapon and Armor Proficiency)"},{"description":"Стойкий защитник получает бонус уклонения к КБ, который начинается с +1 и увеличивается по мере повышения уровня защитника, пока не достигнет +4 на 10-м уровне.","name":"Бонус к КБ (AC Bonus) (Экс)"},{"description":"На 1-м уровне стойкий защитник может принять защитную стойку, позицию готовности и решимости, подобной трансу. Стойкий защитник может сохранять эту стойку в течение количества раундов в день, равного 4 + его модификатор Выносливости. На каждом уровне после 1-го он может сохранять стойку еще 2 раунда в день. Временное увеличение Выносливости, например, полученное от защитной стойки и заклинаний, таких как медвежья стойкость, не увеличивает общее количество раундов, в течение которых стойкий защитник может поддерживать защитную стойку в день. Стойкий защитник может войти в защитную стойку свободным действием. Общее количество раундов защитной стойки в день возобновляется после 8-часового отдыха, хотя эти часы не обязательно должны быть последовательными. Находясь в защитной стойке, стойкий защитник получает бонус уклонения +2 к КБ, бонус боевого духа +4 к его Силе и Выносливости, а также бонус боевого духа +2 к испытаниям Воли. Увеличение Выносливости дает стойкому защитнику 2 ПЗ за каждый КЗ, но эти ПЗ исчезают, когда защитная стойка заканчивается, и не теряются первыми, как временные ПЗ. Находясь в защитной стойке, стойкий защитник не может добровольно покинуть свою текущую позицию любыми способами (включая обычное движение, езду на животном, телепортацию или добровольное разрешение союзникам нести его). Если он занимает защитную стойку, находясь на движущемся транспортном средстве, которым он не управляет (например, повозке или корабле), он может сохранять стойку, даже если транспортное средство движется. Если стойкий защитник движется своими силами в результате успешного использования противником навыка Блеф или заклинания школы очарования, его стойка прекращается. Стойкий защитник может завершить свою защитную стойку свободным действием; после окончания стойки он утомлен на количество раундов, равное 2-кратному числу раундов, проведенных в стойке. Стойкий защитник не может принять новую защитную стойку, будучи утомленным или обессиленным, но в остальном может принимать стойку несколько раз в течение одного столкновения или боя. Если стойкий защитник теряет сознание, его защитная стойка немедленно прекращается, подвергая его смертельной опасности. Защитная стойка требует определенного уровня эмоционального спокойствия, и персонаж, находящийся в ярости, не может поддерживать ее (например, из-за особенности класса ярость или заклинания ярость).","name":"Защитная Стойка (Defensive Stance) (Экс)"},{"description":"По мере того, как стойкий защитник получает уровни, он усиливает свою защитную стойку. Начиная со 2-го уровня стойкий защитник получает защитную силу. Он получает еще одну защитную силу за каждые два уровня стойкого защитника, достигнутые после 2-го уровня. Стойкий защитник получает преимущества защитных сил только тогда, когда находится в защитной стойке, и некоторые из этих сил требуют от него действия в первую очередь. Если не указано иное, он не может выбрать отдельную силу более одного раза. Оплот (Bulwark) (Экс): Защитник добавляет свой штраф за доспехи в качестве бонуса к СЛ Блефа и проверкам Акробатики противников, чтобы пройти мимо него, не провоцируя внеочередную атаку при перемещения через пространство, которому он угрожает. Ясный ум (Clear Mind) (Экс): Стойкий защитник может перебросить неудачное испытание Воли. Эта способность используется как прерывающее действие после попытки первого испытания, но до того, как ведущий раскроет результаты. Стойкий защитник должен выбрать второй результат, даже если он хуже. Эту силу можно использовать только один раз за защитную стойку. Бесстрашная защита (Fearless Defense) (Экс): Находясь в защитной стойке, стойкий защитник невосприимчив к потрясению и испугу. Чтобы выбрать эту силу, он должен быть как минимум 4-го уровня. Останавливающий удар (Halting Blow) (Экс): Если движение противника в угрожаемой зоне защитника провоцирует внеочередную атаку, и стойкий защитник успешно поражает противника атакой, движение противника немедленно прекращается. Противник не может снова двигаться до своего следующего хода, но все еще может выполнить остальную часть своих действий. Стойкий защитник должен выбрать силу Оплот, прежде чем выбрать Останавливающий удар. Неподвижный (Immobile) (Экс): Находясь в защитной стойке, стойкий защитник добавляет уровень своего класса к своему ЗБМ против любых боевых маневров таран, вторжение, притягивания и толкания, а также попыток захвата, чтобы сдвинуть его с места. Стойкий защитник должен быть как минимум 4-го уровня, чтобы выбрать эту способность. Повышение снижения урона (Increased Damage Reduction) (Экс): Снижение урона стойкого защитника от этого класса увеличивается на 1/-. Это увеличение всегда активно, пока стойкий защитник находится в защитной стойке. Он может выбирать эту силу до двух раз. Её эффекты суммируются. Стойкий защитник должен иметь как минимум 6-й уровень, прежде чем выбирать эту защитную силу. Перехват (Intercept) (Экс): Один раз в раунд в качестве прерывающего действия, когда оружие ближнего или дальнего боя успешно поразит соседнего союзника, стойкий защитник может выбрать, чтобы это оружие поразило его, а не намеченную цель. Атака автоматически попадает в стойкого защитника, независимо от его КБ или любого действующего шанса промаха, и он страдает от обычных последствий атаки. Внутренняя стойкость (Internal Fortitude) (Экс): Находясь в защитной стойке, стойкий защитник невосприимчив к дезориентации и тошноте. Могучая устойчивость (Mighty Resilience) (Экс): Стойкий защитник автоматически сводит на нет дополнительный урон от одного успешного критического удара или атаки исподтишка, а также другие способности или эффекты, которые зависят от успешного критического удара или атаки исподтишка (например, ослепление от Критического ослепления или кровотечение от атаки исподтишка). Стойкий защитник получает от атаки только обычный урон. Эту способность можно использовать только один раз за защитную стойку. Стойкий защитник должен быть как минимум 6-го уровня, чтобы выбрать эту способность. Обновленная защита (Renewed Defense) (Экс): В качестве основного действия стойкий защитник исцеляет 1d8 единиц урона + модификатор Выносливости. За каждые два уровня, которых стойкий защитник достиг выше второго, это исцеление увеличивается на 1d8, до максимума 5d8 на 10-м уровне. Эту силу можно использовать только один раз в день и только в защитной стойке. Разбуженная защита (Roused Defense) (Экс): Стойкий защитник может занять защитную стойку, даже если он утомлен. Сохраняя защитную стойку после использования этой способности, он невосприимчив к состоянию утомления. Как только эта стойка заканчивается, он обессилен на 10 минут за раунд, проведенный в защитной стойке. Разгром (Smash) (Экс): Находясь в защитной стойке, стойкий защитник может совершить дополнительную атаку за раунд, которая представляет собой либо удар щитом, либо крушащий удар (даже если обычно у него нет атаки крушащим ударом). Если используется как часть действия полной атаки, дополнительная атака производится с полным базовым модификатором атаки стойкого защитника -5. Разгром наносит 1d4 единиц урона (если стойкий защитник среднего размера или 1d3, если небольшого) плюс половину модификатора Силы персонажа. Персонаж может совершить эту атаку как часть действия по поддержанию захвата или освобождению от него; эта атака разрешается до того, как будет сделана проверка захвата. Если атака попадает, любые проверки захвата, сделанные стойким защитником против цели в этом раунде, получают бонус +2. Неожиданный удар (Unexpected Strike) (Экс): Стойкий защитник может провести внеочередную атаку против врага, который движется в любую клетку, которой угрожает стойкий защитник, независимо от того, провоцирует ли это движение обычно внеочередную атаку. Эту силу можно использовать только один раз за стойку. Стойкий защитник должен иметь как минимум 4-й уровень, прежде чем выбрать эту способность.","name":"Защитные силы (Defensive Powers) (Экс)"},{"description":"На 3 уровне стойкий защитник обретает способность реагировать на опасность быстрее мысли. Его нельзя застать врасплох и он не теряет бонус Ловкости к КБ, если противник невидим. Но он все же теряет этот бонус, если не может двигаться, а также если противник успешно применит против него финт. Если стойкий защитник уже получил эту особенность от другого класса, он автоматически приобретает вместо нее особенность невероятное уклонение+ (см. ниже).","name":"Невероятное уклонение (Uncanny Dodge) (Экс)"},{"description":"На 5-м уровне стойкий защитник получает СУ 1/-. На 7-м уровне это СУ увеличивается до 3/-, а на 10-м уровне — до 5/-. Снижение урона от разных источников не суммируется; однако стойкий защитник 5-го уровня или выше, который получает СУ от брони (но не из какого-либо другого источника), увеличивает свое классовое СУ на значение СУ брони. Таким образом, стойкий защитник 7-го уровня, носящий адамантиновый полный латный доспех (СУ 3/-), имеет СУ 6/-.","name":"Снижение урона (Damage Reduction) (Экс)"},{"description":"С 7 уровня стойкого защитника нельзя взять в тиски. Плут при этом не может атаковать стойкого защитника исподтишка, взяв его в тиски, если только его уровень плута не превышает уровень стойкого защитника на 4. Если у персонажа уже есть полученная от другого класса особенность невероятное уклонение (см. выше), уровни в этих классах складываются для определения того, какой минимальный уровень плута нужен для взятия персонажа в тиски.","name":"Невероятное уклонение+ (Improved Uncanny Dodge) (Экс)"},{"description":"На 9 уровне стойкий защитник может корректировать свою позицию, сохраняя при этом защитную стойку. Находясь в защитной стойке, он может делать один шаг на 5 футов каждый раунд, не теряя преимущества этой стойки.","name":"Мобильная защита (Mobile Defense) (Экс)"},{"description":"Один раз в день, находясь в защитной стойке, стойкий защитник может совершить одну ближнюю атаку по противнику в пределах досягаемости в ответ на атаку, которая снизит его ПЗ до отрицательных, заставит его потерять сознание или убьет. Например, у стойкого защитника остается 1 ПЗ, когда его кусает красный дракон; защитник может использовать эту способность, даже если в противном случае укус дракона убил бы его мгновенно. Если атака попала, бросьте кубик урона для атаки дважды и сложите результаты вместе, но не умножайте бонусы урона от Силы, способностей оружия (например, огненное) или урона, основанного на точности (например, атаки исподтишка). Этот бонусный урон не умножается при критическом ударе (хотя другие бонусы к урону умножаются нормально). Как только атака защитника завершена, он испытывает обычный эффект атаки, вызвавшей эту способность.","name":"Последнее слово (Last Word) (Экс)"}],"hitDie":"d12","kind":"prestige","nameEn":"Stalwart Defender","nameRu":"Стойкий защитник","originalUrl":"https://pathfinder.family/class/prestige/stalwartDefender","progression":[{"bab":"+1","fort":"+1","level":1,"ref":"+0","special":"Защитная Стойка","will":"+1"},{"bab":"+2","fort":"+1","level":2,"ref":"+1","special":"Защитная сила","will":"+1"},{"bab":"+3","fort":"+2","level":3,"ref":"+1","special":"Невероятное уклонение","will":"+2"},{"bab":"+4","fort":"+2","level":4,"ref":"+1","special":"Защитная сила","will":"+2"},{"bab":"+5","fort":"+3","level":5,"ref":"+2","special":"СУ 1/-","will":"+3"},{"bab":"+6","fort":"+3","level":6,"ref":"+2","special":"Защитная сила","will":"+3"},{"bab":"+7","fort":"+4","level":7,"ref":"+2","special":"СУ 3/-, Невероятное уклонение+","will":"+4"},{"bab":"+8","fort":"+4","level":8,"ref":"+3","special":"Защитная сила","will":"+4"},{"bab":"+9","fort":"+5","level":9,"ref":"+3","special":"Мобильная защита","will":"+5"},{"bab":"+10","fort":"+5","level":10,"ref":"+3","special":"СУ 5/-, Защитная сила, последнее слово","will":"+5"}],"requirements":[{"kind":"БМА (Base Attack Bonus)","text":"+7."},{"kind":"Черты (Feats)","text":"Уворот, Двужильный, Живучесть."},{"kind":"Особое (Special)","text":"Обращение с лёгкой и средней броней."}],"role":"Стойкие защитники - мастера ближнего боя, стремящиеся доказать, что лучшее нападение - это хорошая защита. Стойких защитников обычно можно найти на передовой, они занимают позиции, чтобы прикрыть своих союзников, прыгают в проломы в построениях противника и удерживают их открытыми для других, а также охраняют более уязвимых союзников, действуя как мобильные укрепления, стабильные точки в постоянно меняющемся хаосе боя.","skillRanks":"2 + Инт","slug":"stalwartDefender"},{"book":"Adventurer's Guide","classSkills":["Акробатика","Блеф","Внимание","Дипломатия","Запугивание","Знание (высший свет)","Знание (история)","Знание (краеведение)","Знание (магия)","Изворотливость","Исполнение","Использование магических устройств","Колдовство","Лазание","Ловкость рук","Маскировка","Механика","Оценка","Плавание","Проницательность","Скрытность","Языкознание"],"features":[{"description":"Дьявол Весткрауна умеет обращаться с длинными мечами.","name":"Ношение брони и обращение с оружием"},{"description":"Возвращение Ародена в Весткраун было предсказано давно, но его смерть подтвердила ненадёжность пророчества, и жителям города пришлось адаптироваться. Сегодня Весткраун чтит наследие Ародена в мемориальных статуях, соборах и других памятных местах. Совет Воров, в свою очередь, обучает своих членов в обращении с излюбленным оружием Ародена - длинным мечом, который тот использовал для достижения ловкости и опытности, избегая великой силы. Дьявол Весткрауна может использовать черту Фехтование с длинным мечом, подходящим под размер дьявола, пока держит его в одной руке, несмотря на то, что это оружие не является одноручным.","name":"Классическая тренировка (Экс)"},{"description":"Группа, известная как основатели Ародена - покровители Весткрауна. Настолько сильные традиции эта группа запечатлела в городе, что даже относительно недавнее посвящение Принцу Тьмы Челиакса не стёрло свой знак на Сумеречном Городе. Дьявол Весткрауна учится призывать силу основателей, наслаждаясь властью над городом, коей могут похвастаться немногие. На 1-ом уровне, Дьявол Весткрауна получает очки благосклонности. Их кол-во равно уровню Дьявола + мод. Интеллекта, Мудрости или Харизмы (выбирается наивысший модификатор). В дополнение к силам, получаемым от Основателей (см. ниже), Дьявол Весткрауна может использовать 1 очко благосклонности, чтобы добавить половину своего уровня (минимум +1) на проверку любого навыка без траты действия. Дьявол Весткрауна обязан заявить об использовании этой способности до проверки навыка, и он использует бонус способности единожды на каждую проверку навыка. Очки благосклонности восстанавливаются каждое утро после 8 часового отдыха. Пока Дьявол Весткрауна получает уровни, он учится взывать к силам, вдохновлёнными некоторыми из Основателей. УЗ для псевдозаклинаний равен уровню Дьявола, а эффекты (включая псевдозаклинания), позволяющие пройти испытание, имеют СЛ равную 10 + уровень Дьявола + мод. Интеллекта, Мудрости или Харизмы (выбирается наивысший модификатор). Око Вадруса (Св): Покровитель стеклодувов позволяет Дьяволу превращать стены в стекло. На 1-ом уровне, тратя 1 очко благосклонности и весь свой ход, Дьявол Весткрауна может увидеть устройство замка, ловушки или любого другого схожего механизма к которому он прикоснётся. Дьявол получает бонус +4 к проверкам Механики для взлома этого механизма. На 4-ом уровне Дьявол Весткрауна может использовать Око Вадруса, чтобы посмотреть сквозь любую дверь или стену, к которой он прислоняется, как будто часть этой стены или двери была прозрачной на 5 кв. футов. Этот эффект распространяется только на двери и стены толщиной не более 6 дюймов. Эта способность действует 1 раунд за уровень Дьявола. Руководство Круцизала (Св): Покровитель навигации направляет Дьявола Весткрауна, препятствуя преследованию. На 3-ем уровне, находясь в городской среде, Дьявол Весткрауна может потратить 1 очко благосклонности в качестве быстрого действия, чтобы получить бонус скорости +10 футов к его базовой скорости и бонус +4 к проверкам Акробатики и Скрытности на 1 минуту. Когда Дьявол Весткрауна тратит благосклонность для улучшения проверки навыка при погоне или преследовании, он добавляет 2d6 вместо 1d6 к этой проверке. Мастерство Адель (Пс): Покровитель деревянного мастерства делится своими навыками для своих творений. На 5-ом уровне, в качестве основного действия Дьявол Весткрауна может потратить 1 очко благосклонности для использования преображения дерева или слияния с деревом (работает как слияние с камнем, но для древесины любого размера или габаритов). Если Дьявол Весткрауна 8-ого уровня и выше, то он может использовать эту способность как проход сквозь стену для деревянных препятствий или как статую для превращения существа в деревянную статую (прочность 5). Щедрость Риксаны (Св): Взывая к Покровителю щедрости глубин, Дьявол учится навигации в подводных условиях. На 7-ом уровне Дьявол Весткрауна может потратить 1 очко благосклонности в качестве свободного действия для использования дыхания под водой на себя на 24 часа. Он также может поделиться этим эффектом с кем угодно, коснувшись его и дополнительно потратив 1 очко благосклонности. Восстановление Палмора (Пс): Покровитель возрождения делится своими навыками могущественного исцеления со своими последователями. На 8-ом уровне в качестве основного действия Дьявол Весткрауна может потратить 1 очко благосклонности для использования исцеления серьёзных ранений или низшего восстановления. Он также может потратить 3 очка благосклонности для использования разрушения чар или восстановления, потратив на это 1 минуту и дорогой материальный компонент по мере необходимости. Саван Дотары (Св): Опытный Дьявол Весткрауна получает благосклонность Покровителя Доттары (городской стражи). На 9-ом уровне Дьявол Весткрауна получает бонус +5 на проверки навыков для обнаружения городской стражи, бонус уклонения +2 к КБ против атак стражников и бонус +2 на все испытания против всех эффектов, созданных городской стражей. Эта способность постоянна до тех пор, пока у Дьявола Весткрауна есть хотя бы 1 очко благосклонности. Воплощение Ароденнамы (Св и Пс): Величайший монумент Весткрауна, Ароденнама, символизирует мёртвого бога человечества, и Дьявол Весткрауна может черпать вдохновение из этой высокой статуи, дабы воззвать к авторитету Ародена или же для достижения мастерства во владении клинком. На 10-ом уровне Дьявол Весткрауна может использовать эту способность для улучшения бросков атаки длинным мечом, как если бы это было проверкой навыка. В дополнение к этому в качестве действия полного хода Дьявол Весткрауна может потратить 2 очка благосклонности для использования внушения или потратить 5 очков для использования массового внушения, однако они будут действовать только на людей.","name":"Милость Основателей (Св)"},{"description":"На 2-ом уровне и каждые 2 уровня после Дьявол Весткрауна получает воровские приёмы. Дьявол рассматривает свой уровень равным уровню плута для определения возможных воровских талантов и их эффектов. На 6-ом уровне Дьявол Весткрауна может взять вместо воровского приёма продвинутый воровской приём. Или же, Дьявол Весткрауна может сосредоточиться на оккультном обучении. Тогда, каждый раз получая воровской приём от этой способности вместо него, его УЗ заклинаний экстрасенса увеличивается на 1. Дьявол Весткрауна может получить УЗ таким образом один раз и еще один раз на 6-м и 10-м уровнях.","name":"Секрет Совета"},{"description":"На 3-ем уровне Дьявол Весткрауна получает атаку исподтишка, идентичную способности плута. Её дополничельный урон равен 1d6, и он увеличивается на 1d6 на 6-ом и 9-ом уровнях.","name":"Атака исподтишка (Экс)"}],"hitDie":"d8","kind":"prestige","nameEn":"Westcrown Devil","nameRu":"Дьявол Весткрауна","originalUrl":"https://pathfinder.family/class/prestige/westcrownDevil","progression":[{"bab":"+0","fort":"+0","level":1,"ref":"+1","special":"Классическая тренировка, Милость Основателей (Око Вадруса (устройства))","will":"+0"},{"bab":"+1","fort":"+1","level":2,"ref":"+1","special":"Секрет Совета","will":"+1"},{"bab":"+2","fort":"+1","level":3,"ref":"+2","special":"Милость Основателей (Руководство Круцизала), Атака исподтишка +1d6","will":"+1"},{"bab":"+3","fort":"+1","level":4,"ref":"+2","special":"Секрет Совета, Милость Основателей (Око Вадруса (препятствия))","will":"+1"},{"bab":"+3","fort":"+2","level":5,"ref":"+3","special":"Милость Основателей (Мастерство Адель)","will":"+2"},{"bab":"+4","fort":"+2","level":6,"ref":"+3","special":"Секрет Совета, Атака исподтишка +2d6","will":"+2"},{"bab":"+5","fort":"+2","level":7,"ref":"+4","special":"Милость Основателей (Щедрость Риксаны)","will":"+2"},{"bab":"+6","fort":"+3","level":8,"ref":"+4","special":"Секрет Совета, Милость Основателей (Мастерство Адель, Восстановление Палмора)","will":"+3"},{"bab":"+6","fort":"+3","level":9,"ref":"+5","special":"Милость Основателей (Саван Дотары), Атака исподтишка +3d6","will":"+3"},{"bab":"+7","fort":"+3","level":10,"ref":"+5","special":"Секрет Совета, Милость Основателей (Воплощение Ароденнамы)","will":"+3"}],"requirements":[{"kind":"Мировоззрение","text":"Любое непринципиальное."},{"kind":"Черты","text":"Фехтование и любая из списка: Атлет, Бдительность, Лёгкая рука, Обманщик, Предрасположенность к магии, Проныра, Убедительность."},{"kind":"Религия","text":"Не поклоняется Норгорберу."},{"kind":"Навыки","text":"Знание (краеведение) 5, 5 пунктов в любых трёх из списка: Акробатика, Блеф, Знание (высший свет), Знание (история), Использование магических устройств, Лазание, Ловкость рук, Механика, Проницательность, Скрытность."}],"skillRanks":"6 + Инт","slug":"westcrownDevil"}]};
